fun main(args: Array<String>) {
    val n = readLine()!!.toInt()
    val s = readLine()!!


    var pattern = mutableListOf<String>()
    var pmap = mutableMapOf<String, Int>()
    if (n >= 2 && n <= 100) {

        for (i in 0..(n - 2)) {
            if (s.substring(i, i + 2) in pattern) {
                var count = pmap[s.substring(i, i + 2)]

                if (count != null) {
                    pmap[s.substring(i, i + 2)] = count + 1
                }
            } else {
                pattern.add(s.substring(i, i + 2))
                pmap.put(s.substring(i, i + 2), 1)
            }
        }
    }
    println(pmap.maxBy { it.value }?.key)
}

import java.util.Scanner;

fun main() {
    val input = Scanner(System.`in`);

    var n = readLine()!!.toInt()
    var str = readLine()!!.toCharArray()

    var mp = mutableMapOf<String, Int>();

    for(i in 0..(n-2)) {
        var s = (str?.get(i)?.toString()) + str?.get(i+1)?.toString();
        if (mp.containsKey(s)) {
            mp[s] = mp.getValue(s)+1;
        } else {
            mp.put(s, 1);
        }
    }

    var ans: String = "";
    var num: Int = 0;

    for((str, count) in mp) {
        if (count > num) {
            num = count;
            ans = str;
        }
    }
    println(ans);
}

fun twoGram(input: String) = input.windowed(2).groupingBy { it }.eachCount().maxBy { it.value }?.key

fun main(args: Array<String>) {
