import java.io.*
import java.math.BigInteger
import java.util.*
import kotlin.math.abs

data class Point(val x: Long, val y: Long)

fun solve(inn: InputReader, out: PrintWriter) {
    val x0 = inn.readLong()
    val y0 = inn.readLong()
    val ax = inn.readLong()
    val ay = inn.readLong()
    val bx = inn.readLong()
    val by = inn.readLong()
    val xs = inn.readLong()
    val ys = inn.readLong()
    val t = inn.readLong()

    val pts = mutableListOf<Point>()
    pts.add(Point(x0, y0))
    while (pts.last().x < Long.MAX_VALUE / 4 && pts.last().y < Long.MAX_VALUE / 4) {
        val (x, y) = pts.last()

        val cx = BigInteger.valueOf(x) * BigInteger.valueOf(ax) + BigInteger.valueOf(bx)
        if (cx >= BigInteger.valueOf(Long.MAX_VALUE / 4)) {
            break
        }
        val cy = BigInteger.valueOf(y) * BigInteger.valueOf(ay) + BigInteger.valueOf(by)
        if (cy >= BigInteger.valueOf(Long.MAX_VALUE / 4)) {
            break
        }

        pts.add(Point(x * ax + bx, y * ay + by))
    }

    var result = 0
    for (i in 0 until pts.size) {
        var x = xs
        var y = ys
        val dist = abs(x - pts[i].x) + abs(y - pts[i].y)
        if (dist > t) {
            continue
        }

        x = pts[i].x
        y = pts[i].y

        var impact = 1
        var remT = t - dist
        for (j in i - 1 downTo 0) {
            val dist = abs(x - pts[j].x) + abs(y - pts[j].y)
            if (dist > remT) {
                break
            }

            remT -= dist
            ++impact
            x = pts[j].x
            y = pts[j].y
        }

        for (j in i + 1 until pts.size) {
            val dist = abs(x - pts[j].x) + abs(y - pts[j].y)
            if (dist > remT) {
                break
            }

            remT -= dist
            ++impact
            x = pts[j].x
            y = pts[j].y
        }

        result = result.coerceAtLeast(impact)
    }

    out.println(result)
}

fun main() {
    val inn = InputReader(System.`in`)
