/** @author Spheniscine */
fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
    val x0 = readLong()
    val y0 = readLong()
    val ax = readLong()
    val ay = readLong()
    val bx = readLong()
    val by = readLong()

    val xs = readLong()
    val ys = readLong()
    val start = Point(xs, ys)
    val t = readLong()

    val nodes = generateSequence(Point(x0, y0)) { (x, y) ->
        Point(ax * x + bx, ay * y + by)
    }.takeWhile { (x, y) -> x <= xs + t && y <= ys + t }
        .filter { start.distance(it) <= t }
        .toList()

    var ans = 0
    fun findCandidate(seq: IntProgression) {
        var pos = start
        var k = 0
        var rem = t

        for(j in seq) {
            rem -= pos.distance(nodes[j])
            if(rem < 0) break
            k++
            pos = nodes[j]
        }

        if(k > ans) ans = k
    }

    for(i in nodes.indices) {
        findCandidate(i downTo 0)
        findCandidate(i until nodes.size)
    }

    println(ans)
}

