fun isLuckyNumber(number: Int): Boolean {
        var isLucky = false

        if (isDigitWith(number, Pair('4', '7')))
            isLucky = true
        else if (isDividedByLuckyNumber(number))
            isLucky = true

        return isLucky
    }

    private fun isDividedByLuckyNumber(number: Int): Boolean {
        var luckyNumber = 4
        while (number / luckyNumber >= 1) {
            if (isDividedBy(number, luckyNumber)) return true
            else luckyNumber = nextLuckyNumber(luckyNumber)
        }
        return false
    }

    fun nextLuckyNumber(preLuckyNumber: Int): Int {

        if (isNeedToIncreasedBitNumber(preLuckyNumber)) {
            val num = preLuckyNumber.toString().map { '4' }
            return String(num.toCharArray()).toInt() * 10 + 4
        } else {
            val digits = preLuckyNumber.toString().toCharArray()
            var isNotChanged = true
            val changedDigits =
                digits.reversed()
                        .map {
                            if (isNotChanged && it == '4') {
                                isNotChanged = false
                                '7'
                            } else it
                        }
                        .reversed()

            return String(changedDigits.toCharArray()).toInt()
        }
    }

    private fun isNeedToIncreasedBitNumber(preLuckyNumber: Int): Boolean {
        return (preLuckyNumber % 7) == 0
    }

private fun isDigitWith(number: Int, digits: Pair<Char, Char>): Boolean {
    val (c1, c2) = digits

    val numCharArray = number.toString().toCharArray()
    for (char in numCharArray) {
        if (char != c1 && char != c2)
            return false
    }
    return true
}

private fun isDividedBy(number: Int, divider: Int): Boolean {
    return (number % divider) == 0
}

