class fastReader {
	var buffer : String = "";
	var pos : Int = 0;
	var bufferSize : Int = 0;

	fun readBuffer() {
		buffer = readLine()!!;
		buffer += ' ';
		pos = 0;
		bufferSize = buffer.length;
	}

	fun getChar() : Char {
		if (pos == bufferSize) {
			readBuffer();
		}
		return buffer[pos++];
	}

	fun getInt() : Int {
		var ans : Int = 0;
		var c : Char = ' ';
		var minus : Boolean = false;
		while ((c == ' ') or (c == '\n'))
			c = getChar();
		if (c == '-') {
			minus = true;
			c = getChar();
		}
		while ((c != ' ') and  (c != '\n')) {
			ans = ans * 10 + c.toInt() - '0'.toInt();
			c = getChar();
		}
		if (minus) {
			ans *= -1;
		}
		return ans;
	}

	fun getLong() : Long {
		var ans : Long = 0;
		var c : Char = ' ';
		var minus : Boolean = false;
		while ((c == ' ') or (c == '\n'))
			c = getChar();
		if (c == '-') {
			minus = true;
			c = getChar();
		}
		while ((c != ' ') and  (c != '\n')) {
			ans = ans * 10 + c.toInt() - '0'.toInt();
			c = getChar();
		}
		if (minus) {
			ans *= -1;
		}
		return ans;
	} 

	fun getString() : String {
		var c : Char = ' ';
		var ans : String  = "";
		while ((c == ' ') or (c == '\n'))
			c = getChar();
		while ((c != ' ') and  (c != '\n')) {
			ans += c;
			c = getChar();
		}
		return ans;
	}

	fun getSpaceString() : String {
		var ans : String = buffer;
		readBuffer();
		return ans;
	}
}

