private fun pages(n: Int, p: Int, k: Int): String {
    val goToFirstPageSymbol = "<< "
    val goToLastPageSymbol = " >>"
    val sb = StringBuilder()
    var leftBound = if(p - k > 1) p- k else 1
    if(leftBound != 1) {
        sb.append(goToFirstPageSymbol)
    }
    for(i in leftBound until p) {
        sb.append("$i ")
    }
    sb.append("($p) ")
    val rightBound = if(p + k > n) n else p + k
    for (i in p + 1..rightBound) {
        sb.append("$i ")
    }
    sb.deleteCharAt(sb.length - 1)
    if (p + k < n) {
        sb.append(goToLastPageSymbol)
    }

    return sb.toString()
}

