fun main(args:Array<String>){
    var input = readLine()!!.split(' ')

    val studentCount = input[0].toInt() - 1


    input = readLine()!!.split(' ')

    val puzzles = mutableListOf<Int>()

    input.forEach {
        puzzles.add(it.toInt())
    }
    puzzles.sort()

    var currentMinDiff = puzzles[puzzles.lastIndex]
    for (i in 0..puzzles.lastIndex - studentCount){
        if(i + studentCount <= puzzles.lastIndex){
            val diffCandidate = puzzles[i + studentCount] - puzzles[i]

            if ( diffCandidate  < currentMinDiff){
                currentMinDiff = diffCandidate
            }
        }
    }

    print(currentMinDiff)
}

