fun main(args: Array<String>) {
    class Scanner(s: InputStream) {
        private var st: StringTokenizer? = null
        private var br: BufferedReader = BufferedReader(InputStreamReader(s))

        @Throws(IOException::class)
        operator fun next(): String {
            while (st == null || !st!!.hasMoreTokens())
                st = StringTokenizer(br.readLine())
            return st!!.nextToken()
        }

        @Throws(IOException::class)
        fun nextInt(): Int {
            return Integer.parseInt(next())
        }

        @Throws(IOException::class)
        fun nextLong(): Long {
            return java.lang.Long.parseLong(next())
        }

        @Throws(IOException::class)
        fun nextLine(): String {
            return br.readLine()
        }

        @Throws(IOException::class)
        fun nextDouble(): Double {
            return java.lang.Double.parseDouble(next())
        }

        @Throws(IOException::class)
        fun ready(): Boolean {
            return br.ready()
        }
    }

    val scan = Scanner(System.`in`)

    val n = scan.nextInt()
    val k = scan.nextInt()

    val dist = (0 until n).map { scan.nextInt() }
    if(dist.all { it <= k }) {
        println(n)
        return
    }

    var first = dist.indexOfFirst { it > k }
    if (first < 0) first = 0
    var last = dist.indexOfLast { it > k }
    if (last < 0) last = n - 1

    val ans = first + n - last - 1

    println(ans)
}

