class ModuloArithmetic(private val MOD: Int) {
    fun ofInt(x: Int) = IntMod(x, MOD)
    fun ofLong(x: Long) = IntMod((x % MOD).toInt(), MOD)

    fun precomputeFactorials(n: Int) = PrecomputedFactorials(n, MOD)

    fun factorial(n: Int): IntMod {
        var res = ofInt(1)
        for (i in 1..n) {
            res *= i
        }
        return res
    }

    /**
     * n choose k, picking k elements from a set of n element, without repetitions
     *
     *  / n \
     *  |   |
     *  \ k /
     */
    fun choose(n: Int, k: Int): IntMod {
        if (k > n || n <= 0) return ofInt(0)
        if (k == 0 || k == n) return ofInt(1)

        return factorial(n) / (factorial(k) * factorial(n-k))
    }

    /**
     * n multichoose k, i.e. picking k elements from a set of n element, *with* repetitions, order does not matter.
     */
    fun multichoose(n: Int, k: Int): IntMod = choose(n+k-1, k)

    /**
     * /       n      \
     * |              |
     * \ k_1, ... k_m /
     *
     * Number of ways of putting n distinct objects into m distinct bins
     * with k_i objects in the i'th bin
     */
    fun multinomial(n: Int, ks: List<Int>): IntMod {
        var res = factorial(n)
        for (k in ks) {
            res /= factorial(k)
        }
        return res
    }

    /**
     * Number of distinct ways of shuffling values [vs] (distinct = some value on some position differs).
     */
    fun numWayToShuffle(vs: List<Int>): IntMod {
        val f = mutableMapOf<Int, Int>()
        for (v in vs) {
            f.merge(v, 1, Int::plus)
        }
        return multinomial(vs.size, f.values.toList())
    }
}

class IntMod(n: Int, private val MOD: Int) {
    val i = n % MOD

    fun ofInt(x: Int) = IntMod(x, MOD)
    fun ofLong(x: Long) = IntMod((x % MOD).toInt(), MOD)

    operator fun plus(other: IntMod): IntMod = IntMod(Math.floorMod(i + other.i, MOD), MOD)
    operator fun plus(other: Int): IntMod = this + ofInt(other)
    operator fun plus(other: Long): IntMod = this + ofLong(other)

    operator fun minus(other: IntMod): IntMod = IntMod(Math.floorMod(i - other.i, MOD), MOD)
    operator fun minus(other: Int): IntMod = this - ofInt(other)
    operator fun minus(other: Long): IntMod = this - ofLong(other)

    operator fun times(other: IntMod): IntMod = IntMod(Math.floorMod(i.toLong() * other.i, MOD.toLong()).toInt(), MOD)
    operator fun times(other: Int): IntMod = this * ofInt(other)
    operator fun times(other: Long): IntMod = this * ofLong(other)

    operator fun div(other: IntMod): IntMod = this * other.multiplicativeInverse()
    operator fun div(other: Int): IntMod = this / ofInt(other)
    operator fun div(other: Long): IntMod = this / ofLong(other)

    override fun toString(): String = i.toString()

    // i^n
    fun pow(n_in: Long): IntMod {
        var x = this
        var y = ofInt(1)
        var n = n_in
        // x^n
        while (n > 0) {
            if (n % 2L != 0L) y *= x
            n /= 2
            x *= x
        }
        return y
    }

    private fun multiplicativeInverse(): IntMod = pow(MOD-2L)
}

class PrecomputedFactorials(val n: Int, val MOD: Int) {
    val fact = Array(n+1) { IntMod(1, MOD) }
    val invFact = Array(n+1) { IntMod(1, MOD) }

    init {
        var f = IntMod(1, MOD)
        for (i in 1..n) {
            f *= i
            fact[i] = f
            invFact[i] = IntMod(1, MOD) / f
        }
    }

    fun fact(i: Int) = fact[i]

    fun choose(n: Int, k: Int) = when {
        k > n -> IntMod(0, MOD)
        n < 0 -> IntMod(0, MOD)
        else -> fact[n] * invFact[n - k] * invFact[k]
    }

    fun multichoose(n: Int, k: Int) = choose(n+k-1, k)
}

