enum class Color {Blue,Red,Yellow}

fun Christmas(yellowcolor:Int,bluecolor:Int,redcolor:Int):Int
{
    if(yellowcolor==bluecolor && bluecolor==redcolor)
        return (yellowcolor-1)+yellowcolor+(yellowcolor-2)

    return when(if (yellowcolor <= bluecolor && yellowcolor <= redcolor)
        Color.Yellow
    else if (bluecolor <= redcolor && bluecolor <= yellowcolor)
        Color.Blue
    else
        Color.Red){
        Color.Yellow -> if(yellowcolor==bluecolor)
                             yellowcolor+(yellowcolor+1)+(yellowcolor-1)
                        else if (redcolor==bluecolor && (redcolor+bluecolor)-(yellowcolor*2)<3)
                             yellowcolor+(yellowcolor+1)+(yellowcolor-1)
                        else if (yellowcolor==redcolor)
                             yellowcolor+(yellowcolor-2)+(yellowcolor-1)
                        else if (bluecolor>redcolor && redcolor-yellowcolor==1)
            yellowcolor+(yellowcolor+1)+(yellowcolor-1)


        else if(redcolor>bluecolor || redcolor==bluecolor ||(bluecolor>redcolor && (redcolor+bluecolor)-(yellowcolor*2)>3))
                            yellowcolor+(yellowcolor+1)+(yellowcolor+2)

                        else
                            yellowcolor+(yellowcolor+1)+(yellowcolor-1)

        Color.Blue-> if(bluecolor==redcolor)
            (bluecolor-2)+bluecolor+(bluecolor-1)
            else
                        (bluecolor+1)+bluecolor+(bluecolor-1)
        else -> redcolor+(redcolor-2)+(redcolor-1)
    }


}

