    if (ab.isEmpty()) {
        val amin = a.min()!!
        val bmin = b.min()!!
        if (amin < bmin)
            println("$amin$bmin")
        else
            println("$bmin$amin")
    } else {
        val x = ab.min()
        println("$x")
    }
}

