    numbers.sort()

    var from = 0
    var to = 0
    var optimalRemoved = Int.MAX_VALUE
    while (to <= numbers.lastIndex) {
        val d = numbers[to] - numbers[from]

        if (d <= desiredDiameter) {
            optimalRemoved = minOf(from + (numbers.size - to - 1), optimalRemoved)
        }

        if (d <= desiredDiameter) {
            to++
        } else {
            from++
        }
    }

    println(optimalRemoved)
}

