            r == 0L -> {
                val subTotal = subPrice * (curN/k) * (k-1)
                if (subTotal < divPrice) {
                    totalPrice += subTotal
                } else {
                    totalPrice += divPrice
                }
                curN /= k
            }
            else -> {
                totalPrice += subPrice * r
                curN -= r

                // ugly check if curN under k so we could get zero
                if (curN == 0L) {
                    curN = 1
                    totalPrice -= subPrice
                }
            }
        }
    }
    println(totalPrice)
}

