    var cost = BigInteger.ZERO
    while (x >= divisor) {
        val mod = x % divisor
        if (mod != 0L) {
            cost += BigInteger.valueOf(mod * subtractCost)
            x -= mod
        } else {
            cost += BigInteger.valueOf(min(divideCost, subtractCost * (x - x/divisor)))
            x /= divisor
        }
    }
