        for(i in 1..n) D[i][i] = twoPow[i-1]
        for(i in 1..n-2) for(j in i/2+1..i) {
            val d = D[i][j]
            for(k in 1..n-1-i) {
                D[i+k+1][j+k] += d * mc.C(j+k, k) * twoPow[k-1]
            }
        }

        val ans = D[n].sum()
