fun cumulativeSum(a: LongArray): LongArray {
    
    val N = a.size
    var s = LongArray(N+1) { 0L }
    
    for( i in 1..N ) {
        s[i] = s[i-1]+a[i-1]
    }
    
    return s
    
}

fun rlowerBound(a: LongArray, x: Long): Int {
    
    val N = a.size
    var high = N-1
    var low = 0
    var mid: Int
    
    while( low < high ) {
        mid = (high+low+1)/2
        if( a[mid] > x ) high = mid-1
        else low = high
    }
    
    return high
    
}

fun lowerBound(a: IntArray, x: Int): Int {
    
    val N = a.size
    var high = N-1
    var low = 0
    var mid: Int
    
    while( low < high ) {
        mid = (high+low)/2
        if( a[mid] < x ) low = mid+1
        else high = mid
    }
    
    return low
    
}

fun permInv(p: IntArray): IntArray {
    
    val N = p.size
    var res = IntArray(N) { -1 }
    
    for( i in 0 until N ) {
        res[p[i]] = i
    }
    
    return res
    
}

