	var set: Boolean = false
	for(i in 0..list.size - 2){
		if(set){
			set = false
			continue
		}
		if('B' == list[i] && 'G' == list[i+1]){
			list[i] = 'G'
			list[i+1] = 'B'
			set  = true
		} 
	}
	//println(list)
	return String(list)
}

