        val isPrime = MutableList(n + 1) { true }
        isPrime[0] = false
        isPrime[1] = false
        for (x in 2..n) {
            if (!isPrime[x]) continue
            for (u in (2 * x)..n step x) isPrime[u] = false
        }

        return isPrime
    }

    fun isPalindrome(d: Int): Boolean {
        val num = d.toString()
        if (num.length == 1) return true
        else {
            for (i in num.indices) if (num[i] != num[num.length - i - 1]) return false
            return true
        }
    }

    val isPrime = sieve(2000000)

    var primes = 0L
    var palindromes = 0L

    var currNumber = 1
    var ans = 0
    while (currNumber < 2000000) {
        if (isPalindrome(currNumber)) palindromes++
        if (isPrime[currNumber]) primes++
        if (q * primes <= p * palindromes) {
            ans = currNumber
//            println("$currNumber -> $primes $palindromes")
        }
        currNumber++
    }

    println(ans)
}

