fun solve(sb: java.lang.StringBuilder, map: MutableMap<Char, Int>) {
    for (c in 'z' downTo 'b') {
        if (map[c] == null || map[c] == 0) continue
        for (i in sb.indices) {
            if (sb[i] == c) {
                if (i > 0 && sb[i - 1] == c - 1 || i < sb.length - 1 && sb[i + 1] == c - 1) {
                    map[sb[i]] = map[sb[i]]!! - 1
                    sb.deleteCharAt(i)
                    return solve(sb, map)
                }
            }
        }
    }
}

