fun pow(x: Long, y: Long): Long {
    var y = y % (mod - 1)

    var res = 1L
    var deg = x
    while (y > 0) {
        if (y % 2 == 1L) {
            res = (res * deg) % mod
        }
        deg = (deg * deg) % mod
        y /= 2
    }

    return res
}


