infix fun Long.pow(n: Long): Long {
    var n = n % (mod - 1)
    var a = this

    var res = 1L
    while (n > 0) {
        if (n % 2 == 1L) res = (res * a) % mod

        a = (a * a) % mod
        n /= 2
    }
    return res
}

