val modulo : Long = 1000000007L

tailrec fun modPow(n : Long, m : Long) : Long {
    if(m == 0L) return 1
    if(m == 1L) return n % modulo
    val vur = if(m % 2L == 0L) 1L  else n % modulo
    val a = modPow(n,m / 2) % modulo;
    return (vur % modulo * a  % modulo * a % modulo) % modulo
}

