fun restore(s: String, delimiters: Iterator<Int>): String {
  if (!delimiters.hasNext()) return s
  val delimiter = delimiters.next()
  return restore(s.substring(0, delimiter).reversed() + s.substring(delimiter), delimiters)
}

fun collectDelimiters(n: Int): Iterator<Int> {
  val res = mutableListOf<Int>()
  var d = n;
  while (d >1) {
    if (n % d == 0) {
      res.add(d);
    }
    d--
  }
  return res.reversed().iterator()
}

