fun main() {
    val scanner = Scanner(System.`in`)
    var n = scanner.nextLong()

    var max = 1L
    var nines = 1L

    while (n > 0) {
        val r = n % 10
        n /= 10
        val rMinusOne = if (r == 1L && n == 0L) 1 else r - 1
        max = if (r * max > rMinusOne * nines) {
            r * max
        } else {
            rMinusOne * nines
        }
        nines *= 9
    }

    System.out.println(max)
}

