fun main() {
    fun String.prod(): Int {
        var sol = 1
        this.forEach { sol *= it - '0' }
        return sol
    }

    val ns = readLine()!!
    var solM = ns.prod()
    if (ns.length == 1) {
        print(ns)
    } else {
        for (k in 0 until ns.length - 1) {
            val candidate =
                ns.substring(0, k).prod() * max(1, (ns[k] - '0' - 1)) * 9.0.pow((ns.length - k - 1).toDouble()).toInt()
            if (candidate > solM) {
                solM = candidate
            }
        }
        print(solM)
    }
}

