fun subtract(input: String) : String {
    val (n, k) = input.split(" ")

    return subtract(n, k.toInt());
}

private fun subtract(n: String, k: Int) : String {
    if (k == 0) return n

    return if (n.last() == '0') {
        subtract(n.substring(0, n.length - 1), k - 1)
    } else {
        subtract(n.toInt(), k).toString()
    }
}

private fun subtract(n: Int, k: Int) : Int {
    if (k == 0) return n

    return if (n % 10 == 0) {
        subtract(n / 10, k - 1)
    } else {
        subtract(n - 1, k - 1)
    }
}

