    val expression = it.next()
    val length = expression.length
    val bucket = ByteArray(4)

    for (i in 0 until length step 2) {
      val rawDigit = expression[i]
      val digit = Character.digit(rawDigit, 10)
      bucket[digit]++
    }

    val plus = "+"
    val builder = StringBuilder(length)
    for (i in 1..3) {
      val count = bucket[i]
      for (k in 0 until count) {
        builder.append(i).append(plus)
      }
    }
    val end = builder.length
    val start = end - 1
    builder.replace(start, end, "")
    println(builder)
  }
}

