import java.io.*
import java.util.*

class A internal constructor(inputStream: InputStream, val out: PrintWriter) {
    companion object {
        val ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null
    }


    private val br = BufferedReader(InputStreamReader(inputStream))
    private var st = StringTokenizer("")

    internal fun hasNext(): Boolean {
        while (!st.hasMoreTokens()) {
            val readLine = br.readLine() ?: return false
            st = StringTokenizer(readLine)
        }
        return true
    }

    private operator fun next() =
            if (hasNext()) st.nextToken()!!
            else throw RuntimeException("No tokens")

    internal fun nextLine() =
            if (hasNext()) st.nextToken("\n")
            else throw RuntimeException("No tokens")

    private fun nextInt() = next().toInt()
    private fun nextIntArray(n: Int) = IntArray(n, { nextInt() })
    private fun nextIntArray(m: Int, n: Int) = Array(m, { nextIntArray(n) })

    private fun nextLong() = next().toLong()
    private fun nextLongArray(n: Int) = LongArray(n, { nextLong() })
    private fun nextLongArray(m: Int, n: Int) = Array(m, { nextLongArray(n) })

    private fun nextDouble() = next().toDouble()
    private fun nextDoubleArray(n: Int) = DoubleArray(n, { nextDouble() })
    private fun nextDoubleArray(m: Int, n: Int) = Array(m, { nextDoubleArray(n) })


    fun log() {
        if (!ONLINE_JUDGE) {
            println()
        }
    }

    inline fun log(arr: IntArray?, name: String = "") {
        if (!ONLINE_JUDGE) {
            print("#$name: ")
            println(arr)
        }
    }

    inline fun log(arr: DoubleArray?, name: String = "") {
        if (!ONLINE_JUDGE) {
            print("#$name: ")
            println(arr)
        }
    }

    inline fun <T> log(arr: Array<T>?, name: String = "") {
        if (!ONLINE_JUDGE) {
            print("#$name: ")
            println(arr)
        }
    }

    inline fun <T> log(stack: Stack<T>?, name: String = "") {
        if (!ONLINE_JUDGE) {
            print("#$name: ")
            println(stack)
