val DX = arrayOf( 0, 1, 1, 1 )
val DY = arrayOf( 1, 0, 1, -1 )

fun find( x0: Int, y0: Int, t: Array<CharArray>, dx: Int, dy: Int ): Boolean {
    var x = x0
    var y = y0
    var xN = 0
    var dotN = 0
    for ( i in 0 until 5 ) {
        if ( x < 0 || x >= t.size || y < 0 || y >= t[x].size ) return false
        if ( t[x][y] == 'X' ) {
            xN ++
        } else if ( t[x][y] == '.' ) {
            dotN ++
        } else {
            return false
        }
        x += dx
        y += dy
    }
    return xN == 4
}

