fun main(args: Array<String>) {
    var (n_, k) = readLongs()
    val n = n_.toInt()
    val s = readLine()!!
    val inf: Long = 1000000000000

    val lastPos = Array(n) { IntArray(26) { -1 } }
    val dp = Array(n) { LongArray(n) }

    for ((i, c) in s.withIndex()) {
        lastPos[i][c - 'a'] = i
        dp[i][0] = 1
    }

    for (i in 1 until n) for (j in 0 until 26) lastPos[i][j] = max(lastPos[i][j], lastPos[i-1][j])

    for (i in 1 until n) for (j in 1..i) for (cc in 0..25) {
        if (lastPos[i-1][cc] != -1) {
            dp[i][j] += dp[lastPos[i-1][cc]][j-1]
            dp[i][j] = min(inf, dp[i][j])
        }
    }

    var cost: Long = 0
    for (len in n-1 downTo 0) {
        for (cc in 0..25) if (lastPos.last()[cc] != -1) {
            val cnt = dp[lastPos.last()[cc]][len]
            if (cnt >= k) {
                cost += k * (n - (len+1))
                println(cost)
                return
            }
            cost += cnt * (n - (len+1))
            k -= cnt
        }
    }

    if (k == 1L) println(cost + n)
    else println(-1)

}

