fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val writer = PrintWriter(System.`out`)

    solve(reader, writer)

    writer.flush()
}

fun solve(reader: BufferedReader, writer: PrintWriter) {
    val n: Int
    var k: Long

    reader.readLine().split(" ").let {
        n = it[0].toInt()
        k = it[1].toLong()
    }

    val s = reader.readLine()

    val prev = Array(n + 1) { LongArray(26) }
    val dp = Array(n + 1) { LongArray(26) }

    (1..n).forEach { i ->
        (0 until 26).forEach { ch ->
            dp[1][ch] = prev[1][ch]
        }
        dp[1][s[i - 1].index()] = 1

        (2..n).forEach { j ->
            (0 until 26).forEach { ch ->
                if (s[i - 1].index() == ch) {
                    dp[j][ch] = prev[j - 1].sum()
                } else {
                    dp[j][ch] = prev[j][ch]
                }
            }
        }

        (0..n).forEach { j ->
            (0 until 26).forEach { ch ->
                prev[j][ch] = dp[j][ch]
                dp[j][ch] = 0
            }
        }
    }

    var price = 0L
    for (i in n downTo 1) {
        val sum = prev[i].sum()
        price += Math.min(sum, k) * (n - i)
        k -= sum
        if (k <= 0) {
            break
        }
    }
    if (k > 1) {
        writer.write((-1).toString())
        return
    }
    if (k == 1L) {
        price += n
    }
    writer.write(price.toString())
}

