fun readStrings(separator: String = " ", emptyWords: Boolean = false): Array<String> {
    val line = readLine()!!
    val list = ArrayList<String>()
    var builder = StringBuilder()

    for (i in 0..line.length) {
        if (i == line.length || separator.contains(line[i])) {
            if (emptyWords || builder.isNotEmpty()) {
                list.add(builder.toString())
                builder = StringBuilder()
            }
        } else {
            builder.append(line[i])
        }
    }

    return list.toTypedArray()
}

fun Long.factorize(): List<Int> {
    var sub = takeIf { it > 1 } ?: return emptyList()

    return sequence {
        for (p in Primes.primes) {
            if (sub <= 1) {
                break
            }

            while (sub % p == 0L) {
                sub /= p
                yield(p)
            }
        }
    }.toList()
}

object Primes {
    const val MAX = 2_000_000

    val bitmap: BitSet by lazy { Primes.sieve(MAX) }
    val primes: List<Int> by lazy { (1..MAX).filter { isPrime(it) }.toList() }

    fun isPrime(num: Int) = bitmap[num - 1]

    fun nthPrime(n: Int) = primes[n - 1]

    private fun sieve(max: Int): BitSet {
        val primeMap = BitSet(max)
        primeMap.set(0, primeMap.size() - 1)
        primeMap.set(0, false)

        for (i in 2..primeMap.size()) {
            if (primeMap[i - 1]) {
                for (j in i + i..primeMap.size() step i) {
                    primeMap.set(j - 1, false)
                }
            }
        }

        return primeMap
    }
}

