            .useInputSource(System.`in`)
            .useOutputSource(System.out)
            .useScanner(FastScanner())
            .solveTask(TaskA())
            .run()

    class TaskA: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val length = scanner.nextInt()
            val numbers = Array(length) { scanner.nextInt() }

            var maxOnesCount = -1

            (0 until length) { i ->
                (i until length) { j ->
                    var currentCountOfOnes = 0
                    (0 until length) {
                        currentCountOfOnes += if((it in (i..j) && 1 - numbers[it] == 1) || (it !in (i..j) && numbers[it] == 1)) 1 else 0 }
                    maxOnesCount = max(maxOnesCount, currentCountOfOnes)
                }
            }

            printer.println(maxOnesCount)
        }

    }

}

