val maxn = 444
val g = Array<MutableList<Int>>(maxn) { mutableListOf() }
val f = Array(maxn) { IntArray(maxn) { Int.MAX_VALUE } }
val problems = Array(maxn) { Array(maxn) { BitSet(maxn) } }
val parents = IntArray(maxn)
val used = BooleanArray(maxn)

fun dfs(v: Int) {
    used[v] = true
    val tos = g[v].filter { !used[it] }.toList()
    f[v][1] = tos.size
    problems[v][1].set(v)
    for (to in tos) {
        if (!used[to]) {
            parents[to] = v
            dfs(to)
            val tempF = f[v].copyOf()
            val tempProblems = arrayOf(*(problems[v].map { it.clone() as BitSet }.toTypedArray()))
            for (childSize in 1 until maxn) {
                val childRoads = f[to][childSize]
                if (childRoads != Int.MAX_VALUE) {
                    for (mySizeBefore in maxn - 1 downTo 1) {
                        if (f[v][mySizeBefore] != Int.MAX_VALUE) {
                            if (f[v][mySizeBefore] - 1 + f[to][childSize] < tempF[childSize + mySizeBefore]) {
                                tempF[childSize + mySizeBefore] = f[v][mySizeBefore] - 1 + f[to][childSize]
                                tempProblems[childSize + mySizeBefore].clear()
                                tempProblems[childSize + mySizeBefore].or(problems[v][mySizeBefore])
                                tempProblems[childSize + mySizeBefore].or(problems[to][childSize])
                            }
                        }
                    }
                }
            }
            tempF.copyInto(f[v])
            problems[v] = arrayOf(*(tempProblems.map { it.clone() as BitSet }.toTypedArray()))
        }
    }
}

fun main() {
    val (n, k) = readIntList()
    val edges = mutableListOf<Pair<Int, Int>>()
    for (i in 0..n-2) {
        var (q, w) = readIntList()
        q--; w--
        g[q].add(w)
        g[w].add(q)
        edges.add(Pair(min(q, w), max(q, w)))
    }

    dfs(0)
    var ans = Int.MAX_VALUE
    var bestV = 0
    for (v in 0 until n) {
        val mb = f[v][k] + (if (v == 0 || f[v][k] == Int.MAX_VALUE) 0 else 1)
        if (mb < ans) {
            ans = mb
            bestV = v
        }
    }
    println(ans)

    val allVerticesInComponent = (0 until n).filter { problems[bestV][k].get(it) }.toSet()
    val ansRibs = mutableListOf<Int>()

    edges.forEachIndexed { idx, edge ->
        val containsA = allVerticesInComponent.contains(edge.first)
        val containsB = allVerticesInComponent.contains(edge.second)
        if ((containsA || containsB) && !(containsA && containsB)) {
            ansRibs.add(idx + 1)
        }
    }

    println(ansRibs.joinToString(separator = " "))
}

