    val dp = Array(n) {
        Array(tree.getSubtreeSize(it) + 1) {
            INF
        }
    }
    val parent = Array(n) {
        Array(n + 1) {
            Parent(-1, -1, -1, -1, -1)
        }
    }
    dfs(dp, parent, tree, 0)
    var minRoot = -1
    for (v in 0 until n) {
        if (dp[v].size > k) {
            if (minRoot == -1 || dp[minRoot][k] + hasParent(minRoot) > dp[v][k] + hasParent(v)) {
                minRoot = v
            }
        }
    }
    val answer = mutableListOf<Int>()
    var edge = if (tree.sons(minRoot).isEmpty()) -1 else tree.sons(minRoot).last().second
    var sz = k
    val result = dp[minRoot][k] + hasParent(minRoot)
    val queue: Queue<Pair<Int, Int>> = LinkedList()
    queue.add(edge to sz)
    while (queue.isNotEmpty()) {
        val cur = queue.poll()
        edge = cur.first
        sz = cur.second
        if (edge == -1 || sz == -1) {
            continue
        }
        answer.add(parent[edge][sz].answer)
        queue.add(parent[edge][sz].e to parent[edge][sz].sz)
        if (parent[edge][sz].to != -1 && tree.sons(parent[edge][sz].to).isNotEmpty()) {
            queue.add(tree.sons(parent[edge][sz].to).last().second to parent[edge][sz].szTo)
        }
    }
    if (minRoot != 0) {
        for (v in 0 until n) {
            for (e in tree.sons(v)) {
                if (e.first == minRoot) {
                    answer.add(e.second)
                }
            }
        }
    }
    println("$result")
    println(answer.filter { it != -1 }.sorted().joinToString(" "))
}

fun hasParent(v: Int) = if (v == 0) 0 else 1

fun dfs(dp: Array<Array<Int>>, parent: Array<Array<Parent>>, tree: Tree, v: Int) {
    dp[v][1] = 0
    var curSize = 1
    for (edgeIndex in tree.sons(v).indices) {
        val edge = tree.sons(v)[edgeIndex]
        val to = edge.first
        dfs(dp, parent, tree, to)
        val layer = dp[v].copyOf()
        dp[v].fill(INF, 0, curSize + 1)
        for (szTo in 0..tree.getSubtreeSize(to)) {
            if (szTo != 0 && dp[to][szTo] == INF) {
                continue
            }
            for (szV in curSize downTo 0) {
                if (layer[szV] == INF) {
                    continue
                }
                val cost = if (szTo == 0) 1 else dp[to][szTo]
                if (dp[v][szV + szTo] > layer[szV] + cost) {
                    dp[v][szV + szTo] = layer[szV] + cost
                    val prevEdge = if (edgeIndex == 0) -1 else tree.sons(v)[edgeIndex - 1].second
                    parent[edge.second][szV + szTo] = Parent(prevEdge, szV, if (szTo == 0) edge.second else -1, to, szTo)
                }
            }
        }
        curSize += tree.getSubtreeSize(to)
    }
}

class Tree(n: Int) {

    private val graph = Array<MutableList<Pair<Int, Int>>>(n) { mutableListOf() }
    private val size = IntArray(n) { 1 }

    fun addEdge(a: Int, b: Int, id: Int) {
        graph[a].add(b to id)
        graph[b].add(a to id)
    }

    fun eraseParents(v: Int = 0, parent: Int = -1) {
        var indexToRemove = -1
        for (i in graph[v].indices) {
            val to = graph[v][i].first
            if (to != parent) {
                eraseParents(to, v)
            } else {
                indexToRemove = i
            }
        }
        if (indexToRemove != -1) {
            graph[v].removeAt(indexToRemove)
        }
    }

    fun calcSizes(v: Int = 0) {
        for (edge in graph[v]) {
            val to = edge.first
            calcSizes(to)
            size[v] += size[to]
        }
    }

    fun getSubtreeSize(v: Int) = size[v]

    fun sons(v: Int) = graph[v]
}

