fun findStraight(cards: List<String>): Int {
    var straigth = 1
    val firstCard = cards[0]
    var numI = firstCard[1]!!.toString().toInt()
    var typeI = firstCard[0]

    for (i in 1 until 3) {
        val card = cards[i]
        var numC = card[1]!!.toString().toInt()
        val typeC = card[0]

        if (typeC == typeI) {
            if (numC == numI + 1) {
                straigth++
            } else if (numC == numI + 2) {
                return 2
            }
        }

        numI = numC
        typeI = typeC
    }
    return straigth
}

