fun final_location(cmds : String) : Pair<Int, Int> {
    var loc = 0
    var num_unrecognized_cmds = 0
    for (cmd in cmds) {
        if (cmd == '+') {
            loc = loc + 1
        } else if (cmd == '-') {
            loc = loc - 1
        } else if (cmd == '?') {
            num_unrecognized_cmds = num_unrecognized_cmds + 1
        } else {
            throw Exception("Unknown input!")
        }
    }
    return Pair(loc, num_unrecognized_cmds)
}

fun factorial(x : Int) : Int {
    var f = 1;
    for (i in 1 .. x) {
        f = f * i
    }
    return f
}

