/** modint inline class, requires hardcoded mod base **/
const val MODBASE = 998244353

inline fun Int.toModInt() = ModInt(this umod MODBASE)
inline fun Long.toModInt() = ModInt((this umod MODBASE).toInt())

/** note: Only use constructor for int within modulo range, otherwise use toModInt **/
inline class ModInt(val int: Int) {
    operator fun plus(other: ModInt) = plus(other.int) // MODBASE < 2^30
    operator fun plus(other: Int) =  (int + other).toModInt() // careful of possible overflow
    operator fun inc() = plus(1)

    operator fun minus(other: ModInt) = minus(other.int)
    operator fun minus(other: Int) = (int - other).toModInt()
    operator fun dec() = minus(1)

    operator fun times(other: ModInt) = times(other.int)
    operator fun times(other: Int) = (int.toLong() * other).toModInt()

    fun pow(exponent: Int): ModInt {
        var res = ModInt(1)
        var e = exponent
        var b = this

        if(e < 0) e = e.umod(MODBASE - 1) // assumes MODBASE is prime

        while(e > 0) {
            if(e and 1 == 1) {
                res *= b
            }
            e = e shr 1
            b *= b
        }
        return res
    }

    fun inv() = pow(MODBASE - 2) // assumes MODBASE is prime

    operator fun div(other: ModInt) = times(other.inv())
    operator fun div(other: Int) = div(other.toModInt())

    override fun toString() = int.toString()
}

inline class ModIntArray(val intArray: IntArray): Collection<ModInt> {
    operator fun get(i: Int) = ModInt(intArray[i])
    operator fun set(i: Int, v: ModInt) { intArray[i] = v.int }

    override val size: Int get() = intArray.size

    override fun contains(element: ModInt): Boolean = indices.any { get(it) == element }

    override fun containsAll(elements: Collection<ModInt>): Boolean = elements.all { contains(it) }

    override fun isEmpty(): Boolean = size == 0

    override fun iterator(): Iterator<ModInt> = object: AbstractIterator<ModInt>() {
        var index = 0
        override fun computeNext() {
            if(index >= size) done()
            else setNext(get(index++))
        }
    }
}
fun ModIntArray(capacity: Int) = ModIntArray(IntArray(capacity))
inline fun ModIntArray(capacity: Int, init: (Int) -> ModInt) =
    ModIntArray(IntArray(capacity) { init(it).int })

