fun countInjuredDragons(k: Int, l: Int, m: Int, n: Int, d: Int): Int{
	var ans: Int = 0
	for(i in 1..d){
		if(divisible(k,l,m,n,i)){
			ans++
		}else{
			continue
		}
	}
	return ans
}

fun divisible(k: Int, l: Int, m: Int, n: Int, c : Int): Boolean{
	return (c % k == 0) || (c % l == 0) || (c % m == 0) || (c % n == 0)
}

