fun getBills(sum: Int, list: List<Int>, indexOfBill: Int): Int {
    val currentBill = list[indexOfBill]
    val amount = sum / currentBill
    val newIndex = indexOfBill + 1
    if (amount <= 0 && newIndex < list.size) {
        return getBills(sum, list, newIndex)
    }
    val newSum = sum % (amount * currentBill)
    if (newSum == 0) return amount
    return amount + getBills(newSum, list, newIndex)
}

fun getBillsAgain(list: List<Int>, sum: Int): Int {
    var count = 0
    var newSum = sum
    list.forEach {
        if (newSum > 0) {
            count += newSum / it
            newSum -= newSum / it * it
        }
    }
    return count
}

