data class Item(val start: Int, val end: Int, val budget: Int)

val dp = mutableMapOf<Item, Int>()

fun bestCuts(a: List<Int>, b: Int, start: Int, end: Int): Int {
    val memoryAns = dp[Item(start, end, b)]
    if (memoryAns != null) return memoryAns

    val size = end - start + 1
    if (size <= 2) return 0

    var ans = 0
    var odds = 0
    var evens = 0
    for (index in start..end) {
        val item = a[index]

        if (item % 2 == 0) evens++
        else odds++

        if (evens == odds && index + 1 <= end && abs(a[index + 1] - a[index]) <= b) {
            val rightBest = bestCuts(a, b - abs(a[index + 1] - a[index]), index + 1, a.size - 1)

            val tempAns = 1 + rightBest
            if (tempAns > ans) {
                ans = tempAns
            }
        }
    }

    dp[Item(start, end, b)] = ans
    return ans
}

