class LongMod(val MOD: Long,initial: Long = 0L)
{
    private var _value = 0L;

    init {
        if (MOD < 1L) throw Exception("MOD must be positive");
        set(initial);
    }

    constructor(MOD: Int,initial: Int): this(MOD.toLong(),initial.toLong());
    constructor(MOD: Long,initial: Int): this(MOD,initial.toLong());
    constructor(MOD: Int,initial: Long): this(MOD.toLong(),initial);

    fun toInt() = _value.toInt();
    fun toLong() = _value;
    fun toDouble() = _value.toDouble();
    fun spawn(v: Long = 0L) = LongMod(MOD,v);
    fun spawn(v: Int) = spawn(v.toLong());
    
    fun set(v: Long) 
    {
        if (v>=0)
        {
            _value = v%MOD;
        }
        else
        {
            _value = (MOD-abs(v)%MOD)%MOD;
        }
    }
    fun set(v: Int) { set(v.toLong()) }
    fun set(v: LongMod) { set(v.toLong()) }
    fun pow(e: Long): LongMod
    {
        val a = +this;
        var b = e;
        val res = spawn(1);
        while (b > 0L)
        {
            if (b and 1L==1L) res*= a;
            a*= a;
            b = b shr 1;
        }
        return res;
    }
    fun pow(e: Int) = pow(e.toLong());
    fun powSet(e: Long)
    {
        this { pow(e) };
    }
    fun powSet(e: Int) = powSet(e.toLong());

    operator fun inc() = LongMod(MOD,_value+1);
    operator fun dec() = LongMod(MOD,_value-1);
    operator fun unaryPlus() = spawn(_value);
    operator fun plus(v: Long) = spawn(_value+v%MOD);
    operator fun plus(v: Int) =  plus(v.toLong());
    operator fun plus(v: LongMod) = plus(v.toLong());
    operator fun plusAssign(v: Long) { set(_value+v%MOD) };
    operator fun plusAssign(v: Int) { plusAssign(v.toLong()) };
    operator fun plusAssign(v: LongMod) { plusAssign(v.toLong()) }; 
    operator fun unaryMinus() = spawn(-_value);
    operator fun minus(v: Long) = spawn(_value-v%MOD);
    operator fun minus(v: Int) =  minus(v.toLong());
    operator fun minus(v: LongMod) = minus(v.toLong());
    operator fun minusAssign(v: Long) { set(_value-v%MOD) };
    operator fun minusAssign(v: Int) { minusAssign(v.toLong()) };
    operator fun minusAssign(v: LongMod) { minusAssign(v.toLong()) }; 
    operator fun times(v: Long) = spawn(_value*v%MOD);
    operator fun times(v: Int) =  times(v.toLong());
    operator fun times(v: LongMod) = times(v.toLong());
    operator fun timesAssign(v: Long) { set(_value*v%MOD) };
    operator fun timesAssign(v: Int) { timesAssign(v.toLong()) };
    operator fun timesAssign(v: LongMod) { timesAssign(v.toLong()) };
    operator fun <T>invoke(fn: () -> T) 
    { 
        var v = fn();
        when(v)
        {
            is Int -> set(v)
            is Long -> set(v)
            is LongMod -> set(v)
            else -> throw Exception("unsupported type, cannot set")
        }
    };

    override fun toString() = _value.toString();
}

