fun solve(x : Long) : Long {
    var ans = x
    var ansSum = x.toString().map{it-'0'}.sum()
    var head = x
    var tailLen = 0
    while (head > 0) {
        head /= 10
        tailLen ++
        var tail = ""
        (1..tailLen).forEach { tail += '9' }
        var cur = -1.toLong()
        head --
        if (head > 0) {
            cur = (head.toString() + tail).toLong()
        } else {
            cur = tail.toLong()
        }
        if (cur > x)
            continue
        val curSum = cur.toString().map{it-'0'}.sum()
        if (curSum > ansSum) {
            ans = cur
            ansSum = curSum
        }
    }
    return ans
}

