fun isUpperCase(str: String): Boolean {
    var isUp: Boolean = true;
    str.forEach { c: Char ->
        if (!c.isUpperCase()) {
            isUp = false
            return@forEach
        }
    }
    return isUp
}

fun invertCase(c: Char): Char {
    if (c.isUpperCase()) {
        return c.toLowerCase();
    } else if (c.isLowerCase()) {
        return c.toUpperCase()
    } else {
        return c
    }
}

fun invertCase(str: String): String {
    val sb: StringBuilder = StringBuilder()
    str.forEach { c -> sb.append(invertCase(c)) }
    return sb.toString()
}

