class Game(chargeFirst: Int, chargeSecond: Int) {

    var duration = 0

    private val first: Joystick = Joystick(chargeFirst)
    private val second: Joystick = Joystick(chargeSecond)

    private val dischargingAmount = -2
    private val chargeAmount = 1

    private val chargingFirst get() = first.charge <= second.charge

    fun minutePasses() {
        val firstNeedsCharging = chargingFirst
        if ((first.charge != 1 || firstNeedsCharging) && (second.charge != 1 || !firstNeedsCharging)) duration++

        first.charge += if (firstNeedsCharging) chargeAmount else dischargingAmount
        second.charge += if (firstNeedsCharging) dischargingAmount else chargeAmount
    }

    val canPlay get() = first.charge > 0 && second.charge > 0
}

