class Reader(stream: InputStream) {
    private val reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer? = null

    init {
        tokenizer = null
    }

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens())
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        return tokenizer!!.nextToken()
    }

    fun nextLine(): String? {
        val fullLine: String
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                fullLine = reader.readLine()
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

            return fullLine
        }
        return null
    }

    fun toArray(): Array<String> {
        return nextLine()!!.split(" ".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextFloat(): Float {
        return java.lang.Float.parseFloat(next())
    }

    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

}

