fun getAnswer(n : Long, k : Long) : Long {
    val maxPossible = if (k <= n) k - 1 else n
    val minPossible = k - maxPossible

    val count = Math.max(0L, (maxPossible - minPossible + 1))
    return count / 2
}

class FenwickTree(n : Int) {

    val size = n + 1
    val tree = LongArray(size) { 0L }

    fun update(index : Int, delta : Int) {
        var x = index + 1
        while (x < size) {
            tree[x] = tree[x] + delta
            x += x and -x
        }
    }

    fun get(start : Int, end : Int) =
            get(end) - get(start - 1)

    fun get(index : Int) : Long {
        var result : Long = 0

        var x = index + 1
        while (x > 0) {
            result += tree[x]
            x -= x and -x
        }

        return result
    }
}

