fun readGraph(n: Int, m : Int,
              undirected : Boolean = true,
              indexing : Int = 1) : Graph {
    val builder = GraphBuilder()

    for (i in 1..m) {
        var (from, to) = readInts()

        from -= indexing
        to -= indexing

        if (undirected) builder.addEdge(from, to)
        else builder.addDirectedEdge(from, to)
    }

    return builder.build(n)
