    internal object IntegerUtils {
        fun trueMod(a: Long, b: Long): Long {
            var a = a
            a %= b
            a += b
            a %= b
            return a
        }

        fun reverse(number: Long, modulo: Long): Long {
            return trueMod(extGcd(number, modulo).first, modulo)
        }

        fun extGcd(a: Long, b: Long): EzLongLongLongTriple {
            var x2: Long = 1
            var y2: Long = 0
            var x1: Long = 0
            var y1: Long = 1
            var x: Long
            var y: Long
            var r2: Long
            var r1: Long
            var q: Long
            var r: Long
            r2 = a
            r1 = b
            while (r1 != 0L) {
                q = r2 / r1
                r = r2 % r1
                x = x2 - q * x1
                y = y2 - q * y1
                r2 = r1
                r1 = r
                x2 = x1
                y2 = y1
                x1 = x
                y1 = y
            }
            return EzLongLongLongTriple(x2, y2, r2)
        }
    }

    internal object PrimitiveHashCalculator {
        fun getHash(x: Long): Int {
            return x.toInt() xor (x ushr 32) as Int
        }
    }

    internal class EzLongLongLongTriple(var first: Long, var second: Long, var third: Long) : Comparable<EzLongLongLongTriple> {
        override fun equals(o: Any?): Boolean {
            if (this === o) return true
            if (o == null || javaClass != o.javaClass) return false
            val that = o as EzLongLongLongTriple
            return first == that.first && second == that.second && third == that.third
        }

        override fun hashCode(): Int {
            var hash = HASHCODE_INITIAL_VALUE
            hash = (hash xor PrimitiveHashCalculator.getHash(first)) * HASHCODE_MULTIPLIER
            hash = (hash xor PrimitiveHashCalculator.getHash(second)) * HASHCODE_MULTIPLIER
            hash = (hash xor PrimitiveHashCalculator.getHash(third)) * HASHCODE_MULTIPLIER
            return hash
        }

        override fun compareTo(o: EzLongLongLongTriple): Int {
            var res = java.lang.Long.compare(first, o.first)
            if (res == 0) {
                res = java.lang.Long.compare(second, o.second)
                if (res == 0) {
                    res = java.lang.Long.compare(third, o.third)
                }
            }
            return res
        }

        override fun toString(): String {
            return "($first, $second, $third)"
        }

        companion object {
            private const val HASHCODE_INITIAL_VALUE = -0x7ee3623b
            private const val HASHCODE_MULTIPLIER = 0x01000193
        }
    }
