inline class ModInt(private val x: Int) {
    companion object {
        const val mod = 998_244_353

        //        const val mod = 1e9.toInt() + 7
        fun Int.toModInt() = ModInt(this)
        fun Int.toModIntSafe() = ModInt((this % mod + mod) % mod)
