private fun solve(scanner : FastScanner, out: PrintWriter) {
    val n = scanner.nextLong()
    val x = scanner.nextInt()

    val expected = when(x) {
        0 -> Triple(1, 0, 0)
        1 -> Triple(0, 1, 0)
        2 -> Triple(0, 0, 1)
        else -> throw IllegalArgumentException()
    }
    listOf(Triple(1, 0, 0), Triple(0, 1, 0), Triple(0, 0, 1)).forEach {
        val res = simulate(it, n)
        if (res == expected) {
            val pos = it.toList().indexOf(1)
            out.print(pos)
            return
        }
    }
}

private fun simulate(initial: Triple<Int, Int, Int>, n: Long): Triple<Int, Int, Int> {
    var state = initial
    for (i in 1..n % 6L) {
        if (i % 2 == 1L) {
            val temp = state.first
            state = state.copy(first = state.second, second = temp)
        } else {
            val temp = state.third
            state = state.copy(third = state.second, second = temp)
        }
    }
    return state
}


private class FastScanner(`in`: InputStream) {
    private var reader: BufferedReader? = null
    private var tokenizer: StringTokenizer? = null

    init {
        reader = BufferedReader(InputStreamReader(`in`))
        tokenizer = null
    }

    operator fun next(): String {
        if (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(reader!!.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        }
        return tokenizer!!.nextToken()
    }

    fun nextLine(): String {
        if (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                return reader!!.readLine()
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        }

        return tokenizer!!.nextToken("\n")
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }
}

