fun get64BitBinaryString(numm : Long) : String {
    val builder = StringBuilder()
    var num = numm
    while (num != 0L){
        if (num%2 == 0L){
            builder.append('0')
        }else{
            builder.append('1')
        }
        num/=2
    }
    while (builder.length != 64){
        builder.append('0')
    }
    return builder.toString().reversed()
}

class Primes {

    val primes = mutableListOf<Int>()

    init {
        sieve()
    }

    fun sieve() {
        val composite = IntArray(100001) { 0 }
        for (i in 2 until 100001){
            if (composite[i] == 0){
                //means i is prime
                primes.add(i)
                var cur = 1
                while (i*cur <= 100000){
                    composite[i*cur] = 1
                    cur++
                }
            }
        }
    }

    fun factorize(num: Int): Map<Int, Int> {
        //using these primes factorize
        val factors = mutableMapOf<Int, Int>()
        var n =num
        primes.forEach {
            var power = 0
            while (n%it == 0){
                n /= it
                power++
            }
            if (power != 0){
                factors[it] = power
            }
        }
        if (n != 1){
            factors[n] = 1
        }
        return factors
    }

}


