tailrec fun solve(left: MutableList<Int>, right: MutableList<Int>, steps: Int = 0): Int {
    val leftSum = left.sum()
    val rightSum = right.sum()
    if (leftSum == rightSum) return steps

    val delta = leftSum - rightSum
    var larger = if (delta>0) left else right
    val smaller = if (delta>0) right else left

    val largerDecreases = larger.sortedDescending()
    val smallerIncreases = smaller.map { 9-it }

    val maxDecrease = largerDecreases.max()!!
    val maxIncrease = smallerIncreases.max()!!

    if(Math.max(maxDecrease, maxIncrease) >= Math.abs(delta)) {
        return steps+1
    }

    fun getIndex(list: List<Int>, number: Int?): Int = if (number == null) 0 else list.indexOf(number)

    if (maxIncrease>maxDecrease) {
        smaller[getIndex(smaller, smaller.min())] = 9
        return solve(smaller, larger, steps+1)
    }
    larger[getIndex(larger, larger.max())] = 0
    return solve(smaller, larger, steps+1)
}

