class TransitionMatrix {
  val matrix : Array<LongArray>

  init {
    this.matrix = Array(4, {_ -> LongArray(4, {_ -> 0L})})
  }

  operator fun get(i : Int, j : Int) : Long {
    return this.matrix[i][j]
  }

  private operator fun set(i : Int, j : Int, x : Long) {
    this.matrix[i][j] = x
  }

  operator fun times(other : TransitionMatrix) : TransitionMatrix {
    val modulo = 1000000007L
    val result = TransitionMatrix()
    for (i in 0 .. 3) {
      for (j in 0 .. 3) {
        var x = 0L
        for (k in 0 .. 3) {
          x = (x + (this[i,k] * other[k,j])) % modulo
        }
        result[i,j] = x
      }
    }
    return result
  }

  companion object {
    fun identity() : TransitionMatrix {
      val result = TransitionMatrix()
      result[0,0] = 1L
      result[1,1] = 1L
      result[2,2] = 1L
      result[3,3] = 1L
      return result
    }

    fun ant() : TransitionMatrix {
      val result = TransitionMatrix()
      for (i in 0 .. 3) {
        for (j in 0 .. 3) {
          result[i,j] = 1L
        }
      }
      result[0,0] = 0L
      result[1,1] = 0L
      result[2,2] = 0L
      result[3,3] = 0L
      return result
    }
  }
}

fun num_paths(n : Int) : Long {
  fun raise_to(t : TransitionMatrix, x : Int) : TransitionMatrix {
    if (x == 0) {
      val result = TransitionMatrix.identity()
      return result
    } else if ((x % 2) == 0) {
      val t_sqr = t * t
      val x_div_2 = x / 2
      val result = raise_to(t_sqr, x_div_2)
      return result
    } else {
      val t_sqr = t * t
      val x_minus_1_div_2 = (x - 1) / 2
      val result = t * raise_to(t_sqr, x_minus_1_div_2)
      return result
    }
  }
  val t_matrix = TransitionMatrix.ant()
  val result = raise_to(t_matrix, n)
  return result[0,0]
}

