    val vowels = "aeiou"
    val vowelsAndN = "aeioun"

    if(s[s.length-1] !in vowelsAndN) return false

    for (i in 1 until s.length) {
        if (s[i - 1] !in vowelsAndN && s[i] !in vowels) return false
    }

    return true
