fun solve(reader: InputReader, writer: PrintWriter) {
    val p = reader.nextInt()
    val y = reader.nextInt()

    if (p == y) {
        writer.print("-1")
        return
    }

    for (i in (p + 1..y).reversed()) {
        var j = 2
        while (j * j <= i) {
            if (i % j == 0) {
                if (j > p) {
                    writer.println(i)
                    return
                }
                break
            }
            j++
        }
//        writer.println("$j -> $i")
        if (j * j > i) {
            writer.println(i)
            return
        }
    }
    writer.print("-1")

}

class InputReader(stream: InputStream) {
    val reader: BufferedReader
    var tokenizer: StringTokenizer? = null

    init {
        reader = BufferedReader(InputStreamReader(stream), 32768)
        tokenizer = null
    }

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        }
        return tokenizer!!.nextToken()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

    fun nextArrayInt(count: Int): IntArray {
        return nextArrayInt(0, count)
    }

    fun nextArrayInt(start: Int, count: Int): IntArray {
        val a = IntArray(start + count)
        for (i in start until start + count) {
            a[i] = nextInt()
        }
        return a
    }

    fun nextArrayLong(count: Int): LongArray {
        val a = LongArray(count)
        for (i in 0 until count) {
            a[i] = nextLong()
        }
        return a
    }
}

