fun solve(reader: InputReader, writer: PrintWriter) {
    val s = reader.next()
    val ans = test(s, 0)

    writer.println(if (ans >= s.length) "-1" else ans)
}

fun test(s: String, g: Int): Int {
    var mm = g

    if (s == "") {
        return mm
    }

    if (s == "0") {
        return mm + 1
    }

    val x = s.toInt()
    val y = sqrt(x.toDouble()).toInt()
    if (y * y == x) {
        return mm
    }

    var mi = 10000
    for (i in 0..s.lastIndex) {
        val sb = StringBuilder(s)
        val t = sb.deleteCharAt(i).toString()

        if (t.length > 1 && t[0] == '0') {
            continue
        }

        mi = min(mi, test(t, g + 1))
    }
    return mi
}

