class Main: Runnable { override fun run() {
	repeat(readLine()!!.toInt()) {
		val (n, m, k) = readLine()!!.split(" ").map {it -> it.toInt()};
		
		var (horizontal, vertical) = Pair(k, n * m / 2 - k);
		if (n % 2 == 1) {
			// there's 1 extra row, fill it with (m / 2) horizontals
			horizontal -= m / 2;
			println(if (horizontal >= 0 && horizontal % 2 == 0 && vertical % 2 == 0) "Yes" else "No");
		}
		else if (m % 2 == 1) {
			vertical -= n / 2;
			println(if (vertical >= 0 && horizontal % 2 == 0 && vertical % 2 == 0) "Yes" else "No");
		}
		else {
			// even * even, can always be decomposed into 2*2 squares
			println(if (horizontal % 2 == 0 && vertical % 2 == 0) "Yes" else "No");
		}
	};
}}

