/** @author Spheniscine */
fun main() {
    output {
        val n = readInt()
        val P = readIntArray(n)

        var ro = (n+1)/2
        var re = n/2
        var icost = 0
        for(p in P) if(p > 0) if(p and 1 == 1) ro-- else re--
        for(i in 1 until n) {
            val p = P[i-1]
            val q = P[i]
            if(p != 0 && q != 0 && p and 1 != q and 1) icost++
        }

        val E = P.indices.filter { P[it] == 0 }

        val open = PriorityQueue<Entry>(11, compareBy { it.cost })
        open.add(Entry(ro, re, -1, icost, -1))
        val closed = IntArray(101 * 101 * 2) { inf }
        fun hash(o: Int, e: Int, lastPar: Int) = o.times(101).plus(e).times(2).plus(lastPar)
        fun enqueue(o: Int, e: Int, lastPar: Int, cost: Int, i: Int) {
            val h = hash(o, e, lastPar)
            if(cost < closed[h]) {
                closed[h] = cost
                open.add(Entry(o, e, lastPar, cost, i))
            }
        }

        val ans = run {
            while(true) {
                var (o, e, lastPar, cost, i) = open.remove()
                if(o == 0 && e == 0)
                    return@run cost
                if(lastPar != -1 && closed[hash(o, e, lastPar)] < cost) continue
                val j = E[i+1]

                if(j > 0 && P[j-1] != 0) lastPar = P[j-1] and 1

                if(o > 0) {
                    var ncost = cost
                    if(lastPar == 0) ncost++
                    if(j+1 < n && P[j+1] != 0 && P[j+1] and 1 == 0) ncost++
                    enqueue(o-1, e, 1, ncost, i+1)
                }
                if(e > 0) {
                    var ncost = cost
                    if(lastPar == 1) ncost++
                    if(j+1 < n && P[j+1] and 1 == 1) ncost++
                    enqueue(o, e-1, 0, ncost, i+1)
                }
            }
            0
        }

        println(ans)
    }
}

