fun find (c:Array<Int>,W:Int,map:MutableMap<Int,Long>):Long {
    return if (W == 0) 0 else map[W] ?: {
        val amount = Array(c.size) { max(1, W shr it) }
        val rem = amount.mapIndexed { index, m -> max(0, W - (m shl index)) }
        val ans = rem.mapIndexed { index, remain -> find(c, remain, map) + c[index] * amount[index].toLong() }
        ans.min()!!
    }.invoke().also { map.put(W, it) }
}

