@ExperimentalStdlibApi
private fun solve1391C() {

    val n = readInt()

    val mod = 1000_000_007L

    // ans = n! - 2^(n-1)

    var fact = 1L
    for (i in 2..n)
        fact = (fact * i) % mod

    var powtwo = 2L
    for (i in 3..n)
        powtwo = (powtwo * 2) % mod

    val ans = (fact + (mod - powtwo) % mod ) % mod

    println(ans)

}

fun modFactorial (n: Long, mod: Long) : Long {
    var result = 1L
    for (i in 1..n) result = (result * i) % mod
    return result
}

fun modExp (base: Long, exp: Long, mod: Long) : Long {
    var b = base
    var e = exp
    var result = 1L
    while (e > 0) {
        if (e % 2L == 0L) {
            b = (b * b) % mod
            e /= 2L
        } else {
            result = (result * b) % mod
            e--
        }
    }
    return result
}

fun cyclePermutations (n : Long, mod : Long) : Long {
    val r = modFactorial(n, mod) - modExp(2, n - 1, mod)
    return (r + mod) % mod
}

