const val eps = 1e-8

const val mod = 998244353

inline class MInt(val x: Int) {
    operator fun plus(m: MInt) = MInt((x + m.x) % mod)
    operator fun minus(m: MInt) = MInt((x - m.x + mod) % mod)
    operator fun times(m: MInt) = MInt((x.toLong() * m.x % mod).toInt())

    override fun toString() = x.toString()

    companion object {
        private val facts = mutableListOf(1)
        private val invs = mutableListOf(1, 1)
        private val invFacts = mutableListOf(1)
        fun Int.mod() = MInt(this)

        fun factorial(x: Int): MInt {
            while (x !in facts.indices) facts += (facts.last().mod() * facts.size.mod()).x
            return facts[x].mod()
        }

        fun inv(x: Int): MInt {
            while (x !in invs.indices) invs += (MInt((mod - mod / x) % mod) * invs[mod % x].mod()).x
            return invs[x].mod()
        }

        fun invFact(x: Int): MInt {
            while (x !in invFacts.indices) invFacts += (invFacts.last().mod() * inv(invFacts.size)).x
            return invFacts[x].mod()
        }
    }
}

fun c(n: Int, k: Int) = if (k in 0..n) MInt.factorial(n) * MInt.invFact(k) * MInt.invFact(n - k) else MInt(0)

@ExperimentalTime
@ExperimentalStdlibApi
class Task(private val fin: FastReader = FastReader()) {
    fun solve() {
        val n = fin.readInt()
        val maxHealth = fin.readInt()

        val powers = Array(maxHealth + 1) { x ->
            Array(n + 1) { null as MInt? }.apply {
                this[0] = MInt(1)
                for (p in 1 until size) this[p] = this[p - 1]!! * MInt(x)
            } as Array<MInt>
        }

        val cache = Array(n + 1) { IntArray(maxHealth + 1) { -1 } }
        fun go(alive: Int, damageGot: Int): MInt {
            if (alive == 0) return MInt(1)
            if (damageGot > maxHealth) return MInt(0)
            if (alive == 1) return MInt(0)
            cache[alive][damageGot].let { if (it != -1) return MInt(it) }
            var res = go(alive, damageGot + alive - 1)
            for (died in 1..alive) {
                val survived = alive - died
                val minWas = 1 + damageGot
                val maxWas = minOf(alive - 1 + damageGot, maxHealth)
                val numberOfWaysDied = c(alive, died)
                val healthForDied = powers[maxWas - minWas + 1][died]
                res += go(survived, damageGot + alive - 1) * numberOfWaysDied * healthForDied
            }
            cache[alive][damageGot] = res.x
            return res
        }

        val ans = go(n, 0)
        println(ans)
    }
}

