                @Suppress("DuplicatedCode")
                inline fun <reified T> Array<T>.countSort(
                    inPlace: Boolean = true,
                    type: (T) -> Int = { (it as Number).toInt() }
                ): Array<T> {
                    if (isEmpty()) return if (inPlace) this else emptyArray()
                    val types = IntArray(size) { type(this[it]) }
                    val min = types.minOrNull()!!
                    val max = types.maxOrNull()!!
                    val count = IntArray(max - min + 1)
                    for (t in types) count[t - min]++
