                        count[i] = sum
                        sum += shift
                    }
                    val sorted = arrayOfNullsSafe<T>(size)
                    for (i in 0 until size) sorted[count[types[i] - min]++] = this[i]
                    return if (inPlace) {
                        this.also { sorted.copyInto(this) }
                    } else {
