                    type: (T) -> Int = { (it as Number).toInt() }
                ): List<T> {
                    if (isEmpty()) return if (inPlace) this else emptyList()
                    val types = IntArray(size) { type(this[it]) }
                    val min = types.minOrNull()!!
                    val max = types.maxOrNull()!!
                    val count = IntArray(max - min + 1)
                    for (t in types) count[t - min]++
                    var sum = 0
                    for (i in count.indices) {
                        val shift = count[i]
                        count[i] = sum
                        sum += shift
                    }
                    val sorted = arrayOfNullsSafe<T>(size)
                    for (i in 0 until size) sorted[count[types[i] - min]++] = this[i]
                    return if (inPlace) {
                        return (this as MutableList<T>).apply {
                            for (i in indices) this[i] = sorted[i]
                        }
                    } else {
                        sorted.asList()
                    }
                }

                @Suppress("DuplicatedCode")
                inline fun IntArray.countSort(
                    inPlace: Boolean = true,
                    type: (Int) -> Int = { it -> it }
                ): IntArray {
                    if (isEmpty()) return if (inPlace) this else intArrayOf()
                    val types = IntArray(size) { type(this[it]) }
                    val min = types.minOrNull()!!
                    val max = types.maxOrNull()!!
                    val count = IntArray(max - min + 1)
                    for (t in types) count[t - min]++
                    var sum = 0
                    for (i in count.indices) {
                        val shift = count[i]
                        count[i] = sum
                        sum += shift
                    }
                    val sorted = IntArray(size)
                    for (i in 0 until size) sorted[count[types[i] - min]++] = this[i]
                    return if (inPlace) {
                        this.also { sorted.copyInto(this) }
                    } else {
                        sorted
                    }
                }
            }
        }

