    class BinarySearchUtils {
        companion object {
            @Suppress("DuplicatedCode")
            inline fun binarySearch(from: Int, to: Int, f: (Int) -> Boolean): Int {
                var l = from
                var r = to + 1
                while (r - l > 1) {
                    val m = (l + r) / 2
                    if (f(m)) l = m
                    else r = m
                }
                return l
            }

            inline fun binarySearch(from: Int = 0, f: (Int) -> Boolean): Int {
                var len = 1
                while (f(from + len)) len *= 2
                return binarySearch(from + len / 2, from + len - 1, f)
            }

            @Suppress("DuplicatedCode")
            inline fun binarySearchLong(from: Long, to: Long, f: (Long) -> Boolean): Long {
                var l = from
                var r = to + 1
                while (r - l > 1) {
                    val m = (l + r) / 2
                    if (f(m)) l = m
                    else r = m
                }
                return l
            }

            inline fun binarySearchLong(from: Long = 0, f: (Long) -> Boolean): Long {
                var len = 1L
                while (f(from + len)) len *= 2
                return binarySearchLong(from + len / 2, from + len - 1, f)
            }

            @Suppress("DuplicatedCode")
            inline fun binarySearchDouble(
                from: Double,
                to: Double,
