class Main internal constructor(inputStream: InputStream, val out: PrintWriter) {
    companion object {
        val ONLINE_JUDGE = System.getProperty("ONLINE_JUDGE") != null
    }

    private val br = BufferedReader(InputStreamReader(inputStream))
    private var st = StringTokenizer("")

    internal fun hasNext(): Boolean {
        while (!st.hasMoreTokens()) {
            val readLine = br.readLine() ?: return false
            st = StringTokenizer(readLine)
        }
        return true
    }

    private operator fun next() =
            if (hasNext()) st.nextToken()!!
            else throw RuntimeException("No tokens")

    internal fun nline() =
            if (hasNext()) st.nextToken("\n")
            else throw RuntimeException("No tokens")

    private fun ni() = next().toInt()
    private fun nii() = Pair(ni(), ni())
    private fun niii() = Triple(ni(), ni(), ni())
    private fun nia(n: Int) = IntArray(n) { ni() }
    private fun nia(m: Int, n: Int) = Array(m) { nia(n) }

    private fun nl() = next().toLong()
    private fun nll() = Pair(nl(), nl())
    private fun nlll() = Triple(nl(), nl(), nl())
    private fun nla(n: Int) = LongArray(n, { nl() })
    private fun nla(m: Int, n: Int) = Array(m) { nla(n) }

    private fun nd() = next().toDouble()
    private fun ndd() = Pair(nd(), nd())
    private fun nddd() = Triple(nd(), nd(), nd())
    private fun nda(n: Int) = DoubleArray(n) { nd() }
    private fun nda(m: Int, n: Int) = Array(m) { nda(n) }

    inline fun log(name: String, block: () -> Unit) {
        if (!ONLINE_JUDGE) {
            p("#$name: ")
            block()
            flush()
        }
    }

    inline fun log() = log("") { pln() }
    inline fun log(message: Any?, name: String = "") = log(name) { pln(message) }
    inline fun log(arr: IntArray?, name: String = "") = log(name) { pln(arr) }
    inline fun log(arr: LongArray?, name: String = "") = log(name) { pln(arr) }
    inline fun log(arr: DoubleArray?, name: String = "") = log(name) { pln(arr) }
    inline fun <T> log(arr: Array<T>?, name: String = "") = log(name) { pln(arr) }
    inline fun <T> log(stack: Stack<T>?, name: String = "") = log(name) { pln(stack) }
    inline fun <T> log(list: List<T>?, name: String = "") = log(name) { pln(list) }

    //prefix print
    inline fun prep(prefix: Boolean, separator: String, message: Any?) {
        if (prefix) {
            p(separator)
        }
        p(message)
    }

    inline fun p(message: Any?) = this.also { out.print(message) }

    inline fun p(arr: IntArray?, separator: String = " ") = this.also {
        arr?.fold(false, { prefix, t -> prep(prefix, separator, t); true })
    }

    inline fun p(arr: LongArray?, separator: String = " ") = this.also {
        arr?.fold(false, { prefix, t -> prep(prefix, separator, t); true })
    }

    inline fun p(arr: DoubleArray?, separator: String = " ") = this.also {
        arr?.fold(false, { prefix, t -> prep(prefix, separator, t); true })
    }

    inline fun <T> p(arr: Array<T>?, separator: String = " ") = this.also {
        arr?.fold(false, { prefix, t -> prep(prefix, separator, t); true })
    }

    inline fun <T> p(list: List<T>?, separator: String = " ") = this.also {
        list?.fold(false, { prefix, t -> prep(prefix, separator, t); true })
    }

    inline fun <T> p(stack: Stack<T>?, separator: String = " ") = this.also {
        stack?.fold(false, { prefix, t -> prep(prefix, separator, t); true })
    }

    inline fun pln() = this.also { out.println() }
    inline fun pln(message: Any?) = p(message).pln()
    inline fun pln(arr: IntArray?, separator: String = " ") = p(arr, separator).pln()
    inline fun pln(arr: LongArray?, separator: String = " ") = p(arr, separator).pln()
    inline fun pln(arr: DoubleArray?, separator: String = " ") = p(arr, separator).pln()
    inline fun <T> pln(list: List<T>?, separator: String = " ") = p(list, separator).pln()
    inline fun <T> pln(arr: Array<T>?, separator: String = " ") = p(arr, separator).pln()
    inline fun <T> pln(stack: Stack<T>?, separator: String = " ") = p(stack, separator).pln()

    inline fun flush() = out.flush()

    //////////////////////////////////////

    fun run() {
        val n = ni()
        var next = 0
        var playing1 = 1
        var playing2 = 2
        val check = HashSet<Int>()
        var winner = 0;
        for (i in 0..n - 1) {
            next = ni();
            if(next!=playing1&&next!=playing2){
                pln("NO")
                return
            }
            winner = next;
            for (i in 1..3) check.add(i)
            check.remove(playing1)
            check.remove(playing2)
            playing1=check.first();
            playing2=winner;
        }
        pln("YES")
    }

}

