fun main() {
    io.apply {

        val (m, s) = int to int

        if (s == 0 && m == 1) {
            cout .. 0 .. 0 .. nl
        } else if (s <= 0 || s > m * 9)
            cout .. -1 .. -1 .. nl
        else {
            val str = CharArray(m) { '0' }
            str[0] = '1'
            var q = s - 1
            for (i in m - 1 downTo 0) {
                var d = min(9, q)
                str[i] = (str[i] + d)
                q -= d
            }
            cout .. String(str) .. " "
            str.fill('0')
            q = s
            for (i in 0 until m) {
                var d = min(9, q)
                str[i] = (str[i] + d)
                q -= d
            }
            cout .. String(str) .. nl
        }

    }.cout.flush()
}

