fun df(a: IntArray): Pair<Triple<Long, Int, Int>, Triple<Long, Int, Int>> {

    var dif = 0L
    var lastIndex = 0
    var maxDif = 0L
    var maxIndex = 0
    var maxLength = 0
    for (i in 0 until a.size - 1 step 2) {
        dif += a[i + 1] - a[i]
        if (dif <= 0) {
            dif = 0
            lastIndex = i + 2
            continue
        }
        if (dif > maxDif) {
            maxDif = dif
            maxIndex = lastIndex
            maxLength = i + 2 - lastIndex
        }
    }

    var dif1 = 0L
    var lastIndex1 = 1
    var maxDif1 = 0L
    var maxIndex1 = 0
    var maxLength1 = 0
    for (i in 1 until a.size - 1 step 2) {
        dif1 += a[i + 1] - a[i]
        if (dif1 >= 0) {
            dif1 = 0
            lastIndex1 = i + 2
            continue
        }
        if (dif1 < maxDif1) {
            maxDif1 = dif1
            maxIndex1 = lastIndex1
            maxLength1 = i + 2 - lastIndex1
        }
    }

    return Pair(Triple(maxDif, maxIndex, maxLength), Triple(-maxDif1, maxIndex1, maxLength1))
}

