            val diff = z - a[x - 1][y - 1]
            rows[x - 1] = rows[x - 1] + diff
            columns[y - 1] = columns[y - 1] + diff
            a[x - 1][y - 1] = z
        }

        rowsP[0] = rows[0]
        for (j in 1 until n) {
            rowsP[j] = rowsP[j - 1] + rows[j]
            rowsPM[j] = rowsP[j - 1] + rowsPM[j - 1]
        }

