fun update(v: Int, tl: Int, tr: Int, pos: Int): Int {
    if (tl == tr) {
        t[v]++
        return t[v]
    } else {
        val tm = (tl + tr) / 2
        val res = if (pos <= tm) {
            update(v * 2, tl, tm, pos)
        } else {
            update(v * 2 + 1, tm + 1, tr, pos)
        }
        t[v] = t[v * 2] + t[v * 2 + 1]
        return res
    }
}

fun delete(v: Int, tl: Int, tr: Int, pos: Int): Int {
//    println("$v [$tl, $tr] = ${t[v]}, pos = $pos")
    if (tl == tr) {
        t[v]--
        return tl
    } else {
        val tm = (tl + tr) / 2
        val res = if (pos <= t[v * 2]) {
            delete(v * 2, tl, tm, pos)
        } else {
            delete(v * 2 + 1, tm + 1, tr, pos - t[v * 2])
        }
        t[v] = t[v * 2] + t[v * 2 + 1]
        return res
    }
}

