        else{
            val firstPrimeMultiple = findFirstPrimeMultiple(n)
            if(firstPrimeMultiple == n) println("${n-1} 1")
            else {
                val number = (n.div(firstPrimeMultiple))
                println("$number ${n-number}")
            }
        }
    }
}

fun findFirstPrimeMultiple(n: Int): Int{
    repeat(sqrt(n.toDouble()).toInt()+10){
        if(it >1) {
            val remaining = (n / it).toInt()
            if (remaining * it == n) return it
        }
    }
    return n
}

