fun PrintWriter.solve(sc: FastScanner) {
    val t = sc.nextInt()
    for (_i in 0 until t) {
        val n = sc.nextInt()
        var p = -1
        var d = 2
        while (d * d <= n) {
            if (n % d == 0) {
                p = d
                break
            }
            d++
        }
        if (p == -1) p = n
        val v = n / p
        println("$v ${n - v}")
    }
}

