fun main() {
    val jin = FastScanner()
    val n = jin.nextInt()
    val m = jin.nextInt()
    val q = jin.nextInt()
    val p = IntArray(n + 1)
    for (j in 1..n) {
        p[j] = jin.nextInt()
    }
    val edges = Array(m) {
        val a = jin.nextInt()
        val b = jin.nextInt()
        Edge(p[a], p[b])
    }
    val queries = Array(q) {
        val type = jin.nextInt()
        val param = jin.nextInt()
        if (type == 2) {
            edges[param - 1].removal = it
        }
        Query(type, param)
    }
    edges.sortByDescending { it.removal }
    val union = IntArray(n + 1) { it }
    val rank = IntArray(n + 1) { 1 }
    fun getUnion(u: Int): Int {
        if (union[u] != union[union[u]]) {
            union[u] = getUnion(union[u])
        }
        return union[u]
    }
    val children = Array(n + 1) { mutableListOf<Int>() }
    for (edge in edges) {
        val u = getUnion(edge.a)
        val v = getUnion(edge.b)
        if (u != v) {
            if (rank[u] > rank[v]) {
                children[u].add(v)
                union[v] = u
                rank[u] += rank[v]
                if (edge.removal < q) {
                    queries[edge.removal].child = v
                }
            } else {
                children[v].add(u)
                union[u] = v
                rank[v] += rank[u]
                if (edge.removal < q) {
                    queries[edge.removal].child = u
                }
            }
        }
    }
    val l = IntArray(n + 1)
    var currL = 1
    fun recur(a: Int) {
        l[a] = currL
        currL++
        for (b in children[a]) {
            recur(b)
        }
    }
    val treeSet = TreeSet<Int>()
    for (a in 1..n) {
        if (l[a] == 0) {
            treeSet.add(currL)
            recur(getUnion(a))
        }
    }
    treeSet.add(n + 1)
    val segTree = MaxSegmentTree(1, n)
    for (a in 1..n) {
        segTree[l[a]] = a
    }
    val out = StringBuilder()
    for (query in queries) {
        if (query.type == 1) {
            val a = p[query.param]
            val res = segTree[treeSet.floor(l[a])!!, treeSet.higher(l[a])!! - 1]
            //println("type 1 for $a -> ${Pair(treeSet.floor(l[a])!!, treeSet.higher(l[a])!! - 1)} => $res")
            out.appendln(res)
            if (res != 0) {
                segTree[l[res]] = 0
            }
        } else {
            //println("bonk ${queries[j].child}")
            if (query.child != 0) {
                treeSet.add(l[query.child])
            }
        }
    }
    print(out)
}

