                readInt() - 1
            }

            init {
                val E = BooleanArray(m)
                for(i in 0 until q) if(T[i] == 2) E[X[i]] = true
                for(i in 0 until m) if(!E[i]) {
                    T.add(2)
                    X.add(i)
                }
                q = T.size
            }

            val boss = IntList()
            val dsu = IntList(n) { it }
            val G = MutableList(n) { IntList(0) }

            fun addVertex(): Int {
                G.add(IntList(2))
                dsu.add(dsu.size)
                return dsu.lastIndex
            }

            tailrec fun root(v: Int): Int = if(dsu[v] == v) v else {
                dsu[v] = dsu[dsu[v]]
                root(dsu[v])
            }

            fun merge(u: Int, v: Int) {
                val ru = root(u)
                val rv = root(v)

                if(ru == rv) return

                val b = addVertex()
                dsu[ru] = b
                dsu[rv] = b
                G[b].add(ru)
                G[b].add(rv)
            }

            init {
                for(i in q-1 downTo 0) {
                    val x = X[i]
                    when(T[i]) {
                        1 -> boss.add(root(x))
