fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
//    val startTime = System.nanoTime()

    val numCases = 1//readInt()
    case@ for(case in 1..numCases) {
//        print("Case #$case: ")

        object {
            val n = readInt()
            val m = readInt()
            val q = readInt()

            val P = readIntArray(n)

            val A = IntArray(m)
            val B = IntArray(m) {
                A[it] = readInt() - 1
                readInt() - 1
            }

            val T = IntArray(q)
            val X = IntArray(q) {
                T[it] = readInt()
                readInt() - 1
            }

            val boss = IntList()
            val dsu = IntList(n) { it }
            val empty = IntList(0)
            val G = MutableList(n) { empty }

            fun addVertex(): Int {
                G.add(IntList(2))
                dsu.add(dsu.size)
                return dsu.lastIndex
            }

            tailrec fun root(v: Int): Int = if(dsu[v] == v) v else {
                dsu[v] = dsu[dsu[v]]
                root(dsu[v])
            }

            fun merge(u: Int, v: Int) {
                val ru = root(u)
                val rv = root(v)

                if(ru == rv) return

                val b = addVertex()
                dsu[ru] = b
                dsu[rv] = b
                G[b].add(ru)
                G[b].add(rv)
            }

            init {
                val E = BooleanArray(m)
                for(i in 0 until q) if(T[i] == 2) E[X[i]] = true
                for(i in 0 until m) if(!E[i]) {
                    merge(A[i], B[i])
                }

                for(i in q-1 downTo 0) {
                    val x = X[i]
                    when(T[i]) {
                        1 -> boss.add(root(x))
                        2 -> merge(A[x], B[x])
                    }
                }
                boss.reverse()

                val start = IntArray(dsu.size) { -1 }
                val end = IntArray(dsu.size)
                val stk = IntList()
                var eul = 0
                for(i in dsu.indices) if(start[i] == -1) {
                    val r = root(i)
                    stk.add(r)

                    while(stk.isNotEmpty()) {
                        val u = stk.pop()
                        if(start[u] == -1) {
                            start[u] = eul++
                            stk.add(u)
                            for(v in G[u]) stk.add(v)
                        } else {
                            end[u] = eul
                        }
                    }
                }

                val S = SegmentTree(eul)

                for(i in 0 until n) {
                    val j = start[i]
                    S.delayedSet(j, IntPair(P[i], j))
                }

                S.pushDelayed()

                for(b in boss) {
                    val (x, j) = S[start[b], end[b]]
                    println(x)
                    S[j] = IntPair(0, j)
                }
            }

        }
    }

//    iprintln("Time: ${(System.nanoTime() - startTime) / 1000000} ms")
}

class SegmentTree(
    val size: Int) {

    val identityValue: IntPair = IntPair(-1, -1)
    inline fun combiner(a: IntPair, b: IntPair): IntPair = if(a.x >= b.x) a else b


    @Suppress("UNCHECKED_CAST")
    val array = IntPairArray(size shl 1) { identityValue }

    inline val lastIndex get() = size - 1
    inline val indices get() = 0 until size
    val asList: List<IntPair> by lazy {
        object : AbstractList<IntPair>() {
            override val size: Int get() = this@SegmentTree.size
            override fun get(index: Int): IntPair = this@SegmentTree[index]
        }
    }

    inline fun build(generator: (Int) -> IntPair) {
        for(i in 0 until size) {
            array[i + size] = generator(i)
        }
        for(i in size-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** alternative to build for arbitrary order **/
    fun delayedSet(i: Int, v: IntPair) { array[i + size] = v }
    fun pushDelayed() {
        for(i in size-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** instantiates values from an iterable, O(n) time */
    fun copyFrom(iterable: Iterable<IntPair>) {
        run {
            iterable.forEachIndexed { i, t ->
                if(i > lastIndex) return@run
                array[i + size] = t
            }
        }
        for(i in size-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Updates a value, O(log n) time */
    operator fun set(index: Int, value: IntPair) {
        require(index in 0 until size)
        var i = index + size
        array[i] = value
        while(true) {
            i = i shr 1
            if(i <= 0) break
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Gets a value by its index, O(1) time */
    operator fun get(index: Int): IntPair {
        require(index in 0 until size)
        return array[index + size]
    }

    /** gets the result of applying the monoid operation to the values in the index range, O(log n) time */
    operator fun get(start: Int, endExclusive: Int): IntPair {
        var l = maxOf(start, 0) + size
        var r = minOf(endExclusive, size) + size

        // two accumulators to support non-commutative monoids
        var lAcc = identityValue
        var rAcc = identityValue

        while(l < r) {
            if(l and 1 == 1) {
                lAcc = combiner(lAcc, array[l++])
            }
            if(r and 1 == 1) {
                rAcc = combiner(array[--r], rAcc)
            }

            l = l shr 1
            r = r shr 1
        }

        return combiner(lAcc, rAcc)
    }

    operator fun get(range: IntRange) = get(range.first, range.last + 1)
}

