import java.io.PrintWriter
import java.util.Arrays
import java.util.NoSuchElementException
import java.util.TreeSet
import kotlin.math.*
import kotlin.random.Random
import kotlin.collections.sort as _sort
import kotlin.collections.sortDescending as _sortDescending
import kotlin.io.println as iprintln


/** @author Spheniscine */
fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
//    val startTime = System.nanoTime()

    val numCases = 1//readInt()
    case@ for(case in 1..numCases) {
//        print("Case #$case: ")

        object {
            val n = readInt()
            val m = readInt()
            val q = readInt()

            val P = readIntArray(n)
            val Q = IntArray(n + 1)
            init {
                for(i in 0 until n) Q[P[i]] = i
            }

            val A = IntArray(m)
            val B = IntArray(m) {
                A[it] = readInt() - 1
                readInt() - 1
            }

            val T = IntArray(q)
            val X = IntArray(q) {
                T[it] = readInt()
                readInt() - 1
            }

            val edgeRemoved = BooleanArray(m)

            init {
                for (i in 0 until q) {
                    if (T[i] == 2) edgeRemoved[X[i]] = true
                }
            }

            val C = Array(n) { i -> _Ez_Int_TreeSet().also { it.add(P[i]) } }
            val par = IntArray(n) { it }

            val hist = IntList()
            fun merge(ei: Int): Int {
                var u = par[A[ei]]
                var v = par[B[ei]]

                if(u == v) return -1

                if(C[u].size() < C[v].size()) u = v.also { v = u }
                for(x in C[v]) {
                    par[Q[x]] = u
                    C[u].add(x)
                }

                return v
            }

            init {
                for(i in 0 until m) if(!edgeRemoved[i]) merge(i)
                for(i in q-1 downTo 0) if(T[i] == 2) {
                    hist.add(merge(X[i]))
                }

                for(i in 0 until q) {
                    val x = X[i]
                    when(T[i]) {
                        1 -> {
                            val ans = C[par[x]].removeLast()
                            println(ans)
                        }
                        2 -> {
                            val v = hist.pop()
                            if (v != -1) {
                                val u = par[v]

                                if(C[v].size() > 0) {
                                    var w = C[v].first
                                    while (true) {
                                        if (!C[u].remove(w)) C[v].remove(w)
                                        par[Q[w]] = v
                                        w = C[v].higher(w)
                                        if(C[v].returnedNull()) break
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

//    iprintln("Time: ${(System.nanoTime() - startTime) / 1000000} ms")
}

