fun check(n: Int, vs: Array<Vertex>, marked: MutableList<Int>): Int? {
    val used = mutableSetOf<Domino>()
    for (x in 1..n) {
        val v = vs[x]
        for (u in v.edge) {
            if (v.n >= u.n) continue
            used.add(Domino(minOf(marked[v.n - 1], marked[u.n - 1]), maxOf(marked[v.n - 1], marked[u.n - 1])))
        }
    }
    return used.size
}

