fun main(args: Array<String>) {
  val scanner = Scanner(System.`in`)
  val k = scanner.nextInt()
  val title = scanner.next().toCharArray()

  if (doStuff(k, title)) {
    println(title)
  }
  else {
    println("IMPOSSIBLE")
  }
}

private fun doStuff(k: Int, title: CharArray): Boolean {
  val n = title.size
  val half = n / 2

  val unusedChars = BitSet(k)
  for (ch in title) {
    if (ch == '?') continue
    unusedChars.set(ch.minus(97).toInt())
  }
  unusedChars.flip(0, k)

  for (leftI in 0..half) {
    val rightI = n - leftI - 1

    val left = title[leftI]
    val right = title[rightI]

    val leftQ = left == '?'
    val rightQ = right == '?'
    if (leftQ && rightQ) continue

    if (leftQ) {
      title[leftI] = right
    }
    else if (rightQ) {
      title[rightI] = left
    }
    else if (left != right) {
      return false
    }
  }

  var lastUsedIndex = k - 1
  for (rightI in half until n) {
    val leftI = n - rightI - 1

    val left = title[leftI]
    val right = title[rightI]

    if (left == '?' && right == '?') {
      lastUsedIndex = unusedChars.previousSetBit(lastUsedIndex)
      val unusedChar = if (lastUsedIndex == -1) {
        'a'
      }
      else {
        unusedChars.set(lastUsedIndex, false)
        lastUsedIndex.plus(97).toChar()
      }
      title[leftI] = unusedChar
      title[rightI] = unusedChar
    }
  }

  return unusedChars.isEmpty
}

