fun mmin(a1: Int, a2: Int, k1: Int, k2: Int, n: Int): Int {
    var ansMin = 0
    var n = n

    val m = ArrayList<Int>()
    for (i in 1..a1) m.add(k1)
    for (i in 1..a2) m.add(k2)

    var key = false
    while (!key) {
        key = true
        for (i in 0 until m.size) {
            val k = m[i]
            if (k <= 1) continue
            n--
            if (n < 0) {
                key = true
                break
            }
            m[i]--
            key = false
        }
    }

    ansMin = max(0, min(n, a1 + a2))

    return ansMin
}

fun mmax(a1: Int, a2: Int, k1: Int, k2: Int, n: Int): Int {
    var ansMax = 0

    val q = ArrayList<Int>()
    for (i in 1..a1) q.add(k1)
    for (i in 1..a2) q.add(k2)
    var nmax = n
    q.sort()

    while (nmax > 0) {
        for (t in q) {
            nmax -= t
            if (nmax >= 0) {
                ansMax++
            }
        }
    }

    return ansMax
}

