    var x = 0L
    var ans = getSum(y)
    while (y > 0) {
      y--
      x += m
      val s = getSum(x)
      val cur = (y + 1) * s + (x + 1) * getSum(y)
      ans = Math.max(ans, cur)
    }
    output.println(ans)
  }

  private fun getSum(s: Long): Long {
    return s * (s + 1) / 2
  }

  private fun read2() {
    val n = input.nextInt()
    val a = Array(n, { IntArray(n) })
    for (i in 0..n - 1) {
      for (j in 0..n - 1) {
        a[i][j] = input.nextInt()
      }
    }
    for (i in 0..n - 1) {
      for (j in 0..n - 1) {
        if (a[i][j] != 1) {
          var ok = false
          for (s in 0..n - 1) {
            for (k in 0..n - 1) {
              if (a[i][j] == a[i][s] + a[k][j]) {
                ok = true
              }
            }
          }
          if (!ok) {
            output.println("No")
            return
          }
        }
      }
    }
    output.println("Yes")
  }


