private class `CF731-D2-A` {
    fun solveTestCase(): Int {
        var total = 0
        var first = false
        var origin: Int = 0
        val aVal = 'a'.toInt()
        val numOfAlphabet = 26
        for (c in read()) {
            if(first) {
                origin = c.toInt() - aVal
                first = false
            } else {
                var destination = c.toInt() - aVal
                var clockwise = destination - origin
                var counterClock = origin - destination
                if (clockwise < 0)
                    clockwise += numOfAlphabet
                if (counterClock < 0)
                    counterClock += numOfAlphabet
                total += min(clockwise, counterClock)
                origin = destination
            }
        }

        return total
    }
}

