fun tabs(n: Int, k: Int, b: Int) : ArrayList<Int> {

    var list = ArrayList<Int>()
    var b2 = b
    while (b2 < n) {
        list.add(b2)
        b2+=k
    }

    b2 = b

    while (b2 >= 0) {
        list.add(b2)
        b2-=k
    }

    return list
}

