class B {
    fun solve(input : InputStream, output : OutputStream) {
        val reader = InputReader(BufferedInputStream(input))
        val writer = PrintWriter(BufferedOutputStream(output))

        val n = reader.nextInt()
        val pos = reader.nextInt()
        val l = reader.nextInt()
        val r = reader.nextInt()

        writer.println(solve(n, pos, l, r))

        writer.close()
    }

    fun range(a : Int, b : Int) : Int {
        return abs(a - b)
    }

    fun solve(n : Int, pos : Int, l : Int, r : Int) : Int {
        if (l == 1 && r == n) {
            return 0
        }
        if (l == 1) {
            return range(pos, r) + 1
        }
        if (r == n) {
            return range(pos, l) + 1
        }

        val leftFirst = range(pos, l) + 1 + range(l, r) + 1
        val rightFirst = range(pos, r) + 1 + range(l, r) + 1
        return min(leftFirst, rightFirst)
    }

    private class InputReader(stream: InputStream) {
        var reader: BufferedReader
        var tokenizer: StringTokenizer? = null

        init {
            reader = BufferedReader(InputStreamReader(stream), 32768)
            tokenizer = null
        }

        operator fun next(): String {
            while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
                try {
                    tokenizer = StringTokenizer(reader.readLine())
                } catch (e: IOException) {
                    throw RuntimeException(e)
                }

            }
            return tokenizer!!.nextToken()
        }

        fun nextInt(): Int {
            return Integer.parseInt(next())
        }

        fun nextLong(): Long {
            return java.lang.Long.parseLong(next())
        }
    }
}

