    fun mergeSort(a: IntArray) {
        val n = a.size
        if (n < 2) return
        val mid = n / 2; val left = IntArray(mid); val right = IntArray(n - mid)
        for (i in 0 until mid) left[i] = a[i]
        for (i in mid until n) right[i - mid] = a[i]
        mergeSort(left);mergeSort(right);merge(left, right, a)
    }

    fun merge(left: IntArray, right: IntArray, a: IntArray) {
        val nLeft = left.size; val nRight = right.size
        var i = 0; var j = 0; var k = 0
        while (i < nLeft && j < nRight) {
            if (left[i] <= right[j]) {
                a[k] = left[i];k++;i++
            } else {
                a[k] = right[j]; k++;j++
            }
        }
        while (i < nLeft) {a[k] = left[i]; i++; k++}
        while (j < nRight){a[k] = right[j]; j++; k++}
    }

