fun sportMafia(moves: Long, candiesLeft: Long): Int {
    var left = 0L
    var right = moves
    while (left <= right) {
        val current = left + (right - left) / 2
        val broughtIn = sumOf(current)
        val eaten = moves - current
        val resultingCandies = broughtIn - eaten
        when {
            resultingCandies < candiesLeft -> {
                left = current + 1
            }
            resultingCandies == candiesLeft -> return eaten.toInt()
            resultingCandies > candiesLeft -> {
                right = current - 1
            }
        }
    }
    throw IllegalArgumentException("solution not found")
}

