private fun List<Int>.sumPrefixes(): List<Int> {
    if (this.isEmpty()) {
        return emptyList()
    }
    val resultList = ArrayList<Int>(this.size)
    resultList.add(this[0])
    for (i in 1 until this.size) {
        resultList.add(resultList[i - 1] + this[i])
    }
    return resultList
}

