fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
    val percent = ModInt(100).inverse()

    val n = readInt()
    val pipes = List(n) { Pipe(readInt(), readInt(), percent * readInt()) }
    val tree = SegmentTree(n, null, nullIdentityCombiner(Seg::plus))

    tree.build { i ->
        Seg(
            ll = 1 - pipes[i].p,
            lr = ModInt(0),
            rl = ModInt(0),
            rr = pipes[i].p,
            ban = NONE
        )
    }

    val cols = ArrayList<Collision>(n-1 shl 1)

    for(i in 0 until n-1) {
        val a = pipes[i]
        val b = pipes[i+1]

        val d = b.x - a.x
        cols.add(Collision(i, RL, d, a.v + b.v))
        if(a.v > b.v) cols.add(Collision(i, RR, d, a.v - b.v))
        else if(a.v < b.v) cols.add(Collision(i, LL, d, b.v - a.v))
    }

    cols.sortWith(Collision.comparator)

    val vi = ModIntArray(cols.size) { ModInt(cols[it].v) }.inverseOfEach()
    var currProb = ModInt(1)
    var ans = ModInt(0)
    for(i in cols.indices) {
        val (a, t, d) = cols[i]
        tree[a] = tree[a]!!.copy(ban = t)
        val prob = tree.root!!.sum
        ans += (currProb - prob) * d * vi[i]
        currProb = prob
    }

    println(ans.int)
}

data class Pipe(val x: Int, val v: Int, val p: ModInt)
data class Collision(val a: Int, val type: CollisionType, val d: Int, val v: Int) {
    companion object {
        val comparator = Comparator<Collision> { a, b ->
            (a.d.toLong() * b.v).compareTo(b.d.toLong() * a.v)
        }
    }
}

typealias CollisionType = Byte
const val NONE: CollisionType = 0
const val LL: CollisionType = 1
const val RL: CollisionType = 2
const val RR: CollisionType = 3

data class Seg(val ll: ModInt, val lr: ModInt, val rl: ModInt, val rr: ModInt, val ban: CollisionType) {
    val sum get() = ll + lr + rl + rr

    operator fun plus(b: Seg): Seg {
        // LR never banned
        var cll = ll * b.rl
        var clr = ll * b.rr
        var crl = rl * b.rl
        var crr = rl * b.rr

        // any ban implies RL banned
        if(ban == NONE) {
            cll += lr * b.ll
            clr += lr * b.lr
            crl += rr * b.ll
            crr += rr * b.lr
        }

        if(ban != LL) {
            cll += ll * b.ll
            clr += ll * b.lr
            crl += rl * b.ll
            crr += rl * b.lr
        }

        if(ban != RR) {
            cll += lr * b.rl
            clr += lr * b.rr
            crl += rr * b.rl
            crr += rr * b.rr
        }

        return Seg(cll, clr, crl, crr, b.ban)
    }
}

class SegmentTree<T>(
    val size: Int,
    val identityValue: T,
    val combiner: (T, T) -> T) {

    private val tsize get() = if(size <= 1) size else Integer.highestOneBit(size - 1) shl 1

    /* degenericization helpers
    val identityValue: T = TODO()
    fun combiner(a: T, b: T): T = TODO()
    */

    @Suppress("UNCHECKED_CAST")
    private val array = Array<Any?>(tsize shl 1) { identityValue } as Array<T>

    val root get() = array[1]

    inline val lastIndex get() = size - 1
    inline val indices get() = 0 until size
    val asList: List<T> by lazy {
        object : AbstractList<T>() {
            override val size: Int get() = this@SegmentTree.size
            override fun get(index: Int): T = this@SegmentTree[index]
        }
    }

    fun build(generator: (Int) -> T) {
        for(i in 0 until size) {
            array[i + tsize] = generator(i)
        }
        for(i in tsize-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** instantiates values from an iterable, O(n) time */
    fun copyFrom(iterable: Iterable<T>) {
        run {
            iterable.forEachIndexed { i, t ->
                if(i > lastIndex) return@run
                array[i + tsize] = t
            }
        }
        for(i in tsize-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Updates a value, O(log n) time */
    operator fun set(index: Int, value: T) {
        require(index in 0 until size)
        var i = index + tsize
        array[i] = value
        while(true) {
            i = i shr 1
            if(i <= 0) break
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Gets a value by its index, O(1) time */
    operator fun get(index: Int): T {
        require(index in 0 until size)
        return array[index + tsize]
    }

    /** gets the result of applying the monoid operation to the values in the index range, O(log n) time */
    operator fun get(start: Int, endExclusive: Int): T {
        var l = maxOf(start, 0) + tsize
        var r = minOf(endExclusive, size) + tsize

        // two accumulators to support non-commutative monoids
        var lAcc = identityValue
        var rAcc = identityValue

        while(l < r) {
            if(l and 1 == 1) {
                lAcc = combiner(lAcc, array[l++])
            }
            if(r and 1 == 1) {
                rAcc = combiner(array[--r], rAcc)
            }

            l = l shr 1
            r = r shr 1
        }

        return combiner(lAcc, rAcc)
    }

    operator fun get(range: IntRange) = get(range.first, range.last + 1)
}

/** Converts a semigroup to a monoid by using null as the identity value. */
inline fun <T: Any> nullIdentityCombiner(crossinline combiner: (T, T) -> T): (T?, T?) -> T? = { a, b ->
    when {
        b == null -> a
        a == null -> b
        else -> combiner(a, b)
    }
}

fun ModIntArray.inverseOfEach(): ModIntArray {
    if(isEmpty()) return this
    var acc = ModInt(1)
    val res = ModIntArray(size) { i ->
        acc *= this[i]
        acc
    }
    acc = acc.inv_unmemoized()
    for(i in lastIndex downTo 1) {
        res[i] = acc * res[i-1]
        acc *= this[i]
    }
    res[0] = acc

    return res
}

const val MOD = 998244353
const val TOTIENT = MOD - 1 // assumes MOD is prime

infix fun Int.umod(mod: Int): Int = (this % mod).let { (it shr Int.SIZE_BITS - 1 and mod) + it }
infix fun Long.umod(mod: Long) = (this % mod).let { (it shr Long.SIZE_BITS - 1 and mod) + it }
infix fun Long.umod(mod: Int) = umod(mod.toLong()).toInt()

fun Int.mulMod(other: Int, mod: Int) = toLong() * other umod mod

fun Int.powMod(exponent: Int, mod: Int): Int {
    if(exponent < 0) error("Inverse not implemented")
    var res = 1L
    var e = exponent
    var b = umod(mod).toLong()

    while(e > 0) {
        if(e and 1 == 1) {
            res = res * b % mod
        }
        e = e shr 1
        b = b * b % mod
    }
    return res.toInt()
}

inline fun Int.toModInt() = ModInt(this umod MOD)
inline fun Long.toModInt() = ModInt(this umod MOD)

/** note: Only use constructor for int within modulo range, otherwise use toModInt **/
inline class ModInt(val int: Int) {
    companion object {
        /** can't seem to make these private or inlined without causing compiler issues */
        @JvmField val _invMemo = HashMap<ModInt, ModInt>()
        fun _invMemoized(m: ModInt) = _invMemo.getOrPut(m) { m.inv_unmemoized() }
    }

    // normalizes an integer that's within range [-MOD, MOD) without branching
    private inline fun normalize(int: Int) = ModInt((int shr Int.SIZE_BITS - 1 and MOD) + int)

    operator fun plus(other: ModInt) = normalize(int + other.int - MOD) // overflow-safe even if MOD >= 2^30
    inline operator fun plus(other: Int) = plus(other.toModInt())
    operator fun inc() = normalize(int + (1 - MOD))

    operator fun minus(other: ModInt) = normalize(int - other.int)
    inline operator fun minus(other: Int) = minus(other.toModInt())
    operator fun dec() = normalize(int - 1)
    operator fun unaryMinus() = normalize(-int)

    operator fun times(other: ModInt) = ModInt((int.toLong() * other.int % MOD).toInt())
    inline operator fun times(other: Int) = ModInt(int.mulMod(other, MOD))

    fun pow(exponent: Int): ModInt {
        val e = if(exponent < 0) {
            require(int != 0) { "Can't invert/divide by 0" }
            exponent umod TOTIENT
        } else exponent
        return ModInt(int.powMod(e, MOD))
    }

    fun pow(exponent: Long) = if(int == 0) when {
        exponent > 0 -> this
        exponent == 0L -> ModInt(1)
        else -> error("Can't invert/divide by 0")
    } else pow(exponent umod TOTIENT)

    inline fun inverse() = inv_memoized() /** NOTE: Change if necessary */

    fun inv_unmemoized(): ModInt {
        require(int != 0) { "Can't invert/divide by 0" }
        return pow(TOTIENT - 1)
    }
    inline fun inv_memoized() = _invMemoized(this)

    operator fun div(other: ModInt) = times(other.inverse())
    inline operator fun div(other: Int) = div(other.toModInt())

    override inline fun toString() = int.toString()
}

