inline val NONE get() = CollisionType(0)
inline val LL get() = CollisionType(1)
inline val RL get() = CollisionType(2)
inline val RR get() = CollisionType(3)

data class Seg(val ll: ModInt, val lr: ModInt, val rl: ModInt, val rr: ModInt, val ban: CollisionType) {
    val sum get() = ll + lr + rl + rr

    operator fun plus(b: Seg): Seg {
        // LR never banned
        var cll = ll * b.rl
        var clr = ll * b.rr
        var crl = rl * b.rl
        var crr = rl * b.rr

        // any ban implies RL banned
        if(ban.i == NONE.i) {
            cll += lr * b.ll
            clr += lr * b.lr
            crl += rr * b.ll
            crr += rr * b.lr
        }

        if(ban.i != LL.i) {
            cll += ll * b.ll
            clr += ll * b.lr
            crl += rl * b.ll
            crr += rl * b.lr
        }

        if(ban.i != RR.i) {
            cll += lr * b.rl
            clr += lr * b.rr
            crl += rr * b.rl
            crr += rr * b.rr
        }

        return Seg(cll, clr, crl, crr, b.ban)
    }
}

class SegmentTree<T>(
    val size: Int,
    val identityValue: T,
    val combiner: (T, T) -> T) {

    private val tsize get() = if(size <= 1) size else Integer.highestOneBit(size - 1) shl 1

    /* degenericization helpers
    val identityValue: T = TODO()
    fun combiner(a: T, b: T): T = TODO()
    */

    @Suppress("UNCHECKED_CAST")
    private val array = Array<Any?>(2 * tsize) { identityValue } as Array<T>

    val root get() = array[1]

    inline val lastIndex get() = size - 1
    inline val indices get() = 0 until size
    val asList: List<T> by lazy {
        object : AbstractList<T>() {
            override val size: Int get() = this@SegmentTree.size
            override fun get(index: Int): T = this@SegmentTree[index]
        }
    }

    fun build(generator: (Int) -> T) {
        for(i in 0 until size) {
            array[i + tsize] = generator(i)
        }
        for(i in tsize-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** instantiates values from an iterable, O(n) time */
    fun copyFrom(iterable: Iterable<T>) {
        run {
            iterable.forEachIndexed { i, t ->
                if(i > lastIndex) return@run
                array[i + tsize] = t
            }
        }
        for(i in tsize-1 downTo 1) {
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Updates a value, O(log n) time */
    operator fun set(index: Int, value: T) {
        require(index in 0 until size)
        var i = index + tsize
        array[i] = value
        while(true) {
            i = i shr 1
            if(i <= 0) break
            array[i] = combiner(array[i shl 1], array[i shl 1 or 1])
        }
    }

    /** Gets a value by its index, O(1) time */
    operator fun get(index: Int): T {
        require(index in 0 until size)
        return array[index + tsize]
    }

    /** gets the result of applying the monoid operation to the values in the index range, O(log n) time */
    operator fun get(start: Int, endExclusive: Int): T {
        var l = maxOf(start, 0) + tsize
        var r = minOf(endExclusive, size) + tsize

        // two accumulators to support non-commutative monoids
        var lAcc = identityValue
        var rAcc = identityValue

        while(l < r) {
            if(l and 1 == 1) {
                lAcc = combiner(lAcc, array[l++])
            }
            if(r and 1 == 1) {
                rAcc = combiner(array[--r], rAcc)
            }

            l = l shr 1
            r = r shr 1
        }

        return combiner(lAcc, rAcc)
    }

    operator fun get(range: IntRange) = get(range.first, range.last + 1)
}

