import java.util.*

fun pair(x: Int): Int {
    if (x >= 0) {
        return x xor 1
    } else {
        return x.inv() xor 2
    }
}

fun current(x: Int) = when {
    x >= 0 -> x
    else -> x.inv()
}

fun opposite(x: Int) = pair(x.inv())

fun oppositePair(x: Int) = current(x) xor 3

fun main(args: Array<String>) = with(Scanner(System.`in`)) {
    val opposite = arrayOf(arrayOf(0, 8), arrayOf(4, 20), arrayOf(12, 16))
    val other = arrayOf(arrayOf(4, 16, 20, 12), arrayOf(8, 16.inv(), 2, 13.inv()),
            arrayOf(0.inv(), 4.inv(), 8.inv(), 21.inv()))
    val a = IntArray(24) { nextInt() }
    loop@ for (op in opposite.indices) {
        for (i in opposite[op]) {
            for (j in 0..3) {
                if (a[i + j] != a[i]) {
                    continue@loop
                }
            }
        }
        val x = other[op]
        for (i in 0..3) {
            if (a[current(x[i])] != a[pair(x[i])]) {
                continue@loop
            }
            if (a[opposite(x[i])] != a[oppositePair(x[i])]) {
                continue@loop
            }
