class Cube {
    private val colors = Array(24) { sc.nextInt() }

    private val sides = arrayOf(
        arrayOf(1, 2, 3, 4),
        arrayOf(5, 6, 7, 8),
        arrayOf(13, 14, 15, 16),
        arrayOf(17, 18, 19, 20),
        arrayOf(21, 22, 23, 24),
        arrayOf(9, 10, 11, 12)
    )

    fun rotate(rotation: List<Int>) {
        val x = colors[rotation[0] - 1]
        val y = colors[rotation[1] - 1]
        for (i in 0..2) {

            colors[rotation[2 * i] - 1] = colors[rotation[2 * i + 2] - 1]
            colors[rotation[2 * i + 1] - 1] = colors[rotation[2 * i + 3] - 1]
        }

        colors[rotation[6] - 1] = x
        colors[rotation[7] - 1] = y
    }


    val isSolved: Boolean
        get() {
            for (side in sides) {
                if (side.map { colors[it - 1] }.distinct().size != 1) return false
            }
            return true
        }

}


