    var best = lcm(a,b)
    var ans = 0L
    var sqrt = Math.sqrt(diff.toDouble()).toLong()
    for(i in 1..sqrt){
        if(diff%i==0L){
            var difI = diff / i
            var A = Math.ceil(a.toDouble()/difI).toLong() * difI
            var k = A - a
            var lcm = lcm(a+k, b+k)
            if(lcm < best){
                best = lcm
                ans = k
            }

            A = Math.ceil(a.toDouble()/i).toLong() * i
            k = A - a
            lcm = lcm(a+k, b+k)
            if(lcm < best){
                best = lcm
                ans = k
            }
        }
    }
    println(ans)
