fun findZeroSum2(aPos: List<Int>, bPos: List<Int>, maxCount: Int, n: Int): Int {
    val map = IntArray(2 * maxCount + 1) { -100 }
    map[maxCount] = -1

    val merged = merge(aPos, bPos, n)
    var sum = 0
    var bestAns = 0
    for (i in merged.indices) {
        val (value, index) = merged[i]
        sum += value
        val oppositeIndex = map[sum + maxCount]

