            val r = merged.getOrNull(i + 1)?.index ?: index
            val rDiff = if (r != index) 1 else 0
            bestAns = max(bestAns, (r - rDiff) - oppositeIndex)
        } else {
            map[sum + maxCount] = index
        }
    }

    return bestAns
