fun fibInv(n: Long): Int {
    if(n < 3) {
        return 1;
    }

    var i = 1;
    val fib = ArrayList<Long>(2)

    fib.add(1);
    fib.add(2);

    while(n >= fib[i]) {
        i++
        fib.add(fib[i - 1] + fib[i - 2]);
    }

    return i - 1;
}

