fun divisors(xx : Int) : List<Int> {
    var x = xx
    val res = mutableListOf<Int>()
    fun tryDiv(div : Int) {
        if (x % div == 0) {
            res.add(div)
            do {
                x /= div
            } while (x % div == 0)
        }
    }
    tryDiv(2)
    var div = 3
    while(div * div <= x) {
        tryDiv(div)
        div += 2
    }
    if (x != 1) {
        res.add(x)
    }
    return res
}

val mod = 1000000007L
fun fastExp(a : Long, b : Long) : Long {
    //(a ^ b) % mod
    var res = 1L
    var x   = a
    var e   = b
    while(e > 0) {
        if (e % 2L == 1L) {
            res *= x
            res %= mod
        }
        x *= x
        x %= mod
        e /= 2
    }
    return res
}

