fun pow(x: Long, n: Long): Long {
    var num = x
    var count = n
    var result = 1L
    while (count > 0) {
        if (count and 1L == 1L) {
            result = (result * num) % 1000000007
        }
        num = (num * num) % 1000000007
        count = count shr 1
    }
    return result
}

