val Bag<*>.numDistinct get() = countMap.size

interface Bag<T> : Collection<T> {
    val countMap: Map<T, Int>

    fun getCount(element: T): Int = countMap[element] ?: 0
    val elements: Set<T> get() = countMap.keys
    val entries: Set<Map.Entry<T, Int>> get() = countMap.entries

    override fun iterator(): Iterator<T> = sequence {
        for((e, cnt) in countMap) {
            repeat(cnt) { yield(e) }
        }
    }.iterator()

    override fun contains(element: T): Boolean = countMap.containsKey(element)
}

private fun Bag<*>._size() = countMap.values.sum()
private fun Bag<*>._equals(other: Any?) = when {
    this === other -> true
    other is Bag<*> -> countMap == other.countMap
    else -> false
}
private fun Bag<*>._hashCode() = countMap.hashCode()

class BagImpl<T>(override val countMap: Map<T, Int>): Bag<T>, AbstractCollection<T>() {
    override val size = _size()
    override fun equals(other: Any?) = _equals(other)
    override fun hashCode() = _hashCode()
    override fun contains(element: T) = super<Bag>.contains(element)
    override fun iterator() = super.iterator()
}
fun <T> Bag(countMap: Map<T, Int>): Bag<T> = BagImpl(countMap)

interface MutableBag<T> : Bag<T>, MutableCollection<T> {
    val _countMap: MutableMap<T, Int>
    var _size: Int

    override fun add(element: T): Boolean { add(element, 1); return true }
    fun add(element: T, occurrences: Int): Int {
        require(occurrences >= 0)
        val oldCount = getCount(element)
        _countMap[element] = oldCount + occurrences
        _size += occurrences
        return oldCount
    }

    override fun remove(element: T): Boolean = remove(element, 1) > 0
    fun remove(element: T, occurrences: Int): Int {
        require(occurrences >= 0)
        val oldCount = getCount(element)
        val m = minOf(occurrences, oldCount)
        when(oldCount) {
            0 -> return 0
            m -> _countMap.remove(element)
            else -> _countMap[element] = oldCount - m
        }
        _size -= m
        return oldCount
    }

    fun setCount(element: T, occurrences: Int): Int {
        require(occurrences >= 0)
        val oldCount = getCount(element)
        if(occurrences == 0) _countMap.remove(element)
        else _countMap[element] = occurrences
        _size += occurrences - oldCount
        return oldCount
    }

    override fun iterator(): MutableIterator<T> = object: MutableIterator<T> {
        private val mapIterator = _countMap.iterator()
        private var rem = 0
        private lateinit var lastEntry: MutableMap.MutableEntry<T, Int>
        private var removed = true
        override fun hasNext() = rem > 0 || mapIterator.hasNext()
        override fun next(): T {
            if(rem == 0) {
                lastEntry = mapIterator.next()
                rem = lastEntry.value
            }
            rem--
            removed = false
            return lastEntry.key
        }
        override fun remove() {
            if(removed) error("")
            lastEntry.setValue(lastEntry.value - 1)
            if(lastEntry.value == 0) mapIterator.remove()
            _size--
            removed = true
        }
    }
}

abstract class AbstractMutableBag<T>: MutableBag<T>, AbstractMutableCollection<T>() {
    final override val countMap: Map<T, Int> get() = _countMap
    final override val size get() = _size
    override fun equals(other: Any?) = _equals(other)
    override fun hashCode() = _hashCode()
    override fun contains(element: T) = super<MutableBag>.contains(element)
    override fun iterator() = super.iterator()
    override fun add(element: T): Boolean = super.add(element)
    override fun addAll(elements: Collection<T>): Boolean =
        if(elements is Bag<T>) {
            for((e, n) in elements.countMap) add(e, n)
            true
        } else super.addAll(elements)
    override fun remove(element: T): Boolean = super<MutableBag>.remove(element)
    override fun removeAll(elements: Collection<T>): Boolean =
        if(elements is Bag<T>) {
            var modified = false
            for((e, n) in elements.countMap) if(remove(e, n) > 0) modified = true
            modified
        } else super.removeAll(elements)
}

class HashBag<T>(override val _countMap: HashMap<T, Int>): AbstractMutableBag<T>() {
    constructor(): this(HashMap())

    override var _size = _size()
}

