        }
        for (j in st.indices) {
            if (canBeNext(st[i].i1, st[i].j1, st[j].i1, st[j].j1) &&
                canBeNext(st[i].i2, st[i].j2, st[j].i2, st[j].j2)
            ) {
                matrix[i][j] += 1L
            }
            if (st[j].i1 != st[j].i2 &&
                canBeNext(st[i].i1, st[i].j1, st[j].i2, st[j].j2) &&
                canBeNext(st[i].i2, st[i].j2, st[j].i1, st[j].j1)
            ) {
                matrix[i][j] += 1L
            }
        }
    }

    var add = Long.MAX_VALUE % MFFT + 1
    var add2 = (add + add) % MFFT


    var ans = LongArray(k)
    ans[start] = 1
    var nextMatrix = Array(k) { LongArray(k) }

    var iter = 0
    while (true) {
        if ((m and 1) == 1) {
            var nextAns = LongArray(matrix.size)
            for (i in 0 until k) {
                var cnt = 0
                for (j in 0 until k) {
                    var prod = ans[j] * matrix[j][i]
                    nextAns[i] += prod
                    if (nextAns[i] in 0 until prod) cnt++
                }
                if (nextAns[i] < 0L) {
                    nextAns[i] = -(Long.MIN_VALUE - nextAns[i]) + add
                }
                nextAns[i] = (nextAns[i] + cnt * add2) % MFFT

            }
            ans = nextAns
        }
        m /= 2
        if (m == 0) break
        for (i in 0 until k) {
            for (j in 0 until k) {
                if (iter > 8 && matrix[i][j] == 0L) continue
                var cnt = 0
                for (z in 0 until k) {
                    var prod = matrix[i][z] * matrix[z][j]
                    nextMatrix[i][j] += prod
                    if (nextMatrix[i][j] in 0 until prod) cnt++
                }
                if (nextMatrix[i][j] < 0L) {
                    nextMatrix[i][j] = -(Long.MIN_VALUE - nextMatrix[i][j]) + add
                }
                nextMatrix[i][j] = (nextMatrix[i][j] + cnt * add2) % MFFT
            }
        }
        for (i in 0 until k) {
            for (j in 0 until k) {
                matrix[i][j] = nextMatrix[i][j]
                nextMatrix[i][j] = 0
            }
        }
        iter++
    }
    var sm = 0L
    for (i in st.indices) {
        if (st[i].j1 + 1 == a[st[i].i1].length && st[i].j2 + 1 == a[st[i].i2].length) {
            sm += ans[i]
        }
    }
    println(sm % MFFT)

}

