val MOD = 998244353

fun mul(a: Array<IntArray>, b: Array<IntArray>): Array<IntArray> {
    val n = a.size
    val res = Array<IntArray>(n) { IntArray(n) { 0 } }

    for (i in 0 until n) {
        for (j in 0 until n) {
            for (k in 0 until n) {
                res[i][j] += ((a[i][k].toLong() * b[k][j].toLong()) % MOD).toInt()
                if (res[i][j] >= MOD) {
                    res[i][j]-=MOD
                }
            }
        }
    }

    return res
}

fun pow(a: Array<IntArray>, k: Int): Array<IntArray> {
    if (k == 1) {
        return a
    }

    var res = pow(a, k / 2)
    res = mul(res, res)
    if (k % 2 == 1) {
        res = mul(res, a)
    }
    return res
}


fun solve(src: List<String>, m: Int): Int {
    val kids = mutableListOf(IntArray(26) { -1 })
    val word = mutableListOf<String>("")
    val end = mutableListOf<Boolean>(true)

    for (w in src) {
        var u = 0
        var t = ""
        for (_c in w) {
            t += _c
            val c = _c - 'a'
            if (kids[u][c] == -1) {
                kids[u][c] = kids.size
                kids.add(IntArray(26) { -1 })
                word.add("")
                end.add(false)
            }
            u = kids[u][c]
            word[u] = t
        }
        end[u] = true
    }

    val stateId = mutableMapOf<Pair<Int, Int>, Int>()
    val nodesByState = mutableListOf<Pair<Int, Int>>()

    for (i in kids.indices) {
        for (j in kids.indices) {
            if ((word[i]!!.endsWith(word[j]!!)
                        || word[j]!!.endsWith(word[i]!!))
                && (j >= i)
            ) {
                stateId[i to j] = stateId.size
                nodesByState.add(i to j)
            }
        }
    }

    val matr = Array(nodesByState.size) { IntArray(nodesByState.size) }

    fun getState(u: Int, v: Int): Int {
        val t =stateId[minOf(u, v) to maxOf(u, v)]
        return t!!
    }

    for ((state, p) in nodesByState.withIndex()) {
        val (u, v) = p

        for (c in 0 until 26) {
            if (kids[u][c] == -1 || kids[v][c] == -1) {
                continue
            }

            val newU = kids[u][c]
            val newV = kids[v][c]

            val newState = getState(newU, newV)

            matr[state][newState]++

            if (end[newU]) {
                val st = getState(0, newV)
                matr[state][st]++
            }

            if (end[newV]) {
                val st = getState(0, newU)
                matr[state][st]++
            }

            if (end[newU] && end[newV]) {
                matr[state][0]++
            }
        }
    }

    val p = pow(matr, m)

    return p[0][0].toInt()
}

