fun Long.divisors() = sequence {
    val n = this@divisors
    if(n <= 0) return@sequence
    val tail = mutableListOf<Long>()

    for(p in 1..Long.MAX_VALUE) {
        val sq = p * p
        if(sq > n) break
        if(n % p == 0L) {
            yield(p)
            if(sq != n) tail.add(n / p)
        }
    }

    yieldAll(tail.asReversed())
}

