fun testBipartite(N: Int, g: Array<BooleanArray>, D: IntArray): Boolean {
  for (u in 0 until N) {
    for (v in 0 until N) {
      if (!g[u][v]) continue
      if (D[v] % 2 == D[u] % 2) {
        return false
      }
    }
  }

  return true
}
/**
 * (dist, parent, queue)
 * @param rt ルートノードを指定する。nullの場合は全ノード辿るまで繰り返す
 */
fun traceBfs(g: Array<BooleanArray>): Array<IntArray>? {
  val n = g.size
  val q = IntArray(n)
  val d = IntArray(n)
  val p = IntArray(n){-2}
  var h = 0
  var t = 0

  fun bfs(rt: Int) {
    p[rt] = -1
    q[t++] = rt
    d[rt] = 0
    while (h < t) {
      val u = q[h++]
      for (v in 0 until n) {
        if (!g[u][v]) continue
        if (p[v] == -2) {
          p[v] = u
          q[t++] = v
          d[v] = d[u] + 1
        }
      }
    }
  }

  var traced = false
  for (u in 0 until n) {
    if (g[u].all{!it}) continue
    if (p[u] != -2) continue
    if (traced) return null
    bfs(u)
    traced = true
  }
  return arrayOf(d, p, q)
}
fun packUGraph(n: Int, from: IntArray, to: IntArray): Array<IntArray> {
  val p = IntArray(n)
  val m = from.size
  for (i in 0 until m) {
    ++p[from[i]]
    ++p[to[i]]
  }
  val g = Array(n){IntArray(p[it])}
  for (i in 0 until m) {
    g[from[i]][--p[from[i]]] = to[i]
    g[to[i]][--p[to[i]]] = from[i]
  }
  return g
}
