fun List<Int>.linearSearch(start: Int = 0, end: Int = size - 1): IntPair {
    var max = Int.MIN_VALUE
    var maxI = 0
    for (i in start..end) {
        if (this[i] > max) {
            max = this[i]
            maxI = i
        }
    }

    return maxI to max
}

