fun List<Int>.binarySearchFirst(key: Int, start: Int = 0, end: Int = size - 1): Int {
    var mid = (start + end) / 2
    var l = start
    var r = end
    while (l <= r) {
        mid = (r + l) / 2
        if (this[mid] == key && (mid == start || this[mid - 1] < key)) {
            return mid
        } else if (this[mid] >= key) {
            r = mid - 1
        } else {
            l = mid + 1
        }
    }

    return if(this[mid] == key) mid else 0 - mid - 1
}

fun List<Int>.binarySearchLast(key: Int, start: Int = 0, end: Int = size - 1): Int {
    var mid = (start + end) / 2
    var l = start
    var r = end
    while (l <= r) {
        mid = (r + l) / 2
        if (this[mid] == key && (mid == end || this[mid + 1] > key)) {
            return mid
        } else if(this[mid] == key && this[mid + 1] == key) {
            l = mid + 1
        } else if (this[mid] > key) {
            r = mid - 1
        } else {
            l = mid + 1
        }
    }

    return if(this[mid] == key) mid else 0 - mid - 1
}

