fun sieve(bound: Int): List<Int> {
    val result = ArrayList<Int>()
    for (i in 2..bound) {
        result.add(i)
    }
    for (i in 2..bound) {
        for (j in i + i..bound step i) {
            result[j - 2] = -1
        }
    }
    return result
}

