fun binarySearch(list: List<Int>, value: Int): Int {
    var l = -1
    var r = list.size
    while (r - l > 1) {
        val m = (l + r) ushr 1
        if (list[m] < value) l = m
        else r = m
    }
    return r
}

fun nextGreaterElement(list: List<Long>): List<Int> {

    if (list.isEmpty()) return emptyList()
    val stack = Stack<Pair<Long, Int>>()
    stack.push(Pair(list.first(), 0))
    val result = MutableList(list.size) { list.size }
    for (i in 1 until list.size) {
        var prev = stack.peek()
        val cur = list[i]
        while (prev.first < cur && stack.isNotEmpty()) {
            result[prev.second] = i
            stack.pop()
            if (stack.isNotEmpty()) prev = stack.peek()
        }
        stack.push(Pair(cur, i))
    }
    return result
}

typealias Number = Long

fun segmentTreeFunction(a: Number, b: Number): Number = max(a, b)

fun buildSegmentTree(elements: List<Number>): SegmentTreeNode {
    val leafs = elements.mapIndexed { ind, it ->
        SegmentTreeNode(it, null, ind, ind)
    }
    var curLevel = leafs
    while (curLevel.size > 1) {
        val nextLevel = mutableListOf<SegmentTreeNode>()
        for (i in curLevel.indices step 2) {
            val node = if (i + 1 < curLevel.size) {
                SegmentTreeNode(
                    segmentTreeFunction(curLevel[i].element, curLevel[i + 1].element),
                    listOf(curLevel[i], curLevel[i + 1]),
                    curLevel[i].start,
                    curLevel[i + 1].finish
                )
            } else {
                SegmentTreeNode(
                    curLevel[i].element,
                    listOf(curLevel[i]),
                    curLevel[i].start,
                    curLevel[i].finish
                )
            }
            nextLevel.add(node)
        }
        curLevel = nextLevel
    }
    return curLevel.first()
}

class SegmentTreeNode
    (
    val element: Number,
    val children: List<SegmentTreeNode>? = null,
    val start: Int,
    val finish: Int
) {
    fun query(l: Int, r: Int): Number {
        if (l == start && r == finish) {
            return element
        }
        val left = children!!.first()
        if (r <= left.finish) {
            return left.query(l, r)
        }
        val right = children[1]
        if (l >= right.start) {
            return right.query(l, r)
        }
        return segmentTreeFunction(left.query(l, left.finish), right.query(right.start, r))
    }
}

fun prefSums(base: Iterable<Long>): List<Long> {
    val prefSums = base.toMutableList()
    for (i in 1 until prefSums.size) {
        prefSums[i] += prefSums[i - 1]
    }
    return prefSums
}


fun gcd(a: Long, b: Long): Long {
    if (a == 0L) return b
    return gcd(b % a, a)
}

/**
 * least common multiply
 */
fun lcm(a: Long, b: Long): Long {
    return abs(a.toLong() * b.toLong()) / gcd(a, b).toLong()
}

val primes by lazy { generatePrimes(2 * 1000_000).toSet() }


fun factorize(x: Int): MutableMap<Int, Int> {
    val mp = mutableMapOf<Int, Int>()
    var xx = x

    for (prime in primes) {
        var count = 0
        while (xx % prime == 0) {
            xx /= prime
            count++
        }
        if (count > 0) {
            mp[prime] = count
        }
        if (primes.contains(xx)) {
            mp[xx] = 1
            break
        }
    }
    return mp

}


fun generatePrimes(n: Int): List<Int> {
    val prime = Array(n + 1) { true }
    var p = 2
    while (p * p <= n) {
        if (prime[p]) {
            var i = p * p
            while (i <= n) {
                prime[i] = false
                i += p
            }
        }
        p++
    }
    return (2..n).filter { prime[it] }
}

