private fun getInput() : Array<Int>
{
    val input = Array(scan.nextInt()) {it}
    scan.nextLine()
    for (i in input.indices)
    {
        input[i] = scan.nextInt()
    }
    return input
}

private fun calc(input: Array<Int>) : Array<Int>
{
    val result = Array(input.size) {it}
    for (i in input.indices)
    {
        val caseValue = input[i]
        val caseValueSqrt = sqrt(caseValue.toDouble())
        val caseValueCbrt = Math.cbrt(caseValue.toDouble())
        val caseValueCbrtCbrt = sqrt(caseValueCbrt)
        result[i] = caseValueSqrt.toInt() + caseValueCbrt.toInt() - caseValueCbrtCbrt.toInt()
    }
    return result
}

