class Combination(private val maxN: Int, private val mod: Int) {
    private val fac = LongArray(maxN+1) { 1 }
    private val inv = LongArray(maxN+1) { 1 }

    init {
        for (i in 2..maxN) fac[i] = fac[i-1] * i % mod
        var m = mod - 2
        var x = fac.last()
        while (m > 0) {
            if (m.and(1) == 1) inv[maxN] = inv[maxN] * x % mod
            x = x * x % mod
            m = m.shr(1)
        }
        for (i in maxN downTo 2) inv[i-1] = inv[i] * i % mod
    }

    fun ncr(n: Int, r: Int): Long = ((fac[n] * inv[r]) % mod) * inv[n-r] % mod
    fun npr(n: Int, r: Int): Long = fac[n] * inv[n-r] % mod
}

fun main(args: Array<String>) {
    val (n, m) = readInts()
    if (n == 1) {
        println(0)
        return
    }
    val mod = 998244353
    val comb = Combination(m, mod)
    var ans = comb.ncr(m, n-1) * (n-2) % mod
    for (i in 0 until n-3) ans = ans * 2 % mod

    println(ans)
}

const val MOD = 998244353L

val fact = ArrayList<Long>()
fun main(args: Array<String>) {
    val (n, m) = getLongs()
    if (n == 2L) {
        println(0)
        return
    }

    fact.add(1L)
    (1..m).forEach {
        fact.add(fact.last() * it % MOD)
    }

    var out = comb(m, n - 1)
    out = out * (n - 2) % MOD

    var c = 0L
    (0..n - 3).forEach {
        c = (c + comb(n - 3, it)) % MOD
    }
    out = out * c % MOD
    println(out)
}

fun comb(n: Long, k: Long): Long {
    return (fact[n.toInt()] * inv(fact[k.toInt()]) % MOD) * inv(fact[n.toInt() - k.toInt()]) % MOD
}

fun inv(n: Long): Long {
    return pow(n, MOD - 2)
}

fun pow(base: Long, exp: Long): Long {
    return when {
        exp == 0L -> 1L
        exp == 1L -> base
        exp % 2 == 0L -> pow(base, exp / 2).let { it * it % MOD }
        else -> pow(base, exp / 2).let { (base * it % MOD) * it % MOD }
    }
}


