class ModFFT(minCapacity: Int) {
    val n = Integer.highestOneBit(minCapacity.shl(1) - 1)
    inline val g get() = ModInt(3) // primitive root modulo 998244353
    val ninv = ModInt(n).inverse()
    val mask = n - 1

    val w = ModIntArray(n).also { w ->
        w[0] = ModInt(1)
        val w1 = g.pow((MOD-1) / n)
        for(i in 1 until n) {
            w[i] = w[i-1] * w1
        }
    }

    // rev[i] is reversal of bits in i
    val rev = IntArray(n).also { rev ->
        if(n == 1) return@also
        rev[1] = n shr 1
        var bit = 2
        while(bit < n) {
            val revbit = rev[bit shr 1] shr 1
            for(i in bit until bit.shl(1)) {
                rev[i] = revbit or rev[i - bit]
            }
            bit = bit shl 1
        }
    }

    operator fun invoke(a: ModIntArray, invert: Boolean): ModIntArray {
        val res = a.copyOf(n)
        inPlace(res, invert)
        return res
    }

    // in-place FFT. Precondition: a.size == n
    fun inPlace(a: ModIntArray, invert: Boolean) {
        require(a.size == n) { "size of a must be n = $n" }
        for(i in 0 until n) {
            val j = rev[i]
            if(i < j) a[i] = a[j].also { a[j] = a[i] }
        }

        var len = 2
        var ang = n shr 1 // = n / len
        if(invert) ang = -ang
        while(len <= n) {
            for(i in 0 until n step len) {
                var k = 0
                for(j in 0 until len.shr(1)) {
                    val u = a[i+j]
                    val v = a[i+j+len.shr(1)] * w[k]
                    a[i+j] = u + v
                    a[i+j+len.shr(1)] = u - v
                    k = k + ang and mask
                }
            }

            len = len shl 1
            ang = ang shr 1
        }

        if(invert) {
            for(i in 0 until n) a[i] *= ninv
        }
    }

    fun mul(a: ModIntArray, b: ModIntArray): ModIntArray {
        require(a.size + b.size <= n)
        val a1 = invoke(a, false)
        val b1 = invoke(b, false)
        for(i in 0 until n) a1[i] *= b1[i]
        inPlace(a1, true)
        return a1.copyOf(a.size + b.size)
    }
}

const val MOD = 998244353
const val TOTIENT = MOD - 1 // assumes MOD is prime

infix fun Int.umod(mod: Int): Int = (this % mod).let { (it shr Int.SIZE_BITS - 1 and mod) + it }
infix fun Long.umod(mod: Long) = (this % mod).let { (it shr Long.SIZE_BITS - 1 and mod) + it }
infix fun Long.umod(mod: Int) = umod(mod.toLong()).toInt()

fun Int.mulMod(other: Int, mod: Int) = toLong() * other umod mod

fun Int.powMod(exponent: Int, mod: Int): Int {
    if(exponent < 0) error("Inverse not implemented")
    var res = 1L
    var e = exponent
    var b = umod(mod).toLong()

    while(e > 0) {
        if(e and 1 == 1) {
            res = res * b % mod
        }
        e = e shr 1
        b = b * b % mod
    }
    return res.toInt()
}

inline fun Int.toModInt() = ModInt(this umod MOD)
