class ModFFT(deg: Int) {
    inline val g get() = ModInt(3) // primitive root modulo 998244353
    val n = Integer.highestOneBit(deg shl 1 or 1)
    private val ninv = ModInt(n).inverse()

    // w[1] represents n-th root of unity e^(i * tau/n), w[k] = w[1]^k
    val w = ModIntArray(n).also { w ->
        w[0] = ModInt(1)
        val w1 = g.pow(TOTIENT / n)
        for(i in 1 until n) {
            w[i] = w[i-1] * w1
        }
    }

    // rev[i] is reversal of bits in i
    private val rev = IntArray(n).also { rev ->
        var bit = 1
        var rbit = n shr 1
        while(bit < n) {
            for(i in 0 until bit) {
                rev[i or bit] = rbit or rev[i]
            }
            bit = bit shl 1
            rbit = rbit shr 1
        }
    }

    operator fun invoke(a: ModIntArray, invert: Boolean): ModIntArray {
        val res = a.copyOf(n)
        inPlace(res, invert)
        return res
    }

    // in-place FFT. Precondition: a.size == n
    fun inPlace(a: ModIntArray, invert: Boolean) {
        require(a.size == n) { "size of a must be n = $n" }
        for(i in 0 until n) {
            val j = rev[i]
            if(i < j) a[i] = a[j].also { a[j] = a[i] }
        }

        var len = 2
        var ang = n shr 1 // = n / len, representing the angle tau / len
        if(invert) ang = -ang
        while(len <= n) {
            for(i in 0 until n step len) {
                var k = 0
                for(j in 0 until len.shr(1)) {
                    val u = a[i+j]
                    val v = a[i+j+len.shr(1)] * w[k]
                    a[i+j] = u + v
                    a[i+j+len.shr(1)] = u - v
                    k = k + ang and n-1
                }
            }

            len = len shl 1
            ang = ang shr 1
        }

        if(invert) {
            for(i in 0 until n) a[i] *= ninv
        }
    }

    fun mul(a: ModIntArray, b: ModIntArray): ModIntArray {
        require(a.size + b.size - 1 <= n)
        val a1 = invoke(a, false)
        val b1 = invoke(b, false)
        for(i in 0 until n) a1[i] *= b1[i]
        inPlace(a1, true)
        return a1//.copyOf(a.size + b.size - 1)
    }
}

