val perm = intArrayOf(0, 1, 2, 3, 4, 5)
fun nextPerm(): Boolean {
    var hasNext = false
    for (i in perm.size - 2 downTo 0) {
        if (perm[i] > perm[i + 1]) continue
        hasNext = true

        for (j in perm.lastIndex downTo i + 1) {
            if (perm[j] > perm[i]) {
                swap(i, j)
                break
            }
        }
        var l = i + 1;
        var r = perm.lastIndex
        while (l < r) {
            swap(l++, r--)
        }
        break
    }

    return hasNext
}

private fun swap(i: Int, j: Int) {
    val tmp = perm[i]
    perm[i] = perm[j]
    perm[j] = tmp
}

