    var bob = readInts()

    var orders = Array(6){IntArray(3)}
    var ptr = 0
    for(i in 0 until 3) {
        for(j in 0 until 3) {
            for(k in 0 until 3) {
               if(i == j || i == k || j == k) continue
                orders[ptr][0] = i; orders[ptr][1] = j; orders[ptr][2] = k;
                ptr++
            }
        }
    }

    //0 = rock, 1 = scissors, 2 = paper
    fun isWin(a: Int, b: Int): Boolean {
        if(a == 0) return b == 1
        if(a == 1) return b == 2
        if(a == 2) return b == 0
        return false
    }

    fun eval(order: IntArray, order1: IntArray): Int {
        var A = alice.toMutableList()
        var B = bob.toMutableList()

        var wins = 0
        var bobPtr = 0
        var aliPtr = 0
        while(aliPtr < 3 && bobPtr < 3) {
            var amtMe = A[order1[aliPtr]]
            var amtHim = B[order[bobPtr]]
            var plays = min(amtMe, amtHim)
            if(isWin(order1[aliPtr], order[bobPtr])) {
                wins += plays
            }

            A[order1[aliPtr]] -= plays
            B[order[bobPtr]] -= plays

            if(B[order[bobPtr]] == 0) bobPtr++
            if(A[order1[aliPtr]] == 0) aliPtr++
        }

        return wins
    }

    var minWin = n+1
    var maxWin = 0

    for(i in 0 until 6) {
        for(j in 0 until 6) {
            var ret = eval(orders[i], orders[j])
            minWin = min(minWin, ret)
            maxWin = max(maxWin, ret)
        }
    }

