class FF(val n: Int) {

	var adj = Array(n){ LongArray(n) }
	var seen = BooleanArray(n)

	fun add(u: Int, v: Int, cap: Long) {
		adj[u][v] += cap
	}

	fun dfs(u: Int, low: Long, t: Int): Long {
		if (u == t)
			return low

		seen[u] = true;

		for (v in 0..n-1) {
			if (adj[u][v] != 0L && !seen[v]) {
				var flow = dfs(v, min(adj[u][v], low), t)

				if (flow > 0) {
					adj[u][v] -= flow
					adj[v][u] += flow
					seen[u] = false
					return flow
				}
			}
		}

		seen[u] = false
		return 0
	}

	fun flow(s: Int, t: Int): Long {
		var flow = 0L

		while (true) {
			var here = dfs(s, 100000000000, t)
			if (here == 0L)
				break
			flow += here
		}

		return flow
	}
}

