fun nextPermutation(array: MutableList<Int>): Boolean {
    var tmp: Int
    for (i in array.size - 2 downTo 0) {
        if (array[i] < array[i + 1]) {
            for (j in array.size - 1 downTo i + 1) {
                if (array[j] > array[i]) {
                    tmp = array[i]
                    array[i] = array[j]
                    array[j] = tmp

                    val tmpArray = array.takeLast(array.size - (i + 1)).sorted()
                    tmpArray.forEachIndexed { index, e ->
                        array[i + 1 + index] = e
                    }

                    return true
                }
            }
        }
    }
    return false
}

fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val a = Array(3) { sc.nextInt() }
    val b = Array(3) { sc.nextInt() }
    var ans1 = Int.MAX_VALUE
    val ord = arrayOf(0 to 0, 0 to 2, 1 to 1, 1 to 0, 2 to 2, 2 to 1)
    var p = (0 until 6).toMutableList()
    do {
        val a1 = a.copyOf()
        val b1 = b.copyOf()
        for (i in 0 until 6) {
            val j = ord[p[i]]
            val cnt = minOf(a1[j.first], b1[j.second])
            a1[j.first] -= cnt
            b1[j.second] -= cnt
        }
        val cur = minOf(a1[0], b1[1]) + minOf(a1[1], b1[2]) + minOf(a1[2], b1[0])
        ans1 = minOf(ans1, cur)
    } while (nextPermutation(p))
    val ans2 = minOf(a[0], b[1]) + minOf(a[1], b[2]) + minOf(a[2], b[0])
    println("$ans1 $ans2")
}

