fun nextString(): String? {
    var c = skipWhitespace()
    if (c < 0) return null

    return sb.run {
        setLength(0)

        do {
            append(c.toChar())
            c = read()
        } while (c > ' '.toInt())

        toString()
    }
}

fun nextLine(): String? {
    var c = read()
    if (c < 0) return null

    return sb.run {
        setLength(0)

        while (c >= 0 && c != '\n'.toInt()) {
            append(c.toChar())
            c = read()
        }

        toString()
    }
}

fun nextLong(): Long {
    var c = skipWhitespace()

    val sign = if (c == '-'.toInt()) {
        c = read()
        -1
    } else 1

    var ans = 0L

    while (c > ' '.toInt()) {
        ans = ans * 10 + c - '0'.toInt()
        c = read()
    }

    return sign * ans
}

fun nextInt() = nextLong().toInt()
fun nextDouble() = nextString()?.toDouble() ?: 0.0
fun nextBigInteger(): BigInteger = nextString()?.toBigInteger() ?: BigInteger.ZERO
fun nextBigDecimal(): BigDecimal = nextString()?.toBigDecimal() ?: BigDecimal.ZERO

fun nextStrings(n: Int) = Array<String>(n) { nextString() ?: "" }
