val MOD = 1_000_000_007
fun powMod(a: Long, n: Long, mod: Int): Long {
  if (n == 0L) return 1
  val res = powMod(a * a % mod, n / 2, mod)
  return if (n % 2 == 1L) res * a % mod else res
}
class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  private val reader = BufferedReader(InputStreamReader(stream), 32768)

  fun solve() {
    val S = ns()
    val Ss = (0 until 10).map { S.replace('X', '0'+it) }.distinct()
    val ans = Ss.map(::solve2).sum()
    out.println(ans)
  }

  fun solve2(S: String): Int {
    debug{"solve2($S)"}
    val N = S.length
    if (N < 3) {
      return solve_naive(S)
    }

    val head = S.take(max(0, N - 2)) // 0かもしれない
    val fst = head.take(1)
    val snd = head.drop(1)
    val tail = S.drop(head.length)

    fun countTail(): Int {
      var cnt = 0
      for (num in 0 until 100) {
        if (num % 25 == 0 && accepts(tail, num) != null) cnt++
      }
      return cnt
    }

    fun countHead(): Int {
      if (fst.isEmpty()) return 1

      val c1 = when(fst[0]) {
        '_' -> 9
        '0' -> 0
        else -> 1
      }
      val underscores = snd.count { it == '_' }
      val c2 = powMod(10, underscores.toLong(), MOD).toInt()
      return c1 * c2
    }

    debug{"countTail: ${countTail()} countHead${countHead()}"}
    return countTail() * countHead()
  }

  fun solve_naive(S: String): Int {
    val N = S.length
    val max = powMod(10, N.toLong(), MOD).toInt()
    var cnt = 0
    for (num in 0 until max) {
      if (num % 25 != 0) continue
      val res = accepts(S, num) ?: continue
      if (res.length == 1 || res[0] != '0') cnt++
    }
    return cnt
  }

  fun accepts(S: String, num: Int): String? {
    val numStr = ("00$num").takeLast(S.length)
    val ok = numStr.indices.all { S[it] == '_' || S[it] == numStr[it] }
    return if (ok) numStr else null
  }













































