fun exp10(x: Long): Long {
    if (x == 0L) {
        return 1
    } else {
        return 10 * exp10(x - 1)
    }
}

fun kthDigit(k: Long): Char {
    val lev_lst: MutableList<Long> = mutableListOf(0L)
    for (lev in 1L..12L) {
        val step = exp10(lev - 1) * 9 * lev
        val nxt = step + lev_lst.last()
        lev_lst.add(nxt)
    }
    val arr = LongArray(lev_lst.size) { lev_lst[it] }

    fun binLevSearch(): Int {
        var lo = 0
        var hi = arr.lastIndex
        while (hi - lo > 1) {
            val m = (hi + lo) / 2
            //println("m=$m")
            if (k > arr[m])
                lo = m
            else
                hi = m
        }

        return hi
    }

    val bound_idx = binLevSearch()
    val wid = bound_idx
    val base = arr[bound_idx - 1]
    val delta = k - base - 1
    val cnt = delta / wid
    val offs: Int = (delta % wid).toInt()
    val from = exp10(wid - 1L)
    val num = from + cnt
    val numstr = num.toString()
    val dgt: Char = numstr[offs]

    return dgt
}

