fun solve(input: BufferedReader, out: BufferedWriter) {
    val s = input.readLine()
    var result: String? = null
    for (match in Regex("at").findAll(s, 1)) {
        val r = match.groups[0]!!.range
        if (r.endInclusive + 1 < s.length) {
            val s1 = s.substring(1, r.start)
            val s2 = s.substring(r.endInclusive + 1, s.length - 1)
            val t = s.first() + s1.replace("dot", ".") + "@" + s2.replace("dot", ".") + s.last()
            result = result?.let { listOf(it, t).minBy {x -> x.length } } ?: t
        }
    }
    println(result)
}

