class C {
    fun solve() {
        val st = StringTokenizer(readLine())

        val a: IntArray = IntArray(3)
        val needs: IntArray = intArrayOf(0, 1, 2, 0, 2, 1, 0)

        a[0] = st.nextToken().toInt()
        a[1] = st.nextToken().toInt()
        a[2] = st.nextToken().toInt()

        val weeks = min(a[0] / 3, min(a[1] / 2, a[2] / 2))
        var ans = weeks * 7

        a[0] -= (weeks * 3)
        a[1] -= (weeks * 2)
        a[2] -= (weeks * 2)

        var maxDays = 0
        for (weekDay in 0..6) {
            var days = 0
            val b: IntArray = a.copyOf()
            var cur = weekDay
            while (b[needs[cur]] != 0) {
                b[needs[cur]] --
                days ++
                cur ++
                cur %= 7
            }

            cur = (weekDay + 6) % 7
            while (b[needs[cur]] != 0) {
                b[needs[cur]] --
                days ++
                cur = (cur + 6) % 7
            }

            maxDays = max(days, maxDays)
        }

        ans += maxDays
        println(ans)
    }
