fun DecryptWord(WORD: String): String {
    val ChrArr = CharArray(WORD.length)
    var middle = if(WORD.length%2 ==0) WORD.length/2 -1 else WORD.length/2
    var counter = 0

    for(i in WORD.indices) {
        if(i%2 == 0) {
            var getChar = WORD.get(middle - counter)
            ChrArr[i] = getChar
            counter++
        } else {
            var getChar = WORD.get(middle + counter)
            ChrArr[i] = getChar
        }
    }
    var newString: String = String(ChrArr)
    return newString
}

