inline class ModInt(val int: Int) {
    companion object {
        /** can't seem to make these private or inlined without causing compiler issues */
        val _invMemo = HashMap<ModInt, ModInt>()
        fun _invMemoized(m: ModInt) = _invMemo.getOrPut(m) { m.inv_unmemoized() }
    }

    inline operator fun plus(other: ModInt) = plus(other.int) // MODBASE < 2^30
    inline operator fun plus(other: Int) =  (int + other).toModInt() // careful of possible overflow
    inline operator fun inc() = plus(1)

    inline operator fun minus(other: ModInt) = minus(other.int)
    inline operator fun minus(other: Int) = (int - other).toModInt()
    inline operator fun dec() = minus(1)
    operator fun unaryMinus() = if(int == 0) this else ModInt(MODBASE - int)

    inline operator fun times(other: ModInt) = times(other.int)
    inline operator fun times(other: Int) = ModInt(int.mulMod(other, MODBASE))

    fun pow(exponent: Int): ModInt {
        val e = if(exponent < 0) exponent umod MODBASE - 1 else exponent // assumes MODBASE is prime
        return ModInt(int.powMod(e, MODBASE))
    }

    inline fun inv() = inv_memoized() /** NOTE: Change if necessary */

    fun inv_unmemoized(): ModInt {
        require(int != 0) { "Can't invert/divide by 0" }
        return pow(MODBASE - 2) // assumes MODBASE is prime
    }
    fun inv_memoized() = _invMemoized(this)

    operator fun div(other: ModInt) = times(other.inv())
    inline operator fun div(other: Int) = div(other.toModInt())

    override fun toString() = int.toString()
}

