data class Matrix2(val p: ModInt, val q: ModInt,
                   val r: ModInt, val s: ModInt) {
    operator fun times(b: Matrix2) =
        Matrix2(
            p = p * b.p + q * b.r, q = p * b.q + q * b.s,
            r = r * b.p + s * b.r, s = r * b.q + s * b.s
        )

    fun pow(exponent: Long): Matrix2 {
        var res = I
        var e = exponent
        var b = this

        while(e > 0) {
            if(e and 1 == 1L) {
                res *= b
            }
            e = e shr 1
            b *= b
        }
        return res
    }

    companion object {
        val I = Matrix2(
            ModInt(1), ModInt(0),
            ModInt(0), ModInt(1)
        )
    }
}

class ArrayModCombinatorics(val maxn: Int) {
    val factorial = ModIntArray(maxn + 1).also {
        it[0] = ModInt(1)
        for(i in 1 .. maxn) {
            it[i] = it[i-1] * i
        }
    }

    val invf = ModIntArray(maxn + 1).also {
        it[maxn] = factorial[maxn].inv_unmemoized()
        for(i in maxn downTo 1) {
            it[i-1] = it[i] * i
        }
    }

    fun P(n: Int, k: Int) = if(k > n || k < 0) ModInt(0) else factorial[n] * invf[n-k]
    fun C(n: Int, k: Int) = if(k > n || k < 0) ModInt(0) else factorial[n] * invf[k] * invf[n-k]

    // multi-choose, be sure to adjust maxn accordingly
    fun M(n: Int, k: Int) = if(k == 0) ModInt(1) else C(n + k - 1, k)
}

const val BILLION7 = 1e9.toInt() + 7
const val MOD = BILLION7
