fun FastReader.mainFn(out: StringBuilder) {
  repeat(nextInt()) {
    val (n, k) = nextInts(2)
    with(Mod(Mod.M109)) {
      val p = 2 powermod (n - 1)
      val q = p mulmod 2

      val modMatrixSpace =
        MatrixSpace.of(addModMonoid, mulModMonoid) {dim -> intArrayMatrix(dim, 0)}
      val mulMatrixMonoid = with(modMatrixSpace)
        { Monoid.of(identity(n=2), {x, y -> x matrixmul y}) }

      if (n and 1 == 0) {
        val m = buildIntArrayMatrix(2 to 2) {
          r(q, 1)
          r(0, p submod 1)
        }
        val mp = with(mulMatrixMonoid) { m fastpower k.toLong() }
        val ans = with(modMatrixSpace) {intArrayMatrix(1 to 2, 1) matrixmul mp}
        out.appendLine(ans[0, 1])
      } else {
        out.appendLine((p addmod 1) powermod k)
      }
    }
  }
}

