object FastReader {
  val reader = System.`in`.bufferedReader()
  var tokenizer: StringTokenizer? = null

  fun next(): String =
    tokenizer?.takeIf{it.hasMoreElements()}?.run {nextToken()}
      ?: run {
        tokenizer = StringTokenizer(reader.readLine())
        next()
      }

  fun nextInt(): Int = next().toInt()
  fun nextInts(n: Int): List<Int> = (1..n).map{nextInt()}
  fun nextIntArray(n: Int): IntArray = IntArray(n) {nextInt()}

  fun nextLong(): Long = next().toLong()
  fun nextLongs(n: Int): List<Long> = (1..n).map{nextLong()}
  fun nextLongArray(n: Int): LongArray = LongArray(n) {nextLong()}

  fun nextLine(): String {
    tokenizer = null
    return reader.readLine()
  }
}
