// {{{ Mod

class Mod(val mod: Int) {
  companion object {
    const val M109 = 1_000_000_007
    const val M99 = 998244353
  }

  val addModMonoid: Monoid<Int> = Monoid.of(0) {x, y -> x addmod y}
  val mulModMonoid: Monoid<Int> = Monoid.of(1) {x, y -> x mulmod y}

  fun Int.toMod() = this % mod
  infix fun Int.addmod(other: Int): Int {
    val x = this + other
    return if (x >= mod) x - mod else x
  }
  infix fun Int.submod(other: Int): Int {
    val x = this - other
    return if (x < 0) x + mod else x
  }
  infix fun Int.mulmod(other: Int): Int =
    (toLong() * other.toLong() % mod.toLong()).toInt()
  infix fun Int.powermod(n: Int): Int {
    var res = 1
    var t = this
    var nn = n

    while (nn > 0) {
      if (nn and 1 > 0) {
        res = res mulmod t
      }
      t = t mulmod t
      nn = nn shr 1
    }
    return res
  }
  fun Int.invmod(): Int = this powermod (mod-2)
}

