// {{{ Monoid

interface Semigroup<T> {
  infix fun T.stimes(other: T): T
}

abstract class Monoid<T>(val unit: T): Semigroup<T> {
  companion object {
    fun <T> of(unit: T, stimesFn: (T, T) -> T): Monoid<T> = object: Monoid<T>(unit) {
      override infix fun T.stimes(other: T): T = stimesFn(this, other)
    }
  }

  infix fun T.fastpower(n: Long): T {
    require(n >= 0)
    var res = unit
    var p = this
    var np = n
    while (np > 0) {
      if (np and 1 > 0) {
        res = res stimes p
      }
      p = p stimes p
      np = np shr 1
    }
    return res
  }
}

