typealias MatDim = Pair<Int, Int>

abstract class Matrix<E>(val numRows: Int, val numColumns: Int) {
  val dimension: MatDim
    get() = numRows to numColumns
  abstract operator fun get(i: Int, j: Int): E
  abstract operator fun set(i: Int, j: Int, value: E)
}

fun intArrayMatrix(dimension: MatDim, initialValue: Int): Matrix<Int> {
  val (numRows, numColumns) = dimension
  val mat = Array(numRows) {IntArray(numColumns){initialValue}}
  return object : Matrix<Int>(numRows, numColumns) {
    override operator fun get(i: Int, j: Int): Int = mat[i][j]
    override operator fun set(i: Int, j: Int, value: Int) { mat[i][j] = value }
  }
}

fun buildIntArrayMatrix(dimension: MatDim , buildFn: IntArrayMatrixBuilder.()->Unit)
  : Matrix<Int> {
  val builder  = IntArrayMatrixBuilder(dimension)
  builder.buildFn()
  return builder.build()
}

class IntArrayMatrixBuilder(dimension: MatDim) {
  private val numRows = dimension.first
  private var currentRow = 0
  private val result = intArrayMatrix(dimension, 0)

  fun r(vararg values: Int) {
    check(currentRow < numRows)
    rat(currentRow, *values)
    currentRow++
  }

  fun rat(rowIndex: Int, vararg values: Int) {
    require(rowIndex >= 0 && rowIndex < numRows)
    for ((c, x) in values.withIndex()) {
      result[currentRow, c] = x
    }
  }

  fun build(): Matrix<Int> = result
}

abstract class MatrixSpace<E>(
  val addMonoid: Monoid<E>, val mulMonoid: Monoid<E>) {

  companion object {
    fun <E> of(
      addMonoid: Monoid<E>, mulMonoid: Monoid<E>, zerosFn: (MatDim) -> Matrix<E>):
      MatrixSpace<E> = object: MatrixSpace<E>(addMonoid, mulMonoid) {
      override fun zeros(dimension: MatDim): Matrix<E> = zerosFn(dimension)
    }
  }

  abstract fun zeros(dimension: MatDim): Matrix<E>

  fun identity(n: Int): Matrix<E> {
    val result = zeros(n to n)
    for (i in 0 until n) {
      result[i, i] = mulMonoid.unit
    }
    return result
  }

  infix fun Matrix<E>.matrixmul(other: Matrix<E>): Matrix<E> {
    require(this.numColumns == other.numRows)
    val result = zeros(this.numRows to other.numColumns)
    for (k in 0 until this.numColumns) {
      for (i in 0 until this.numRows) {
        for (j in 0 until other.numColumns) {
          val s = with(mulMonoid) {this@matrixmul[i, k] stimes other[k, j]}
          with(addMonoid) {
            result[i, j] = result[i, j] stimes s
          }
        }
      }
    }
    return result
  }
}

