class Main(private val input: InputReaderKt, private val out: PrintWriter) {
    fun solve() {
        val MOD: Long = 1_000_000_000 + 7

        repeat(input.nextInt()) {
            val n = input.nextLong()
            val k = input.nextInt()

            // Sum of Even Index Binomial Coefficients
            val p = (1 until n).fold(1L) { acc, _ ->
                acc * 2 % MOD
            }
            val twoToNPower = p * 2 % MOD
            val b = LongArray(k + 1)
            b[0] = 1
            (1..k).forEach { power -> b[power] = (b[power - 1] * twoToNPower) % MOD }

            // x = AND of ith bits
            // y = XOR of ith bits

            // 1 = x > y = 0, all ith bits = 1, n - even
            val xGreaterThanY = 1 - n % 2

            // x = y = 0
            val xEqualsYEquals0 = if (n % 2 == 0L) (p - 1 + MOD) % MOD else p

            // x = y = 1, all ith bits = 1, n - odd
            val xEqualsYEquals1 = n % 2

            var casesWhenAndGreaterThanXor: Long = 0L
            var casesWhenAndEqualsXor: Long = 1L

            // for each bit
            repeat(k) { bit ->
                casesWhenAndGreaterThanXor += casesWhenAndEqualsXor * xGreaterThanY * b[k - 1 - bit]
                casesWhenAndGreaterThanXor %= MOD

                casesWhenAndEqualsXor *= xEqualsYEquals0 + xEqualsYEquals1
                casesWhenAndEqualsXor %= MOD
            }

            out.println((casesWhenAndGreaterThanXor + casesWhenAndEqualsXor) % MOD)
        }
    }
}

class InputReaderKt {
    private var st: StringTokenizer? = null
    private val input: BufferedReader = BufferedReader(InputStreamReader(System.`in`))

    fun hasNextToken(): Boolean {
        var t = st
        while (t == null || !t.hasMoreTokens()) {
            val line = input.readLine() ?: return false
            t = StringTokenizer(line)
        }
        st = t
        return true
    }

    fun nextToken(): String {
        var t = st
        while (t == null || !t.hasMoreTokens()) {
            val line = input.readLine() ?: throw IllegalStateException("End of input reached")
            t = StringTokenizer(line)
        }
        st = t
        return t.nextToken()
    }

    fun readLine() = input.readLine()

    fun nextInt() = nextToken().toInt()

    fun nextLong() = nextToken().toLong()

    fun nextDouble() = nextToken().toDouble()
}

