fun modPow(a: Long, b: Long, mod: Long) : Long {
	var res = 1L
	var c = a
	var cur = b
	while (cur > 0) {
		if (cur % 2 == 1L) {
			res = res * c % mod
		}
		c = c * c % mod
		cur = cur / 2
	}
	return res
}
fun main() {
	val t = readInt()
	val resList = mutableListOf<Long>()
	
	
	val fs = 501010
	val mod = 1000000007L
	val fact = MutableList<Long>(fs) { 1L }
	val ifact = MutableList<Long>(fs) { 1L }
	val invs = MutableList<Long>(fs) { 1L }
	for (i in 2 until fs) {
		fact[i] = fact[i - 1] * i % mod
		invs[i] = mod - invs[(mod % i).toInt()] * (mod / i) % mod
		ifact[i] = ifact[i - 1] * invs[i] % mod
	}
	fun binom(a: Int, b: Int) : Long {
		if (b == 0 || a == b) {
			return 1L
		}
		if (a < b || b < 0) {
			return 0L
		}
		return fact[a] * ifact[b] % mod * ifact[a - b] % mod
	}
	
	repeat (t) {
		val (n, k) = readIntList()
		
		var res = 0L
		if (n % 2 == 1) {
			res++
			for (i in 0 until n step 2) {
				res = (res + binom(n, i)) % mod
			}
			res = modPow(res, k.toLong(), mod)
		} else {
			var c = 1L
			var te = 0L
			for (i in 0 until n step 2) {
				te = (te + binom(n, i)) % mod
			}
			for (i in 0 until k) {
				res = (res + c * modPow(2L, n * (k - i - 1).toLong(), mod) % mod) % mod
				c = c * te % mod
