fun main()  {
    val modulo = 100_000_000L

    val reader = BufferedReader(InputStreamReader(System.`in`))
    val (n1, n2, k1, k2) = reader.readLine().split(' ').map { it.toInt() }

    val states = hashMapOf<Triple<Int, Int, Int>, Long>()
    var xfn: ((Int, Int, Int) -> Long)? = null
    xfn = { nn1: Int, nn2: Int, k12: Int ->
        val key = Triple(nn1, nn2, k12)
        if (key in states) {
            states[key]!!
        } else {
            val fn = xfn!!
            val result = when {
                nn1 < 0 || nn2 < 0 -> 0L
                nn1 + nn2 == 0 || k12 == 0 -> if (nn1 + nn2 == 0 && k12 == 0) 1L else 0L
                k12 == 1 -> (-k1..0).map { fn(nn1, nn2-1, it) }.reduce { a, b -> (a + b) % modulo }
                k12 == -1 -> (0..k2).map { fn(nn1-1, nn2, it) }.reduce { a, b -> (a + b) % modulo }
                k12 < 0 -> fn(nn1-1, nn2, k12+1)
                k12 > 0 -> fn(nn1, nn2-1, k12-1)
                else -> throw UnknownError("unreachable")
            }
            states[key] = result
            result
        }
    }

    println((-k1..k2).map { xfn(n1, n2, it) }.reduce { a, b -> (a + b) % modulo })
}

