fun solve(ir : InputReader, pw : PrintWriter) {

    val n : Int = ir.nextInt()
    val k : Int = ir.nextInt()
    val a = IntArray(n)
    var res = 0

    for (i in 0 until n)
        a[i] = ir.nextInt()

    for (i in 0 until k) {
        var ones = 0
        var twos = 0
        for (j in i until n step k) {
            if (a[j] == 1)
                ones++
            else
                twos++
        }

        res += if (ones > twos)
            twos
        else
            ones

    }

    pw.print(res)

}

