private fun <T: Comparable<T>> List<T>.compareTo(other: List<T>): Int {
    val n = Math.min(this.size, other.size)
    for (i in 0 until n) {
        val c = this[i].compareTo(other[i])
        if (c != 0) {
            return c
        }
    }
    return when {
        this.size < other.size -> -1
        this.size > other.size -> 1
        else -> 0
    }
}

