private fun countingArrays(n: Int, m: BigInteger): BigInteger {
    var mul = 1L.toBigInteger()
    val factors = mutableSetOf<Int>()
    var last = 0L.toBigInteger()
    var result = 0L.toBigInteger()
    var base = 1L.toBigInteger()
    for (i in 2 until n + 1) {
        base = (base * m) % MODLL
        if (mul <= m) {
            for (fa in primeFactor(i)) {
                if (!factors.contains(fa)) {
                    factors.add(fa)
                    mul *= fa.toBigInteger()
                    if (mul > m) {
                        break
                    }
                }
            }
        }
        // println(mul)
        // mul = lcmL(mul, i.toLong())
        // mul = mul.min(m + 1L)
        val count = if (mul > m) m else m - m / mul
        val a = (last * m) % MODLL
        val b = ((base - last) * count) % MODLL
        // println("$i, $mul, $count. $base, $a, $b, ${a + b}")
        last = (a + b + MODLL) % MODLL
        result = (result + last) % MODLL
    }
    return result
}

