/**
 * 返回质因数列表，已排序
 * 时间复杂度 n^0.5
 */
private fun primeFactor(n: Int): List<Int> {
    var remain = n
    val result = mutableListOf<Int>()
    var k = 2
    while (k * k <= remain) {
        while (remain != k && remain % k == 0) {
            result.add(k)
            remain /= k
        }
        k++
    }
    if (remain != 1) {
        result.add(remain)
    }
    return result
}

import java.util.Scanner

fun main() {
	val sc = Scanner(System.`in`)

	val n = sc.nextInt()
	val m = sc.nextLong()

	val lim = 998244353L

	// calculating the number of all the possible arrays for each length from 1 to n
	var currPow = 1L
	var res = 0L
	for (i in 1..n) {
		currPow = (currPow * (m % lim)) % lim
		currPow = (currPow + lim) % lim

		res = (res + currPow) % lim
		res = (res + lim) % lim
	}

	// calculate primes
	val primes = mutableListOf<Int>()
	val isPrime = MutableList(n + 1) { true }
	var currPrime = 2L
	while (currPrime <= n) {
		if (isPrime[currPrime.toInt()]) {
			primes.add(currPrime.toInt())

			for (nonPrime in currPrime * currPrime..n step currPrime) {
				isPrime[nonPrime.toInt()] = false
			}
		}

		currPrime += 1L
	}
	isPrime.clear()

	// subtracting the number of all the 'bad' array for each array length from 1 to n
	// left with only the 'good' ones

	var lastPrimeIdx = 0
	var currPrimesMult = 1L
	var toSubtract = 1L

	for (currLength in 1..n) {
		if (lastPrimeIdx < primes.size && currLength >= primes[lastPrimeIdx]) {
			currPrimesMult *= primes[lastPrimeIdx]
			++lastPrimeIdx
		}

		if (m < currPrimesMult) {
			break
		}

		val newPart = (m / currPrimesMult) % lim
		if (newPart == 0L) {
			break
		}

		toSubtract = (toSubtract * newPart) % lim
		toSubtract = (toSubtract + lim) % lim

		res = (res - toSubtract) % lim
		res = (res + lim) % lim
	}

	println(res)

}

