val MOD = 998244353
val MOD_BIG = BigInteger.valueOf(MOD.toLong())

fun solve(n: Int, m: Long): Long {
    var lcm = 1L
    var all = BigInteger.valueOf(1L)
    val bigM = m.toBigInteger()
    var bad = 1L
    var toDeduct = 0L
    var s = 0L

    for (i in 1 .. n) {
        if (lcm <= m && i.prime()) {
            lcm = (lcm * i) / gcd(i.toLong(), lcm)
        }

        val rem = m / lcm
        all = (all * bigM) % MOD_BIG
        bad = (bad * (rem % MOD)) % MOD
        toDeduct = (toDeduct + bad) % MOD
        s = (s + all.toLong()) % MOD
    }

    return toAdd(s, toDeduct)
}

fun Int.prime(): Boolean {
