fun zFunc(s: String): IntArray {
    val z = IntArray(s.length)

    var l = 0
    var r = 0
    for (i in 1 until s.length) {
        if (i < r) {
            z[i] = minOf(r - i + 1, z[i - l])
        }
        while (i + z[i] < s.length && s[z[i]] == s[i + z[i]]) {
            z[i]++
        }

        if (r < i + z[i] - 1) {
            r = i + z[i] - 1
            l = i
        }
    }

    return z
}

fun String.fastContains(p: String): Boolean {
    if (p.length > this.length) {
