}

class Graph(val size: Int) {
    private val g = Array(size) { mutableListOf<Edge>() }

    fun addEdge(from: Int, to: Int, w: Int = 1) = g[from].add(Edge(from, to, w))

    fun getEdges(from: Int) = g[from]

    fun getAllEdges() = g.flatMap { it }
}

fun findShortestPaths(g: Graph, source: Int): IntArray {
    val distances = IntArray(g.size) { Int.MAX_VALUE }
    distances[source] = 0
    val handled = BooleanArray(g.size)

    val pq = PriorityQueue<Int>(compareBy { distances[it] }).apply {
        add(source)
    }

    while (pq.isNotEmpty()) {
        val vertex = pq.poll()
        if (handled[vertex]) continue
        val distanceToVertex = distances[vertex]

        for ((_, to, weight) in g.getEdges(vertex)) {
            if (distanceToVertex + weight < distances[to]) {
                distances[to] = distanceToVertex + weight
                pq.add(to)
            }
        }
    }

    return distances
}

data class Edge(val from: Int, val to: Int, val w: Int = 1)

data class FlowEdge(val from: Int, val to: Int, val capacity: Int) {
    var flow = 0

    fun residual() = capacity - flow
}

class FlowGraph(val n: Int) {
    val from = Array(n) { mutableListOf<FlowEdge>() }
    val to = Array(n) { mutableListOf<FlowEdge>() }

    fun addEdge(f: Int, t: Int, c: Int = 1): FlowEdge {
        val e = FlowEdge(f, t, c)
        from[f].add(e)
        to[t].add(e)
        return e
    }

    fun findMaxFlow(source: Int, sink: Int): Int {
        while (tryToAddFlow(source, sink)) {
            //do nothing
        }

        return from[source].sumBy { it.flow }
    }

    private fun tryToAddFlow(source: Int, sink: Int): Boolean {
        val visited = BooleanArray(n)
        val cameByEdge = Array<FlowEdge?>(n) { null }
        visited[source] = true
        val queue = LinkedList<Int>()
        queue.add(source)

        while (queue.isNotEmpty()) {
            val v = queue.poll()

            for (e in from[v]) {
                if (!visited[e.to] && e.residual() > 0) {
                    visited[e.to] = true
                    cameByEdge[e.to] = e
                    queue.add(e.to)
                }
            }

            for (e in to[v]) {
                if (!visited[e.from] && e.flow > 0) {
                    visited[e.from] = true
                    cameByEdge[e.from] = e
                    queue.add(e.from)
                }
            }
        }

        if (!visited[sink]) {
            return false
        }

        var v = sink
        var maxFlow = Int.MAX_VALUE
        while (cameByEdge[v] != null) {
            val e = cameByEdge[v]!!
            if (e.to == v) {
                maxFlow = minOf(maxFlow, e.residual())
                v = e.from
            } else {
                maxFlow = minOf(maxFlow, e.flow)
                v = e.to
            }
        }

        v = sink
        while (cameByEdge[v] != null) {
            val e = cameByEdge[v]!!
            if (e.to == v) {
                e.flow += maxFlow
                v = e.from
            } else {
                e.flow -= maxFlow
                v = e.to
            }
        }

        return true
    }
}

class SumSegmentTree(n: Int) {

    private val base = (2.0.pow(ceil(log2(n.toDouble())))).toInt()
    private val a = IntArray(base * 2)

    fun agg(left: Int, right: Int): Int {
        var l = left + base
        var r = right + base

        var agg = 0
        while (l <= r) {
            if (l % 2 != 0) {
                agg += a[l++]
            }
            if (r % 2 == 0) {
                agg += a[r--]
            }
            l /= 2
            r /= 2
        }

        return agg
    }

    fun set(pos: Int, v: Int) {
        var i = pos + base
        a[i] = v
        i /= 2
        while (i > 0) {
            a[i] = a[i * 2] + a[i * 2 + 1]
            i /= 2
        }
    }
}

