private fun Modulo138d2D.powMod(base: Long, exp: Long): Long {
    if (exp == 0L)
        return 1
    val res = powMod(base, exp / 2)
    return if (exp % 2 == 1L) {
        timesMod(res, timesMod(res, base))
    } else {
        timesMod(res, res)
    }
}

