private class Modulo138d2D(val base: Long) {
    init {
        require(base * base / base == base) { "The base $base caused an overflow" }
    }

    fun plusMod(a: Long, b: Long) = a.plus(b).mod(base)
    fun minusMod(a: Long, b: Long) = plusMod(a, -b)
    fun timesMod(a: Long, b: Long) = a.times(b).mod(base)
}

private class PrimesSieve138d2D private constructor(val size: Int) {
    companion object {
        fun upTo(n: Int): PrimesSieve138d2D = PrimesSieve138d2D(size = n + 1)
    }

    private val isComposite = BitSet(size).apply {
        for (i in 2 until size()) {
            if (!get(i)) {
                for (j in i * 2 until size step i)
                    set(j, true)
            }
        }
    }

    fun isPrime(i: Int): Boolean {
        require(i >= 1) { "Expected a positive number, got $i" }
        require(i < size) { "Expected a number smaller than $size got $i" }
        return !isComposite[i]
    }
}
