fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val _k = sc.nextLong()
    if (_k >= n) {
        println(0)
        return
    }
    val k = _k.toInt()
    val c = (n - k).toLong()
    var ans = ModInt(c).pow(n.toLong())
    for (i in 0 until n - k - 1) {
        val v = comb(c, c - i - 1) * ModInt(c - i - 1).pow(n.toLong())
        if (i % 2 == 0) {
            ans -= v
        } else {
            ans += v
        }
    }
    ans *= comb(n.toLong(), c)
    if (k > 0) {
        ans *= ModInt(2)
    }
    println(ans)
}

