@Suppress("MemberVisibilityCanBePrivate", "unused")
@ExperimentalStdlibApi
@ExperimentalTime
@ExperimentalUnsignedTypes
inline class ModInt(private val x: Int) {
    companion object {
        private const val mod = 998_244_353

        //        const val mod = 1e9.toInt() + 7
        fun Int.toModInt() = ModInt(this)
        fun Int.toModIntSafe() = ModInt((this % mod + mod) % mod)
        fun Long.toModIntSafe() = ModInt(((this % mod + mod) % mod).toInt())
        val ZERO = ModInt(0)
        val ONE = ModInt(1)
        val TWO = ModInt(2)
        val TEN = ModInt(10)

        fun Iterable<ModInt>.sum() = fold(ZERO, ModInt::plus)
        fun Array<ModInt>.sum() = fold(ZERO, ModInt::plus)

        inline fun <T> Iterable<T>.sumOf(f: (T) -> ModInt) = fold(ZERO) { acc, i -> acc + f(i) }
        inline fun <T> Array<T>.sumOf(f: (T) -> ModInt) = fold(ZERO) { acc, i -> acc + f(i) }
        inline fun IntRange.sumOf(f: (Int) -> ModInt) = fold(ZERO) { acc, i -> acc + f(i) }
    }

    operator fun plus(k: ModInt) = ModInt((x + k.x).let { if (it >= mod) it - mod else it })
    operator fun minus(k: ModInt) = ModInt((x - k.x).let { if (it < 0) it + mod else it })
    operator fun times(k: ModInt) = ModInt((x * k.x.toLong() % mod).toInt())
    operator fun div(k: ModInt) = this * k.inv()
    operator fun unaryMinus() = if (x == 0) this else ModInt(mod - x)
    fun inv() = pow(mod - 2)
    fun pow(p: Int): ModInt = if (p == 0) ONE else pow(p / 2).let { if (p % 2 == 1) it * it * this else it * it }
    fun toInt() = x
    override fun toString() = x.toString()
}

