fun <T : Comparable<T>> max(a: T, b: T): T = if (b > a) b else a
fun <T : Comparable<T>> min(a: T, b: T): T = if (b < a) b else a
fun Number.isEven(): Boolean = if (this.toInt() and 1 == 0) true else false
fun Number.isOdd(): Boolean = !this.isEven()

tailrec fun gcd(a: Int, b: Int): Int {
    if (a == 0) return b
    else return gcd(b % a, a)
}

fun lcm(a: Int, b: Int): Int {
    return (a / gcd(a, b)) * b
}

fun main(args: Array<String>) {
    if (args.isNotEmpty()) System.setIn(FileInputStream(args[0]))
    val br = BufferedReader(InputStreamReader(System.`in`))
    val bw = BufferedWriter(OutputStreamWriter(System.out))

    var st = StringTokenizer(br.readLine())
    val n = st.nextToken().toInt()
    val arr = IntArray(n + 1)
    st = StringTokenizer(br.readLine())
    for (i in 1..n) {
        arr[i] = st.nextToken().toInt()
    }
    var answer = 1
    for (i in 1..n) {
        var loop = false
        val a = i
        var b = a
        for (j in 1..n) {
            b = arr[b]
            if (b == a) {
                loop = true
                if (j.isEven()) answer = lcm(answer, j/2)
                else answer = lcm(answer, j)
                break
            }
        }
        if (!loop) {
            answer = -1
            break
        }
    }
    bw.write("$answer")
    bw.newLine()
    bw.flush()
}

