fun Int.primeFactors(): List<Int> {
    val L = mutableListOf<Int>()
    var v: Int = 2
    var nn = this
    while (nn > 1 && L.size < 21) {
        if (nn % v == 0) {
            L.add(v)
            nn /= v
        } else {
            v++
        }
    }
    return L
}

