private fun sort(array: IntArray, barray: IntArray, low: Int, high: Int) {

    var i = low
    var j = high
    val x = array[low + (high - low) / 2]

    do {
        while (array[i] < x) ++i
        while (array[j] > x) --j
        if (i <= j) {
            val tmp = array[i]
            array[i] = array[j]
            array[j] = tmp

            val pmt = barray[i]
            barray[i] = barray[j]
            barray[j] = pmt

            i++
            j--
        }
    } while (i <= j)

    if (low < j) sort(array, barray, low, j)
    if (i < high) sort(array, barray, i, high)

}

