private fun fastPow(a: Long, exp: Long, mod: Long): Long {
    var result = 1L % mod
    var base = a % mod
    var remain = exp
    while (remain != 0L) {
        if (remain % 2L == 1L) {
            result = (result * base) % mod
        }
        base = (base * base) % mod
        remain /= 2L
    }
    return result
}

private fun gcd(a: Int, b: Int): Int {
    return if (b == 0) a else gcd(b, a % b)
}

private fun gcdL(a: Long, b: Long): Long {
    return if (b == 0L) a else gcdL(b, a % b)
}

