private fun requiredLen(n: Int, x: Long): Int {
    val queue = listOf(x).toArrayDeque()
    val visited = mutableSetOf<Long>()
    var step = 0
    while (queue.isNotEmpty()) {
        repeat(queue.size) {
            val num = queue.removeFirst()
            if (num < 0L) {
                return step
            }
            if (visited.contains(num)) {
                return@repeat
            }
            visited.add(num)
            val str = num.toString()
            if (str.length == n) {
                return step
            }
            if (str.length > n) {
                return@repeat
            }
            val digits = BooleanArray(10)
            for (char in str) {
                digits[char.toDigit()] = true
            }
            for (d in 2 until 10) {
                if (!digits[d]) {
                    continue
                }
                queue.addLast(num * d)
            }
        }
        step++
        // println(queue)
    }
    return -1
}

