fun listFrom(a: Array<Int>, m: Int): MutableList<Int> {
    val n = a.size
    var res = mutableListOf<Int>()
    for (s in 0 until (1 shl (n))) {
        var sum = 0
        for(k in 0 until n){
            if ((s shr k) and 1 == 1) sum = (sum + a[k]) % m
        }
        res.add(sum)
    }
    return res

}


