class MeetInTheMiddle(private val numbers: List<Long>, private val moduloValue: Long) {

    private val firstModuloSumList = mutableListOf<Long>()
    private val secondModuloSumList = mutableListOf<Long>()

    fun getLargestModuloSum(): Long {
        val modNumbers = numbers.map { it.rem(moduloValue) }
        if (modNumbers.size == 1) {
            return modNumbers.first()
        }
        val firstList = modNumbers.subList(0, modNumbers.size / 2)
        val secondList = modNumbers.subList(modNumbers.size / 2, modNumbers.size)

        bruteForceModuloSums(0, firstList, firstModuloSumList, firstList.first())
        bruteForceModuloSums(0, firstList, firstModuloSumList, 0L)
        bruteForceModuloSums(0, secondList, secondModuloSumList, secondList.first())
        bruteForceModuloSums(0, secondList, secondModuloSumList, 0L)

        return maxModuloSumBetweenList()
    }

    private fun maxModuloSumBetweenList(): Long {
        val firstModuloSumSet = TreeSet(firstModuloSumList)
        val secondModuloSumSet = TreeSet(secondModuloSumList)
        var maxSum = (firstModuloSumSet.last()).coerceAtLeast(secondModuloSumSet.last())

        firstModuloSumSet.forEach {
            val gap: Long = moduloValue.minus(it+1)
            val floorValue = secondModuloSumSet.floor(gap)
            if (floorValue != null) {
                maxSum = maxSum.coerceAtLeast((it + floorValue).rem(moduloValue))
            }
        }
        return maxSum
    }

    private fun bruteForceModuloSums(index: Int, modNumbers: List<Long>, moduloSumList: MutableList<Long>, sum: Long) {
        if (index == modNumbers.size - 1) {
            moduloSumList.add(sum.rem(moduloValue))
            return
        }
        bruteForceModuloSums(index + 1, modNumbers, moduloSumList, sum + modNumbers[index + 1])
        bruteForceModuloSums(index + 1, modNumbers, moduloSumList, sum)
    }
}


/**
 * IO class with exposing various input operations. Kotlin Translation of
 * [Kattio.java](https://github.com/Kattis/kattio/blob/master/Kattio.java)
 */
class KotlinIo(private val input: InputStream, private val outPut: OutputStream) :
    PrintWriter(BufferedOutputStream(outPut)) {

    private var reader: BufferedReader = BufferedReader(InputStreamReader(input))
    private var line: String? = null
    private var tokenizer: StringTokenizer? = null
    private var token: String? = null

    fun hasMoreTokens() = peekToken() != null

    fun getInt() = nextToken()!!.toInt()

    fun getDouble() = nextToken()!!.toDouble()

    fun getLong() = nextToken()!!.toLong()

    fun getWord() = nextToken()

    fun getLine(): String? {
        try {
            return reader.readLine()
        } catch (e: IOException) {
            e.printStackTrace()
        }
        return null
    }

    private fun peekToken(): String? {
        if (token == null) {
            try {
                while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
                    line = reader.readLine()
                    if (line == null) {
                        return null
                    }
                    tokenizer = StringTokenizer(line)
                }
                token = tokenizer!!.nextToken()
            } catch (e: IOException) {
                e.printStackTrace()
            }
        }
        return token
    }

    private fun nextToken(): String? {
        val ans = peekToken()
        token = null
        return ans
    }
}

