fun Long.round(k: Int): Long {
    var t = this
    var doub = 0
    while (t % 2 == 0L) {
        doub += 1
        t /= 2
    }
    var five = 0
    while (t % 5 == 0L) {
        five += 1
        t /= 5
    }

    var res = this
    while (doub < k) {
        res *= 2
        doub += 1
    }
    while (five < k) {
        res *= 5
        five += 1
    }
    return res
}

