val MOD = 1_000_000_007L

class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val N = ni()
    val (L, R) = na2(N)

    var ans = 0.0

    for (i in 0 until N) {
      for (j in 0 until N) {
        if (i == j) continue
        for (x in L[j] .. R[j]) {
          var prob = 1.0
          for (k in 0 until N) {
            if (k == j) continue

            prob *= if (k == i) {
              val l = max(if (i < j) x else x + 1, L[i])
              val r = R[i]
              max(0, r - l + 1)
            } else {
              val l = L[k]
              val r = min(if (j < k) x else x - 1, R[k])
              max(0, r - l + 1)
            }
          }
          ans += prob * x
        }
      }
    }

    debug{"ans:$ans"}
    for (i in 0 until N) {
      ans /= (R[i] - L[i] + 1)
    }

    out.println("%.10f".format(ans))
  }













































