import kotlin.properties.Delegates
import kotlin.reflect.KProperty

class Memorize<T, R>(val func: (T) -> R) {
    val cache = mutableMapOf<T, R>()

    operator fun getValue(thisRef: Any?, property: KProperty<*>) = { n: T ->
        cache.getOrPut(n) { func(n) }
    }
}

var k by Delegates.notNull<Long>()
var l by Delegates.notNull<Long>()
val f: (Pair<Long, Boolean>) -> Long by Memorize { (weight, hasLeast) ->
    when {
        weight < 0 -> 0
        weight == 0L -> if (hasLeast) 1L else 0L
        hasLeast -> ((1..k).fold(0L) { acc: Long, l: Long -> acc + f(Pair(weight - l, true)) })%1000000007L
        else -> { ((if (k >= l) (l..k).fold(0L) { acc: Long, l: Long ->
                        acc + f(Pair(weight - l, true))
            } else 0L) + (1..minOf(k, l - 1)).fold(0L) { acc: Long, l: Long ->
            acc + f(Pair(weight - l, false)) })%1000000007L
        }
    }//.also { println("weight: $weight hasleast: $hasLeast res: $it") }
}

