import java.io.BufferedReader
import java.io.InputStreamReader

const val MODULO = 1000000007L

fun calc(n: Long, k: Long, d: Long, cache: MutableMap<Triple<Long, Long, Long>, Long>): Long {
    if (n <= 0L) {
        return if (d == 0L && n == 0L) 1L else 0L
    }

    return cache.getOrPut(Triple(n, k, d)) {
        (1..k).map { kIdx -> calc(n-kIdx, k, if (kIdx >= d) 0L else d, cache) }
                .reduce { a, b -> (a + b) % MODULO }
    }
}

