fun findMaxGap(arr: MutableList<Int>, excludePos: Int) : Int {
    val value = arr[excludePos]
    arr.removeAt(excludePos)

//    System.out.println(arr)

    var max = arr[1] - arr[0]
    for(i in 1 until arr.size) {
        if (arr[i] - arr[i-1] > max) {
            max = arr[i] - arr[i-1]
        }
    }

    arr.add(excludePos, value)

    return max
}

