    val lengthArray = readLine()!!.split(" ").asSequence().map { it.toInt() }.toList()

    if (n == 3) {
        println(lengthArray[2] - lengthArray[0])
        return
    }

    var min = lengthArray[1] - lengthArray[0] + lengthArray[2] - lengthArray[1]
    var max = lengthArray[1] - lengthArray[0]

    for (i in 2 until n - 1) {
        val left = lengthArray[i] - lengthArray[i - 1]
        val right = lengthArray[i + 1] - lengthArray[i]

        if (left > max) {
            max = left
        }

        if (right > max) {
            max = right
        }

        if (left + right < min) {
            min = left + right
        }
    }

    println(if (min > max) min else max)
}

