object Algorithms {

    tailrec fun gcd(a: Int, b: Int): Int = if (b == 0) a else gcd(b, a % b)
    tailrec fun gcd(a: Long, b: Long): Long = if (b == 0L) a else gcd(b, a % b)

    fun lcm(a: Int, b: Int): Int = a / gcd(a, b) * b
    fun lcm(a: Long, b: Long): Long = a / gcd(a, b) * b

}

class FastInputReader {
    private val bufferedReader: BufferedReader = System.`in`.bufferedReader()
    private var stringTokenizer: StringTokenizer = StringTokenizer("")

    fun nextLine(): String = bufferedReader.readLine()
    fun next(): String {
        while (!stringTokenizer.hasMoreTokens())
            stringTokenizer = StringTokenizer(nextLine())
        return stringTokenizer.nextToken()
    }

    fun readInt(): Int = next().toInt()
    fun readLong(): Long = next().toLong()
    fun readDouble(): Double = next().toDouble()

    fun readIntArray(size: Int) = IntArray(size, { readInt() })
    fun readLongArray(size: Int) = LongArray(size, { readLong() })
    fun readStringArray(size: Int) = Array(size, { next() })
    inline fun <reified T> readTArray(size: Int, convert: (Int, String) -> T) = Array(size, { convert(it, next()) })

    fun readIntTable(rows: Int, cols: Int) = Array(rows, { readIntArray(cols) })
    fun readLongTable(rows: Int, cols: Int) = Array(rows, { readLongArray(cols) })
    fun readStringTable(rows: Int, cols: Int) = Array(rows, { readStringArray(cols) })
    inline fun <reified T> readTTable(rows: Int, cols: Int, convert: (Int, Int, String) -> T) = Array(rows, { readTArray(cols, { col, s -> convert(it, col, s) }) })
}

