    for(i in 1 until M.size) M[i] = M[i-1] * 10 + 1

    var D = hashMapOf(n0 to 0)

    for(k in M.size-2 downTo 1) {
        if(M[k] > n0) continue

        val Dk = HashMap<Long, Int>()

        for((n, c) in D) {
            Dk.checkMin(n % M[k], c + (n / M[k] * k).toInt())
            val n1 = M[k+1] - n
            Dk.checkMin(n1 % M[k], c + k + 1 + (n1 / M[k] * k).toInt())
        }

        D = Dk
    }

    val ans = D[0]

    println(ans)
}

fun <K> HashMap<K, Int>.checkMin(k: K, v: Int) { if(v < getOrDefault(k, Int.MAX_VALUE)) put(k, v) }

