import java.io.BufferedReader
import java.io.InputStreamReader

fun findMin(n: Int, v: Int): Int {
    var cap = 0
    var money = 0
    var rem: Int
    for (i in 1 .. n){
        rem = n - i
        if (cap < rem){
            val missingInTank: Int
            if ((v - cap) <= rem){
                missingInTank = v - cap
            }else{
                missingInTank = rem
            }
            cap += missingInTank
            money += i*missingInTank
        }
        cap--
    }
    return money
}

