const val INF = 99


fun solve() {

    val a = next().toCharArray().map { it.toInt() - 48 }
    val n = a.size

    var ans = INF
    for (i in 0 until n) {
        for (j in 0 until n) {
            if (i !=j) {
                val x = a[i]
                val y = a[j]
                if ((x*10 + y) % 25 == 0) {
                    val b = a.toMutableList()
                    var count = 0
                    for (k in j+1 until n) {
                        b[k] = b[k-1].also { b[k-1] = b[k] }
                        count++
                    }
                    var l = i
                    if (i < j) {
                       l++
                    }
                    for (k in l until n-1) {
                        b[k] = b[k-1].also { b[k-1] = b[k] }
                        count++
                    }

                    if (b[0] == 0) {
                        count += b.indexOfFirst { it != 0 }
                    }

                    ans = min(ans, count)
                }
            }
        }
    }

    print(if (ans != INF) ans else -1)
}




