fun res(a: Char, b: Char): Int {
    var help1 = -1
    var help2 = -1
    val l = str.length
//    if (b == '0' && str[0] == '5' && str[1] == '0')
//        return 2 * l - 4
    for (i in str.length - 1 downTo 0) {
        if (str[i] == a) {
            if (help2 != -1) {
                if (i != 0)
                    return 2 * l - 3 - i - help2
                if (b == '0' && str[1] == '0')
                    return 2 * l - 4
                var help = -1
                for (j in 1 until l) {
                    if (str[j] != '0') {
                        help = j
                        break
                    }
                }
                if (help != help2)
                    return 2 * l - 4 - help2 + help
                return 2 * l - 4
            }
            else if (help1 == -1)
                help1 = i
        }
        else if (str[i] == b) {
            if (help1 != -1) {
                if (i != 0)
