}

val t = IntArray(2 * sz)

fun upd(v: Int, vl: Int, vr: Int, i: Int, x: Int) {
    if (i < vl || i > vr) return
    if (vl == vr) {
        t[v] = x
        return
    }
    val vm = (vl + vr) / 2
    upd(v * 2 + 1, vl, vm, i, x)
    upd(v * 2 + 2, vm + 1, vr, i, x)
    t[v] = max(t[v * 2 + 1], t[v * 2 + 2])
}

fun query(v: Int, vl: Int, vr: Int, l: Int, r: Int): Int {
    if (vl > r || l > vr) return -1
    if (vl >= l && vr <= r) return t[v]
    val vm = (vl + vr) / 2
    return max(query(v * 2 + 1, vl, vm, l, r), query(v * 2 + 2, vm + 1, vr, l, r))
}

val fact = LongArray(maxn)
val invfact = LongArray(maxn)

fun calcFactorials() {
    fact[0] = 1
    for (i in 1..maxn - 1) fact[i] = (fact[i - 1] * i.toLong()) % MOD
    for (i in 0..maxn - 1) invfact[i] = powmod(fact[i], MOD - 2, MOD)
}

fun cnk(n: Int, k: Int, m: Long): Long {
    return ((fact[n] * invfact[k]) % m) * invfact[n - k] % m
}

fun powmod(x: Long, d: Long, m: Long): Long {
    if (d == 0L) return 1
    if (d % 2 == 0L) {
        val y = powmod(x, d / 2, m)
        return (y * y) % m
    }
    return x * powmod(x, d - 1, m) % m
}

fun divup(x: Int, y: Int): Int {
    return (x + y - 1) / y
}

fun divup(x: Long, y: Long): Long {
    return (x + y - 1) / y
}

fun gcd(x: Long, y: Long): Long {
    if (x == 0L || y == 0L) return x + y
    if (x > y) return gcd(x % y, y)
    return gcd(y % x, x)
}

