private fun isFinal(r: Int, n: Int): Boolean {
    return log2(n.toDouble()).toInt() == r
}

private fun round(n: Int, a_: Int, b_: Int): Int {
    var n = n
    var a = minOf(a_, b_)
    var b = maxOf(a_, b_)

    var games = 0

    while (true) {
        games++

        if (b % 2 == 0 && a + 1 == b) {
            return games
        }

        n /= 2
        a = (a + 1) / 2
        b = (b + 1) / 2
    }
}

