fun dfs(a: Int, b: Int, c: Int = 0): Int {
    if (b == a) return c + 1
    if (b < a) return -1
    val da = if (b % 2 == 0) dfs(a, b / 2, c + 1) else -1
    val db = if (b % 10 == 1) dfs(a, (b - 1) / 10, c + 1) else -1
    if (da != -1 || db != -1) list.add(b)
    return max(da, db)
}

