    fun go(a: Long, b: Long, ls: List<Long>): List<Long> =
        if(a == b) ls + listOf(b)
        else if (a > b || a < 0) emptyList()
        else go(a*2, b, ls + listOf(a)) + go(a*10 + 1, b, ls + listOf(a))


    return go(a, b, emptyList())
}

