    val k = IntArray(4)
    val c1 = IntArray(4)
    val c2 = CharArray(4)

    for (i in 0 until s.length)
        if (s[i] == '!')
            c1[i % 4]++
        else
            c2[i % 4] = s[i]

    for (i in 0..3)
