    class TaskB: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val firstName = scanner.nextLine()
            val secondName = scanner.nextLine()
            val mixedUpName = scanner.nextLine()

            val alphabet = Array(26) { 0 }
            val mixedUpAlphabet = Array(26) { 0 }

            firstName.forEach { alphabet[it - 'A']++ }
            secondName.forEach { alphabet[it - 'A']++ }
            mixedUpName.forEach {  mixedUpAlphabet[it - 'A']++ }

            for (it in 0..25) {
                if (alphabet[it] != mixedUpAlphabet[it]) {
                    printer.println("NO")
                    return
                }

            }
            printer.println("YES")
        }

    }

    class TaskC: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val countOfCubes = scanner.nextInt()

            var cubeSum = 0
            var height = 0
            while(cubeSum <= countOfCubes) {
                height++
                cubeSum += (height * (height + 1)) / 2
            }
            printer.println(height - 1)
        }

    }

    class TaskD: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val stringLength = scanner.nextInt()

            var result = 0
            (0 until stringLength) {
                val char = scanner.nextChar()
                when(char) {
                    '0' -> result++
                    '1' -> result--
                }
            }
            printer.println(if (result < 0) -result else result)
        }

    }

    class TaskE: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val wordCount = scanner.nextInt()
            val compukterDelay = scanner.nextInt()
            val words = Array(100005) { 0 }
            var screenedWords = 1

            (1..wordCount) { words[it] = scanner.nextInt() }

            var it = wordCount - 1
            while (it >= 1) {
                if (words[it + 1] - words[it] > compukterDelay)
                    break
                it--
                screenedWords++
            }
            printer.println(screenedWords)
        }

    }

    class TaskF: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val count = scanner.nextInt()
            val lengths = Array(count) { scanner.nextInt() }.sortedArray()

            var l = 0
            var b1 = 0
            var b2 = 0

            for (it in 0 until count) {
                if (it == count - 1 || lengths[it] != lengths[it + 1]) {
                    b1 = Math.max(b1, it - l + 1)
                    b2++
                    l = it + 1
                }
            }
            printer.println(b1.toString() + " " + b2)
        }

    }

    class TaskG: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val aLength = scanner.nextInt()
            val bLength = scanner.nextInt()
            val k = scanner.nextInt()
            val m = scanner.nextInt()

            val a = Array(aLength) { scanner.nextInt() }
            val b = Array(bLength) { scanner.nextInt() }
            printer.println(if(a[k-1]<b[bLength-m]) "YES" else "NO")
        }

    }

    class TaskH: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val player1 = scanner.nextInt()
            val player2 = scanner.nextInt()

            var firstWinCount = 0
            var nobodyWinCount = 0
            var secondWinCount = 0
            (1..6) {
                val didFirstWin = abs(player1 - it)
                val didSecondWin = abs(player2 - it)
                when {
                    didFirstWin < didSecondWin -> firstWinCount++
                    didFirstWin > didSecondWin -> secondWinCount++
                    else -> nobodyWinCount++
                }
            }
            printer.println("$firstWinCount $nobodyWinCount $secondWinCount")
        }

    }

    class TaskI: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val n = scanner.nextLong()
            val m  = scanner.nextLong()

            var countOfPairs = 0L
            (1..n) {
                countOfPairs += (m + it % 5) / 5
            }
            printer.println(countOfPairs)
        }

    }

    class TaskJ: Task() {
        override fun solve(scanner: Scanner, printer: PrintWriter) {
            val iqCount = scanner.nextInt()
            val iq = Array(iqCount) { scanner.nextInt() }

            val oddness = iq[0] % 2 + iq[1] % 2 + iq[2] % 2 >= 2
            (0 until iqCount) {
                if (iq[it] % 2 == 1 && !oddness)
                    printer.println(it + 1)
                if (iq[it] % 2 == 0 && oddness)
                    printer.println(it + 1)
            }
        }

    }

