fun main(args: Array<String>) {
    val n = readLine() ?: ""
    val str = readLine() ?: ""
    var result = ""
    val chars = str.toCharArray()
    var i = 0
    while (i < chars.size) {
        var sum = 0
        var zero = ""
        for (j in i until chars.size) {
            if (chars[j] == '1') {
                sum++
                i++
            }
            else {
                i = j + 1
                break
            }
        }
        for (j in i until chars.size -1) {
            if (chars[j] == '0') {
                zero += "0"
                i++
            }
            else {
                i = j
                break
            }
        }
        result += sum
        result += zero
    }
    if(chars[chars.size-1] == '0')
        result+="0"
    println(result)

}

