    fun readLongs() = readLine()!!.split(" ").map(String::toLong)

    val (f1, f2) = readLongs()
    var goal = readLong()
    if (goal == 1L) {
        print(Math.floorMod(f1, 1000000007))
        return
    }
    if (goal == 2L) {
        print(Math.floorMod(f2, 1000000007))
        return
    }
    var currentPos = 1L
    var previous = f1
    var current = f2
    while (++currentPos < goal) {
        val new = current - previous
        previous = current
        current = new
        if(previous == f1 && current == f2) {
            val cycle = currentPos - 1
            goal = (goal - 2) % cycle + 2
            currentPos = 1
        }
    }
    print(Math.floorMod(current, 1000000007))
}

