import java.lang.ArithmeticException

fun main() {
    val (n, l, r) = readInts()

    // number of possible elements for each modulo 3
    val ele = run {
        val sz = r - l + 1
        val quot = sz / 3
        val rem = sz - quot * 3
        IntArray(3) {
            quot + if((it - l) umod 3 < rem) 1 else 0
        }
    }


    var d = List(3) { ele[it].toModInt() }

    repeat(n-1) {
        val nd = List(3) { i ->
            d[i] * ele[0] +
            d[(i+1)%3] * ele[2] +
            d[(i+2)%3] * ele[1]
        }
        d = nd
    }

    println(d[0])
}

infix fun Int.umod(base: Int) =
    (this % base).let { if(it >= 0) it else it + base }

infix fun Long.umod(base: Long) =
    (this % base).let { if(it >= 0) it else it + base }

infix fun Long.umod(base: Int) =
    (this % base).let { if(it >= 0) it else it + base }

fun Int.modInv(base: Int): Int {
    var s = 0
    var os = 1
    var r = base
    var or = this

    while(r != 0) {
        val q = or / r
        or = r.also { r = or - q * r }
        os = s.also { s = os - q * s }
    }

    return if(or != 1) throw ArithmeticException("$this has no modulo inverse in base $base")
    else os.let { if(it >= 0) it else it + base }
}

/** modint inline class, requires hardcoded mod base **/
const val MODBASE = 1_000_000_007

@Suppress("DEPRECATION")
inline fun Int.toModInt() = ModInt(this umod MODBASE)
@Suppress("DEPRECATION")
inline fun Long.toModInt() = ModInt((this umod MODBASE).toInt())

inline class ModInt
@Deprecated("use toModInt instead") constructor(val int: Int) {
    operator fun plus(other: ModInt) = plus(other.int) // MODBASE < 2^30
    operator fun plus(other: Int) =  (int + other).toModInt() // careful of possible overflow
    operator fun inc() = plus(1)

    operator fun minus(other: ModInt) = minus(other.int)
    operator fun minus(other: Int) = (int - other).toModInt()
    operator fun dec() = minus(1)

    operator fun times(other: ModInt) = times(other.int)
    operator fun times(other: Int) = (int.toLong() * other).toModInt()

    @Suppress("DEPRECATION")
    fun inv() = ModInt(int.modInv(MODBASE))

    operator fun div(other: ModInt) = div(other.int)
    operator fun div(other: Int) = times(other.modInv(MODBASE))

    override fun toString() = int.toString()
}

inline class ModIntArray(val intArray: IntArray) {
    @Suppress("DEPRECATION")
    operator fun get(i: Int) = ModInt(intArray[i])
    operator fun set(i: Int, v: ModInt) { intArray[i] = v.int }
}
fun ModIntArray(capacity: Int) = ModIntArray(IntArray(capacity))
inline fun ModIntArray(capacity: Int, init: (Int) -> ModInt) = ModIntArray(capacity).apply {
    repeat(capacity) { this[it] = init(it) }
}

