private fun calculateAllPossible(n: Int, l: Int, r: Int): Int {
    val zeroOptions: Long = (r / 3 - (l - 1) / 3).toLong()
    val oneOptions = ((r + 2) / 3 + 1 - (l + 1) / 3 - 1).toLong()
    val twoOptions = ((r + 1) / 3 + 1 - (l) / 3 - 1).toLong()

    var zeroTotal: Long = 1L
    var oneTotal: Long = 0L
    var twoTotal: Long = 0L

    for (i in (0 until n)) {
        val nextOneTotal = zeroTotal * oneOptions + twoTotal * twoOptions + oneTotal * zeroOptions
        val nextTwoTotal = oneTotal * oneOptions + twoTotal * zeroOptions + zeroTotal * twoOptions
        val nextZeroTotal = oneTotal * twoOptions + twoTotal * oneOptions + zeroTotal * zeroOptions

        oneTotal = nextOneTotal
        twoTotal = nextTwoTotal
        zeroTotal = nextZeroTotal

        oneTotal %= MODULO
        twoTotal %= MODULO
        zeroTotal %= MODULO
    }
//    val numbers = r - l + 1
//    return ((pow(numbers, n - 1).toLong() * countThreeDividers(l, r).toLong()) % MODULO).toInt()
    return zeroTotal.toInt()
}

private fun calculateTwoNumbers(n: Int, l: Int, r: Int): Int {
    return when {
        n == 1 -> if (r % 3 == 0 || l % 3 == 0) 1 else 0
        n > 1 -> pow(2, n - 2)
        else -> throw Exception("Impossible")
    }
}

private fun calculateOneNumber(n: Int, l: Int): Int {
    return when {
        l % 3 == 0 -> 1
        n % 3 == 0 -> 1
        else -> 0
    }
}

private fun countThreeDividers(l: Int, r: Int): Int {
    val size = r - l + 1
    return when (size % 3) {
        0 -> size / 3
        1 -> size / 3 + (if (r % 3 == 0) 1 else 0)
        2 -> size / 3 + (if (l % 3 == 0) 1 else 0) + (if ((r - 1) % 3 == 0) 1 else 0)
        else -> throw Exception("Impossible")
    }
}

private fun pow(value: Int, power: Int): Int {
    var result = 1L
    for (i in (0L until power.toLong())) {
        result = (result * value) % MODULO
    }
    return result.toInt()
}

