/**
 * Returns a new array of the modular inverses of each value in the original array. All values must be non-zero.
 * The values of the original array will not be changed. Takes O(3n + log(M)) multiplications vs O(n log(M)).
 */
fun ModIntArray.inverseOfEach(): ModIntArray {
    if(isEmpty()) return this
    var acc = ModInt(1)
    val res = ModIntArray(size) { i ->
        acc *= this[i]
        acc
    }
    acc = acc.inv_unmemoized()
    for(i in lastIndex downTo 1) {
        res[i] = acc * res[i-1]
        acc *= this[i]
    }
    res[0] = acc

    return res
}

// creates an array where res[i] == gen(i).inverse() . Any zeros the generator produces will be changed to 1.
inline fun modInvArray(size: Int, gen: (Int) -> ModInt) = ModIntArray(size) {
    val a = gen(it)
    if(a.int != 0) a else ModInt(1)
}.inverseOfEach()



