fun solve(ir : InputReader, pw : PrintWriter) {

    val r1 : Int = ir.nextInt()
    val c1 : Int = ir.nextInt()
    val r2 : Int = ir.nextInt()
    val c2 : Int = ir.nextInt()
    val dis1 : Int = Math.abs(r1 - r2)
    val dis2 : Int = Math.abs(c1 - c2)
    val rest : Int = Math.abs(dis1 - dis2)

    if (r1 != r2 && c1 != c2)
        pw.print("2 ")
    else if (r1 != r2 || c1 != c2)
        pw.print("1 ")
    else
        pw.print("0 ")

    if (dis1 % 2 == dis2 % 2) {
        when {
            dis1 != dis2 -> pw.print("2 ")
            else -> pw.print("1 ")
        }
    } else
        pw.print("0 ")

    if (dis1 >= dis2)
        pw.print("${dis2 + rest}")
    else
        pw.print("${dis1 + rest}")

}

class InputReader(stream: InputStream) {
    private val reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer? = null

    init {
        tokenizer = null
    }

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens())
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        return tokenizer!!.nextToken()
    }

    fun nextLine(): String? {
        val fullLine: String
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                fullLine = reader.readLine()
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

            return fullLine
        }
        return null
    }

    fun toArray(): Array<String> {
        return nextLine()!!.split(" ".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

}

