fun IntArray.shakeForMeBaby(): Int {
    var left = 1
    var right = min(this[1], this[2])
    while (left <= right) {
        val mid = (left + right) / 2
        when {
            this[1] / mid + this[2] / mid < this[0] -> right = mid - 1
            else -> left = mid + 1
        }
    }
    return left - 1
}

