fun initIO(isLocal: Boolean) = when (isLocal) {
    true -> InputReader(File("input.txt").inputStream())
    false -> InputReader(System.`in`)
}

class InputReader(inputStream: InputStream) {
    val reader = inputStream.bufferedReader()
    var tokenizer = StringTokenizer("")

    fun nextLine(): String = when {
        tokenizer.hasMoreTokens() -> tokenizer.nextToken("")!!
        else -> reader.readLine()!!
    }

    fun nextWord(): String {
        while (!tokenizer.hasMoreTokens()) {
            tokenizer = StringTokenizer(nextLine())
        }
        return tokenizer.nextToken()!!
    }

    fun nextInt() = nextWord().toInt()

    fun nextLong() = nextWord().toLong()
}

