data class Vector(val x: Int, val y: Int){

    fun sum(that: Vector): Vector =
            Vector(x + that.x, y + that.y)

    fun mult(n: Int): Vector =
            Vector(x * n, y * n)

    fun isProportional(that: Vector): Boolean =
            x % that.x == 0 && y % that.y == 0

}

