fun Long.mod() : Long {
    var result = this % MODULO
    if (result < 0) result += MODULO
    return result
}

infix fun Long.add(other : Long) = (this + other).mod()
infix fun Long.sub(other : Long) = this add -other.mod()
infix fun Long.mult(other : Long) = (this.mod() * other.mod()).mod()

fun Long.even() = (this and 1L) == 0L
fun Long.odd() = !even()

fun Int.even() = (this and 1) == 0
