class InputReader(val stream: InputStream) {
    val buf = ByteArray(1024)
    var curChar: Int = 0
    var numChars: Int = 0

    fun read(): Int {
        if (numChars == -1)
            throw InputMismatchException()
        if (curChar >= numChars) {
            curChar = 0
            try {
                numChars = stream.read(buf)
            } catch (e: IOException) {
                throw InputMismatchException()
            }
            if (numChars <= 0)
                return -1
        }
        return buf[curChar++].toInt()
    }

    fun nextInt(): Int {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        var sgn = 1
        if (c == 45) {
            sgn = -1
            c = read()
        }
        var res = 0
        do {
            if (c < 48 || c > 57)
                throw InputMismatchException()
            res *= 10
            res += c and 15
            c = read()
        } while (!isSpaceChar(c))
        return res * sgn
    }

    fun nextLong(): Long {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        var sgn = 1
        if (c == 45) {
            sgn = -1
            c = read()
        }
        var res: Long = 0
        do {
            if (c < 48 || c > 57)
                throw InputMismatchException()
            res *= 10
            res += c and 15
            c = read()
        } while (!isSpaceChar(c))
        return res * sgn
    }

    fun nextString(): String {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        val res = StringBuilder()
        do {
            res.appendCodePoint(c)
            c = read()
        } while (!isSpaceChar(c))
        return res.toString()
    }

    fun isSpaceChar(c: Int): Boolean {
        return c == 32 || c == 10 || c == 13 || c == 9 || c == -1
    }
}

class OutputWriter(val stream: OutputStream) {
    val buf = ByteArray(65536)
    var curPos: Int = 0

    fun write(c: Char) {
        if (buf.size - curPos < 1) flush()
        buf[curPos++] = c.toByte()
    }

    fun write(s: String) {
        if (buf.size - curPos < s.length) flush()
        var idx = 0
        var remaining = s.length
        while (remaining > buf.size) {
            while (curPos < buf.size) buf[curPos++] = s[idx++].toByte()
            flush()
            remaining -= buf.size
        }
        while (idx < s.length) buf[curPos++] = s[idx++].toByte()
    }

    fun flush() {
        stream.write(buf, 0, curPos)
        curPos = 0
    }
}

fun countDivs(n: Int): Int {
    var res = 0
    var i = 2
    while (i * i <= n) {
        if (n % i == 0) ++res
        ++i
    }
    --i
    return if (i * i == n) res * 2 + 1 else res * 2 + 2
}

fun main(args: Array<String>) {
    if (args.isNotEmpty()) System.setIn(FileInputStream(args[0]))
    val ir = InputReader(System.`in`)
    val ow = OutputWriter(System.out)

    val a = ir.nextInt()
    val b = ir.nextInt()
    val c = ir.nextInt()
    val arr = IntArray(1000001)
    var answer = 0
    for (i in 1 .. a) {
        for (j in 1 .. b) {
            for (k in 1 .. c) {
                val key = i * j * k
                if (arr[key] == 0) {
                    arr[key] = countDivs(key)
                }
                answer += arr[key]
            }
        }
    }
    ow.write("$answer\n")
    ow.flush()
}

