fun count(nine: Long, n: Long): Long {
    val a = 1L
    val b = n

    val c = nine - n
    val d = nine - 1

    if (b < c) return 0
    if (d < a) return 0

    return Math.min(b, d) - Math.max(a, c) + 1
}


