fun main() {
    val (n, m) = readInts()

    // Kx[y] = # of arrays of x 1s and y -1s such that max prefix sum = 0
    var K = ModIntArray(m+1) { ModInt(1) }
    // Dx[y] = answer for n=x and m=y
    var D = ModIntArray(m+1) { ModInt(0) }

    for(x in 1..n) {
        val Kx = ModIntArray(m+1)
        for(y in x..m) {
            Kx[y] = K[y] + Kx[y-1]
        }

        val Dx = ModIntArray(m+1)
        Dx[0] = ModInt(x)
        for(y in 1..m) {
            val nn = x + y - 1
            Dx[y] = C(nn, y) + D[y] + Dx[y-1] - C(nn, x) + Kx[y-1]
        }

        K = Kx
        D = Dx
    }

    val ans = D[m]

    println(ans)
}

infix fun Int.umod(base: Int) =
    (this % base).let { if(it >= 0) it else it + base }

infix fun Long.umod(base: Long) =
    (this % base).let { if(it >= 0) it else it + base }

infix fun Long.umod(base: Int) =
    (this % base).let { if(it >= 0) it else it + base }

fun Int.mulMod(other: Int, mod: Int) = (toLong() * other).umod(mod).toInt()

fun Int.powMod(exponent: Int, mod: Int): Int {
    var res = 1L
    var e = exponent
    var b = umod(mod).toLong()

    while(e > 0) {
        if(e and 1 == 1) {
            res = res * b % mod
        }
        e = e shr 1
        b = b * b % mod
    }
    return res.toInt()
