    val (n, m) = readInts()

    // Kx[y] = # of arrays of x 1s and y -1s such that max prefix sum = 0
    var K = ModIntArray(m) { ModInt(1) }
    // Dx[y] = answer for n=x and m=y
    var D = ModIntArray(m+1)

    for(x in 1..n) {
        val Kx = ModIntArray(m)
        for(y in x until m) {
            Kx[y] = K[y] + Kx[y-1]
        }

        val Dx = ModIntArray(m+1)
        Dx[0] = ModInt(x)
        for(y in 1..m) {
            val nn = x + y - 1
            Dx[y] = C(nn, y) + D[y] + Dx[y-1] - C(nn, x) + Kx[y-1]
        }

        K = Kx
        D = Dx
    }

    val ans = D[m]

    println(ans)
}

