fun distinct(x:Int):Boolean{
    var firstX:Int=x%10
    var secondX:Int=(x%100)/10
    var thirdX:Int=(x%1000)/100
    var fourthX:Int=x/1000
    if(firstX == secondX || firstX == thirdX || firstX == fourthX
        || secondX == thirdX || secondX == fourthX || thirdX == fourthX){
        return false
    }
    return true
}

fun check(num: Int):Boolean{
    for(i:Int in 0 until n){//bulls the same pos
        if(Bulls(arr[i].x , num) != arr[i].y ||
                Cows(arr[i].x , num) != arr[i].z){
            return false
        }
    }
    return true
}
fun Bulls(x:Int , y:Int):Int{
    var ans:Int=0
    if(x%10 == y%10){
        ans++
    }
    if ((x%100)/10 == (y%100)/10){
        ans++
    }
    if ((x%1000)/100 == (y%1000)/100){
        ans++
    }
    if(x/1000 == y/1000){
        ans++
    }
    return ans
}
fun Cows(x:Int , y:Int):Int{
    var ans=0
    var firstX:Int=x%10
    var secondX:Int=(x%100)/10
    var thirdX:Int=(x%1000)/100
    var fourthX:Int=x/1000

    var firstY:Int=y%10
    var secondY:Int=(y%100)/10
    var thirdY:Int=(y%1000)/100
    var fourthY:Int=y/1000
    if(firstX == secondY || firstX == thirdY || firstX == fourthY){
        ans++
    }
    if(secondX == firstY || secondX == thirdY || secondX == fourthY){
        ans++
    }
