fun gcd(a: Int, b: Int): Int {
    if (a == 0)
        return b
    return gcd(b % a, a)
}

fun solve(cin: FastReader, out: PrintWriter) {
    var la = cin.nextInt()
    var ra = cin.nextInt()
    var ta = cin.nextInt()
    var lb = cin.nextInt()
    var rb = cin.nextInt()
    var tb = cin.nextInt()
    var g = gcd(ta, tb)
    rb -= la
    ra -= la
    lb -= la
    la -= la
    if (lb < 0) {
        lb += tb
        rb += tb
    }

    var ans = 0
    for (d in listOf(lb / g, lb / g + 1, lb / g - 1)) {
        val llb = lb - g * d
        val rrb = rb - g * d

        if (llb <= ra && la <= rrb)
            ans = Math.max(ans, Math.min(ra, rrb) - Math.max(la, llb) + 1)
    }

    out.print(ans)
}




