class TaskB {
    fun solve(inp: InputReader, out: PrintWriter) {
        val t = inp.nextInt()
        for (i in 1..t) {
            val a = inp.nextLong()
            val b = inp.nextLong()
            val d1 = a - b
            val d2 = a + b
            if (d1 == 1L) {
                if (isPrime(d2))
                    out.println("YES")
                else
                    out.println("NO")
            } else
                out.println("NO")
        }
    }

    private fun isPrime(x: Long): Boolean {
        if (x == 1L)
            return false
        var d = 2L
        while (d * d <= x) {
            if (x % d == 0L)
                return false
            d++
        }
        return true
    }
}

class InputReader(stream: InputStream) {
    private var reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer? = null

    init {
        tokenizer = null
    }

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }
        }
        return tokenizer!!.nextToken()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextLong(): Long {
        return next().toLong()
    }
}

