fun solve() {
    var n = readInt()
    var s = read()
    var f = false
    var mx = 0
    var cnt = 0
    var i = 0
    while(i < n){
        if (s[i] == '('){
            f = true
        }
        if (s[i] == ')'){
            f = false
        }
        if (s[i].isLetter()){
            var j = i
            while(j < n && s[j].isLetter()){
                j++
            }
            if (f){
                cnt++
            } else {
                mx = max(mx, j - i)
            }
            i = j - 1
        }
        i++
    }
    print("${mx} ${cnt}")

}

