    var maxOutside = 0
    var count = 0
    for (c in readLine()!!)
        when (c) {
            '_' -> {
                if (insideParenthesis && count > 0) countInside++
                count = 0
            }
            '(' -> {
                insideParenthesis = true
                count = 0
            }
            ')' -> {
                if (count > 0) countInside++
                insideParenthesis = false
                count = 0
            }
            else -> {
                count++
                if (!insideParenthesis) maxOutside = max(maxOutside, count)
            }
        }
    print("$maxOutside $countInside")
}

