class IndexedWeightedGraph(private val n : Int, private val edges: TotalEdgeArray) {

    private val graph : Graph

    private fun buildGraphForEdges(
            edgeFilter : (index : Int, edge : TotalEdge) -> Boolean = { _, _ -> true }
    ) : Graph {
        val builder = GraphBuilder()
        edges
            .forEachIndexed { index, edge ->
                if (edgeFilter(index, edge)) {
                    val (first, second, _ ) = edge

                    builder.addDirectedEdge(first, index)
                    builder.addDirectedEdge(second, index)
                }
            }

        return builder.build(n)
    }

    init {
        graph = buildGraphForEdges()
    }

    var root : Int = -1
    lateinit var inTree : BooleanArray
    lateinit var tree : Graph

    fun kruskalTree(root : Int) : Long {
        this.root = root

        inTree = BooleanArray(edges.size) { false }

        val dsu = DSU(n)

        edges
            .mapIndexed { index, (_, _, w) -> index to w }
            .sortedBy { it.second }
            .forEach {
                val edge = edges[it.first]
                inTree[it.first] = dsu.union(edge.first, edge.second)
            }

        tree = buildGraphForEdges { index, _ -> inTree[index] }

        return edges
                .mapIndexed { index, (_, _, w)  -> if (inTree[index]) w.toLong() else 0L }
                .sum()
    }

    private fun to(from : Int, index : Int) : Int {
        val edge = edges[index]
        return if (from == edge.first) edge.second else edge.first
    }

    fun buildLca() {
        calculateTimes()
        calculateParents()
        calculatePathInfo()
    }

    lateinit var timesIn : IntArray
    lateinit var timesOut : IntArray
    private var time = -1

    private fun calculateTimes() {
        timesIn = IntArray(n) { -1 }
        timesOut = IntArray(n) { -1 }
        this.time = 0

        timeDfs(root)
    }

    private fun timeDfs(from : Int, parent : Int = -1) {
        timesIn[from] = time++

        for (index in tree[from]) {
            val to = to(from, index)
            if (to == parent) continue

            timeDfs(to, from)
        }

        timesOut[from] = time++
    }

    lateinit var parents : Array<IntArray>
    private val maxBit = 19

    private fun calculateParents() {
        parents = Array(maxBit) { IntArray(n) { -1 } }

        parentDfs(root, root)

        for (bit in 0 until maxBit - 1) {
            for (v in 0 until n) {
                val parent = parents[bit][v]
                parents[bit + 1][v] = parents[bit][parent]
            }
        }
    }

    private fun parentDfs(from : Int, parent : Int = -1) {
        parents[0][from] = parent

        for (index in tree[from]) {
            val to = to(from, index)
            if (to == parent) continue

            parentDfs(to, from)
        }
    }

    lateinit var maxEdges : Array<IntArray>

    private fun calculatePathInfo() {
        maxEdges = Array(maxBit) { IntArray(n) { -1 } }

        for (v in 0 until n){
            for (index in tree[v]) {
                val to = to(v, index)
                if (to == parents[0][v]) continue

                maxEdges[0][to] = edges[index].third
            }
        }

        for (bit in 0 until maxBit - 1) {
            for (v in 0 until n) {
                val parent = parents[bit][v]
                maxEdges[bit + 1][v] = max(
                        maxEdges[bit][v],
                        maxEdges[bit][parent]
                )
            }
        }
    }

    fun getOnPath(a : Int, b : Int) : Int {
        var answer = Int.MIN_VALUE

        answer = max(answer, getOnLcaPath(a, b))
        answer = max(answer, getOnLcaPath(b, a))

        return answer
    }

    private fun getOnLcaPath(start : Int, other : Int) : Int {
        var answer = Int.MIN_VALUE

        if (timesIn[start] <= timesIn[other] && timesOut[other] <= timesOut[start]) {
            return answer
        }

        var v = start
        for (bit in maxBit - 1 downTo 0) {
            val parent = parents[bit][v]
            if (timesIn[parent] > timesIn[other] || timesOut[other] > timesOut[parent]) {
                answer = max(answer, maxEdges[bit][v])
                v = parent
            }
        }

        answer = max(answer, maxEdges[0][v])

        return answer
    }
}

