class GraphBuilder {

    private val froms = ArrayList<Int>()
    private val tos = ArrayList<Int>()
    private val weights = ArrayList<Int>()

    fun addEdge(from : Int, to : Int, weight : Int = 1) {
        addDirectedEdge(from, to, weight)
        addDirectedEdge(to, from, weight)
    }

    fun addDirectedEdge(from : Int, to : Int, weight : Int = 1) {
        froms.add(from)
        tos.add(to)
        weights.add(weight)
    }

    private fun calculateFromSizes(n : Int) : IntArray {
        val sizes = IntArray(n) { 0 }
        froms.forEach { ++sizes[it] }
        return sizes
    }

    fun build(n : Int) : Graph {
        val sizes = calculateFromSizes(n)

        val graph = Graph(n) { IntArray(sizes[it]) { 0 } }

        for (i in 0 until n) {
            sizes[i] = 0
        }

        for (i in 0 until froms.size) {
            val from = froms[i]
            val to = tos[i]

            graph[from][sizes[from]++] = to
        }

        return graph
    }

    fun buildWeighted(n : Int) : WeightedGraph {
        val sizes = calculateFromSizes(n)

        val graph = WeightedGraph(n) { EdgeArray(sizes[it]) { -1 to 0 } }

        for (i in 0 until n) {
            sizes[i] = 0
        }

        for (i in 0 until froms.size) {
            val from = froms[i]
            val to = tos[i]
            val weight = weights[i]

            graph[from][sizes[from]++] = to to weight
        }

        return graph
    }
}

