fun regime(l: Long) = l * (l-1) / 2

fun LongRange.binarySearchBy(goldilocks: (Long) -> Int): BinarySearchResult<Long> {
    var low = start
    var high = endInclusive

    while (low <= high) {
        val mid = low / 2 + high / 2 + (low % 2 + high % 2) / 2
        val cmp = goldilocks(mid)

        if (cmp < 0)
            low = mid + 1
        else if (cmp > 0)
            high = mid - 1
        else
            return BinarySearchResult(mid, true) // key found
    }
    return BinarySearchResult(low, false)  // key not found
}
data class BinarySearchResult<out T>(val value: T, val exactFound: Boolean)

