import java.lang.Long.min

fun main() {
    val count = readLine()!!.toInt()
    val dp = Array(count) { i -> LongArray(count - i) { Long.MAX_VALUE / 3 } }
    dp[0].fill(0)
    dp[1].fill(0)
    for (left in 0 until count - 2) {
        dp[2][left] = 1L * (left + 1) * (left + 2) * (left + 3)
    }

    for (length in 3 until count) {
        for (left in 0 until count - length) {
            val right = left + length
            val mult = 1L * (left + 1) * (right + 1)
            for (midPoint in left + 1 until right) {
                dp[length][left] = min(dp[length][left],
                        dp[midPoint - left][left] + dp[right - midPoint][midPoint] + mult * (midPoint + 1))
            }
        }
    }
    println(dp[count - 1][0])
}

