object programkt {
  fun S(n0: Long): Long {
    var res = 0L
    var n = n0
    while (n > 0) {
      res += n % 10
      n = n / 10
    }
    return res
  }

  fun solveDumb(n: Long) =
    LongRange(0, n)
      .map { it -> Pair(S(it) + S(n - it), it) }
      .maxWith(
        object : Comparator<Pair<Long, Long>> {
          override fun compare(o1: Pair<Long, Long>, o2: Pair<Long, Long>): Int {
            if (o1.first == o2.first)
              return o1.second.compareTo(o2.second)
            else
              return o1.first.compareTo(o2.first)
          }
        }
      )!!

  fun solve(n: Long): Long {
    if (n < 10)
      return n
    else {
      var n10 = 1L
      while (n10 * 10 <= n) {
        n10 *= 10
      }
      val a = n / n10 * n10 - 1
      val b = n - a
      return S(a) + S(b)
    }
  }

  @JvmStatic fun main(args: Array<String>) {
    if (args.size == 1)
      System.setIn(FileInputStream(args[0]))
    //val sc = Scanner(System.`in`)

    LongRange(0, 100).forEach {
      //println("$it " + solveDumb(it))
      assert(solveDumb(it).first == solve(it))
    }

    println(solve(BigDecimal(readLine()).toLong()))
  }
}

