data class Point(val row: Int, val col: Int)

fun main() {
    val (n, m) = readSomeInts()

    fun neighbors(p: Point): List<Point> {
        val acc = mutableListOf<Point>()
        if (p.row > 0) {
            acc.add(Point(p.row - 1, p.col))
        }
        if (p.col > 0) {
            acc.add(Point(p.row, p.col - 1))
        }
        if (p.col < m - 1) {
            acc.add(Point(p.row, p.col + 1))
        }
        if (p.row < n - 1) {
            acc.add(Point(p.row + 1, p.col))
        }
        return acc
    }

    val field = mutableListOf<String>().apply {
        repeat(n) {
            val s = readString()
            this.add(s)
        }
    }.toList()

    fun hasWolf(p: Point) = field[p.row][p.col] == 'W'

    val wolfNotHangry = Array<BooleanArray>(n) { BooleanArray(m) }

    var countEatenPigs = 0
    for (i in 0 until n) {
        for (j in 0 until m) {
            if (field[i][j] == 'P') {
                val pigPt = Point(i, j)
                val anyWolf = neighbors(pigPt)
                        .firstOrNull { pt -> hasWolf(pt) && !wolfNotHangry[pt.row][pt.col] }
                if (anyWolf != null) {
                    wolfNotHangry[anyWolf.row][anyWolf.col] = true
                    countEatenPigs++
                }
            }
        }
    }
    println(countEatenPigs)
}

