class Table {
    private val matrix: List<List<Cell>>
    private val n: Int
    private val m: Int

    init {
        readLine()!!.split(" ")
            .map(String::toInt)
            .also {
                n = it[0]
                m = it[1]
            }

        matrix = (0 until n).map {
            readLine()!!.toCharArray().take(m)
                .map {
                    when (it) {
                        'P' -> PigCell()
                        'W' -> WolfeCell()
                        '.' -> EmptyCell
                        else -> throw IllegalArgumentException("Unknown animal")
                    }
                }
        }
    }

    fun forEachIndexed(action: (x: Int, y: Int, cell: Cell) -> Unit) {
        matrix.forEachIndexed { i, row ->
            row.forEachIndexed { j, cell -> action(i, j, cell) }
        }
    }

    private fun inRange(x: Int, y: Int) = x in 0 until n && y in 0 until m

    fun nearby(x: Int, y: Int, predicate: (Cell) -> Boolean): List<Cell> {
        return listOf(
            Pair(x - 1, y),  // left
            Pair(x + 1, y),  // right
            Pair(x, y - 1),  // top
            Pair(x, y + 1)   // bottom
        )
            .filter { (x, y) -> inRange(x, y) }
            .map { (x, y) -> matrix[x][y] }
            .filter(predicate)
    }
}

