class Solver(input: InputStream, output: OutputStream) {

    companion object {
        private const val MAX_N = (1e6 + 10).toInt()
        private const val INF = (1e9 + 7).toInt()
        private const val MOD = (1e9 + 7).toInt()
        private const val INF_F = 1e-6
    }

    private val reader = Reader(input)
    private val writer = Writer(output)

    fun solve() {
        val n = reader.nextInt()
        val a = reader.nextArrayInt(n)
        var ans = 0
        for (i in 1 until n) {
            when {
                a[i] == 2 && a[i - 1] == 3 || a[i] == 3 && a[i - 1] == 2 -> {
                    writer.println("Infinite")
                    return
                }
                a[i] == 1 -> ans += if (a[i - 1] == 2) 3 else 4
                a[i] == 3 -> ans += 4
                a[i] == 2 -> {
                    when {
                        i == 1 -> ans += 3
                        a[i - 2] == 2 -> ans += 3
                        a[i - 2] == 3 -> ans += 2
                    }
                }
            }
        }
        writer.println("Finite")
        writer.println(ans)
    }

    fun clear() {
        writer.close()
    }

    private fun IntArray.gcd(): Int {
        var g = first()
        forEach { g = gcd(g, it) }
        return g
    }

    private fun LongArray.gcd(): Long {
        var g = first()
        forEach { g = gcd(g, it) }
        return g
    }

    private fun gcd(a: Int, b: Int): Int {
        return if (b == 0) a else gcd(b, a % b)
    }

    private fun gcd(a: Long, b: Long): Long {
        return if (b == 0L) a else gcd(b, a % b)
    }
}

class Reader(input: InputStream) {
    private val reader = BufferedReader(InputStreamReader(BufferedInputStream(input)), 32768)
    private var tokenizer: StringTokenizer? = null

    fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }
        }
        return tokenizer!!.nextToken()
    }

    fun nextInt() = next().toInt()

    fun nextLong() = next().toLong()

    fun nextArrayInt(count: Int): IntArray {
        return nextArrayInt(0, count)
    }

    fun nextArrayInt(start: Int, count: Int): IntArray {
        val a = IntArray(start + count)
        for (i in start until start + count) {
            a[i] = nextInt()
        }
        return a
    }

    fun nextArrayLong(count: Int): LongArray {
        val a = LongArray(count)
        for (i in 0 until count) {
            a[i] = nextLong()
        }
        return a
    }
}

