fun IntRange.binarySearchBy(goldilocks: (Int) -> Int): BinarySearchResult<Int> {
    var low = start
    var high = endInclusive

    while (low <= high) {
        val mid = low.and(high) + low.xor(high).shr(1)
        val cmp = goldilocks(mid)

        when {
            cmp < 0 -> low = mid + 1
            cmp > 0 -> high = mid - 1
            else -> return BinarySearchResult(mid, true)
        }
    }
    return BinarySearchResult(low, false)
}
