    val fac: (Int) -> Long = {n -> var res = 1L; for (p in 1 .. n) res *= p; res}

    fun d(n: Int): Long {
        val i: Int
        var res = 0L

        for (i in 0 .. n) {
            val sign = {it: Int -> if (it % 2 == 0) 1 else -1}(i)
            res += sign * fac(n) / fac(i)
        }
        return res
    }

    fun c(n: Int, m: Int): Long {
        var p = 1L
        for (i in (n - m + 1) .. n) {
            p *= i
        }
        return p / fac(m)
    }

