private fun divisors(n: Int): List<Int> {
    val ds = mutableListOf<Int>()
    var i = 2
    while (i * i <= n) {
        if (n % i == 0) {
            ds.add(i)
            ds.add(n / i)
        }
        i++
    }
    return ds.toList()
}


private fun isPrime(n:Int) :Boolean {
    var isPrime = true;
    for (i in 2..sqrt(n.toFloat()).toInt())
        if (n%i==0) {isPrime=false; break}
    return isPrime
}

fun solution(ss: String): Boolean {
    val s = ss.filter { it!='0' }
    if (s.length==1) return false
    if (s.filter { it != '0' }.all { it==s.first() }) return true
    val ns = s.map { it.toInt() - '0'.toInt() }
    val sum = ns.sum()
    val r =
    when {
        isPrime(sum) -> false
        else -> {
            var canDivide = false
            var l = 0
            forloop@ for (i in divisors(sum)) {
                var b: Int
                whileloop@ while (l <= ns.lastIndex) {
                    canDivide=false
                    b=sum/i
                    while (b > 0 && l<=ns.lastIndex) b -= ns[l++]
                    if (b == 0) {
                        canDivide =  true
                        continue@whileloop
                    }
                    else {
                        l=0
                        canDivide = false
                        continue@forloop
                    }
                }

                if (canDivide) break
            }
            canDivide
        }
    }
    return r
}


