            if (index == number.lastIndex) return null
            var j = 1
            var maxIndex = index + j
            var maxDigit = number[maxIndex].toInt()
            repeat(remainingMoves - 1) {
                number.getOrNull(index + ++j)?.toInt()?.let { digit ->
                    if (digit > maxDigit) {
                        maxIndex = index + j
                        maxDigit = digit
                    }
                }
            }
            return if (number[maxIndex].toInt() > number[index].toInt()) maxIndex else null
        }

        while (index < number.length && remainingMoves > 0) {
            getNextMaxDigitIndex()?.let { nextMaxDigitIndex ->
                val maxDigit = number[nextMaxDigitIndex]
                number.deleteCharAt(nextMaxDigitIndex)
                number.insert(index, maxDigit)
                remainingMoves -= nextMaxDigitIndex - index
            }
            index++
        }
    }
