fun solveA(data: List<Int>): Int {
    val zeros = data.takeWhile { it == 0 }.size
    val ones = data.takeLastWhile { it == 1 }.size
    val middle = data.size - zeros - ones
    val maxMiddleCount = if (middle == 0) 0 else (0 until middle).map {
        var i = 0
        var sum = 0
        var countZeroes = i != it
        while (i < middle) {
            val isZero = data[i + zeros] == 0
            if (isZero == countZeroes) {
                sum++
            }
            if (sum == it) {
                countZeroes = false
            }
            i++
        }
        sum
    }.max()!!
    return zeros + ones + maxMiddleCount
}

