fun calculateBoxes(): Int {
    val map = sortedMapOf<Int, Int>()

    fun readPairOfIntegers() = readLine()!!.split(" ").let { Pair(it[0].toInt(), it[1].toInt()) }

    fun addToMap(key: Int, value: Int) {
        fun getValue(key: Int): Int {
            if (map[key] == null) {
                map[key] = 0
            }
            return map[key]!!
        }
        map[key] = value + getValue(key)
    }
    var matchesTaken = 0
    var (availableCapacity, containersCount) = readPairOfIntegers()
    repeat(containersCount) {
        val (boxesCount, boxCapacity) = readPairOfIntegers()
        addToMap(-boxCapacity, boxesCount)
    }
    map.entries.forEach { (boxCapacityNegative, boxesCount) ->
        val boxCapacity = -boxCapacityNegative
        if (boxesCount >= availableCapacity) {
            matchesTaken += availableCapacity * boxCapacity
            return matchesTaken
        } else {
            matchesTaken += boxesCount * boxCapacity
            availableCapacity -= boxesCount
        }
    }
    return matchesTaken
}

fun main() = println(calculateBoxes())

import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val (n, m) = br.readLine().split(" ").map { it.toInt() }
    val matches = List(m){br.readLine().split(" ").map { it.toInt() }}
        .sortedByDescending { it[1] }
    var cnt = 0
    var takenBoxes = 0
    var i = 0
    var full = false
    while (i < m && !full) {
        val (a, b) = matches[i]
        if (takenBoxes + a <= n) {
            cnt += a*b
            takenBoxes += a
            i++
        } else {
            cnt += (n - takenBoxes)*b
            full = true
        }
    }
    println(cnt)
}

