import java.util.*

data class Box(val a: Int = 0, val b: Int = 0) : Comparable<Box> {
    override fun compareTo(other: Box): Int {
        return this.b - other.b
    }
}

fun main(args: Array<String>) {
    var (n, m) = readLine()!!.split(' ').map {it.toInt()}
    val x = Array(m) {Box()}
    for (i in 0 until m) {
        val line = readLine()!!.split(' ').map {it.toInt()}
        x[i] = Box(line[0], line[1])
    }

    var sum = 0
    for (box in x.sortedDescending()) {
        val take = minOf(box.a, n)
        n -= take
        sum += take * box.b
    }
    println(sum)
}

