fun factor(x: Long, op: (p: Long, k: Int) -> Unit) {
    var rem = x
    var p = 2L
    while (p * p <= rem) {
        var k = 0
        while (rem % p == 0L) {
            rem /= p
            k++
        }
        if (k > 0) op(p, k)
        p++
    }
    if (rem > 1) op(rem, 1)
}

fun pp(n: Long, p: Long): Long {
    var ans = 0L
    var cur = p
    while (cur <= n) {
        ans += n / cur
        if (cur > (n + p - 1) / p) break
        cur *= p
    }
    return ans
}

