data class Position(
    val nextPriliv: Boolean,
    val value: Long
) {
    fun next(k: Long): Position {
        val nextValue = if (nextPriliv) value + 1 else value - 1
        return when (nextValue) {
            0L -> Position(true, 0)
            k -> Position(false, k)
            else -> Position(nextPriliv, nextValue)
        }
    }
}

fun main() {
    val reader = Scanner(System.`in`)
    val out = PrintWriter(BufferedOutputStream(System.`out`))

    val t = reader.nextInt()
    repeat(t) {
        val n = reader.nextInt() // Distance
        val k = reader.nextLong() // Priliv time
        val l = reader.nextLong() // Max depth
        val depths = LongArray(n) { reader.nextLong() }

        val possibilities = Array(n + 1) { mutableSetOf<Position>() }
        for (i in 0L until k) {
            possibilities[0].add(Position(true, i))
        }
        for (i in k downTo 1L) {
            possibilities[0].add(Position(false, i))
        }

        for (i in 0 until n) {
            possibilities[i].forEach { position ->
                var nextPosition = position.next(k)
                while (depths[i] + nextPosition.value <= l) {
                    possibilities[i + 1].add(nextPosition)
                    if (position == nextPosition) {
                        break
                    }
                    nextPosition = nextPosition.next(k)
                }
            }
        }
        if (possibilities[n].isNotEmpty()) {
            out.println("Yes")
        } else {
            out.println("No")
        }
    }

    out.flush()
}

