fun p(pos: Int, k: Int) =
    if (pos <= k) {
        pos
    } else {
        2 * k - pos
    }

fun maxWait(d: Int, cur: Int, k: Int, mx: Int): Int {
    var curD = d + p(cur, k)
    return if (cur < k) {
        mx - curD
    } else {
        2 * k - cur + mx - d
    }
}

