                            if (cur < k) {
                                can1 = false
                            } else {
                                val nextD = d[i + 1] + p((cur + 1) % (2 * k), k)
                                val needWait = nextD - mx
                                cur = (cur + needWait + 1) % (2 * k)
                            }
                        } else {
                            cur = (cur + 1) % (2 * k)
                        }
                    } else {
