class FactorialCache(size: Int, private val mod: Long) {
  private val list = LongArray(size + 1) { 0 }
  private var current = 1

  init {
    list[0] = 1
    list[1] = 1
  }

  fun get(n: Int): MLong {
    if (current < n) {
      for (i in (current + 1)..n) {
        list[i] = (i * list[i - 1]) % mod
      }
      current = n
    }
    return MLong(list[n])
  }
}

var MOD = 1_000_000_007L

@JvmInline
value class MLong(private val value: Long) {

  operator fun plus(other: MLong): MLong {
    return MLong((value + other.value) % MOD)
  }

  operator fun minus(other: MLong): MLong {
    var ret = (value - other.value) % MOD
    if (ret < 0) {
      ret += MOD
    }
    return MLong(ret)
  }

  operator fun times(other: MLong): MLong {
    return MLong((value * other.value) % MOD)
  }

  fun pow(power: Long): MLong {
    var ret = 1L
    var current = value
    var p = 0
    while (1L shl p < power) {
      if (power and (1L shl p) != 0L) {
        ret = (ret * current) % MOD
      }
      current = (current * current) % MOD
