import kotlin.math.min

class FactorialCache(size: Int, private val mod: Long) {
  private val list = LongArray(size + 1) { 0 }
  private var current = 1

  init {
    list[0] = 1
    list[1] = 1
  }

  fun get(n: Int): MLong {
    if (current < n) {
      for (i in (current + 1)..n) {
        list[i] = (i * list[i - 1]) % mod
      }
      current = n
    }
    return MLong(list[n])
  }
}

