private fun Char.diff(c: Char): Int {
  val a: MutableList<Int> = mutableListOf()
  a.addIfNotNegative(this - c)
  a.addIfNotNegative(c - this)
  a.addIfNotNegative(reverseDiff(c, this))
  a.addIfNotNegative(reverseDiff(this, c))
  return a.min()!!
}

private fun reverseDiff(c: Char, c1: Char) = ('Z' - c1) + (c - 'A') + 1

