class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val Xp = ni()
    val Yp = ni()
    val Xv = ni()
    val Yv = ni()

    var win = false
    val diagonal = min(Xv, Yv)
    for (i in 1 .. diagonal) {
      val x = Xv - i
      val y = Yv - i
      if (Xp >= x && Yp >= y) {
        val tp = Xp - x + Yp - y
        val tv = i
        win = win || tp <= tv
      }
    }

    for (i in 1 .. max(Xv, Yv) - diagonal) {
      val x = max(0, Xv - diagonal - i)
      val y = max(0, Yv - diagonal - i)
      if (Xp >= x && Yp >= y) {
        val tp = Xp - x + Yp - y
        val tv = i + diagonal
        win = win || tp <= tv
      }
    }

    if (win) out.println("Polycarp")
    else out.println("Vasiliy")
  }













































