                '?' -> {
                    var j = i
                    while (j < s.length && s[i] == s[j])
                        ++j

                    if (j - i >= 2)
                        ok = true
                    else {
                        var lch = if (i > 0) s[i - 1] else '\u0000'
                        var rch = if (j < s.length) s[j] else '\u0000'
                        if (lch == rch || lch == '\u0000' || rch == '\u0000')
                            ok = true
                    }
                    i = j
                }
                else -> {
                    if (i < s.length - 1 && s[i] == s[i + 1]) {
                        ok = false
                        break@mainloop
                    } else
                        ++i
                }
            }
        }

        println(if (ok) "Yes" else "No")
