inline fun findMin(mn: Long, mx: Long, f: (Long) -> Boolean): Long {
  var low = mn - 1
  var high = mx
  while(high - low > 1) {
    val m = (low + high) / 2
    if (f(m)) high = m
    else low = m
  }
  return high
}
