fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
//    val startTime = System.nanoTime()

    val numCases = 1//readInt()

    case@ for(case in 1..numCases) {
        //    print("Case #$case: ")

        val n = readInt()
        MOD = readInt()

//        val C = ModIntArray(n+1)
//        C[n]++
//        for(i in 1..n) {
//            for(j in n-i until n) C[j] += C[j+1]
//        }

        var ans = ModInt(0)
        val P = ModIntArray(n+1)
        P[0]++
        for(i in 0 until n) P[i+1] = P[i] * (n - i)

        var D = OffsetModIntArray(0, 0)
        D[0]++
        for(i in 2..n) {
            for(j in 0 until D.arr.lastIndex) D.arr[j+1] += D.arr[j]
            var acc = ModInt(0)
            for(j in 1 until i) acc += D.getPinned(-j-1) * (i - j)

            ans += acc * P[n-i]

            acc = ModInt(0)
            val Di = OffsetModIntArray(D.firstIndex - i, D.lastIndex + i)
            for(j in Di.firstIndex .. Di.lastIndex) {
                acc += D.getPinned(j + i - 1) - D.getPinned(j - 1)
                acc -= D.getPinned(j - 1) - D.getPinned(j - i - 1)
                Di[j] = acc
            }
            D = Di
        }

        println(ans.int)
    }

//    iprintln("Time: ${(System.nanoTime() - startTime) / 1000000} ms")
}

fun OffsetModIntArray.getPinned(i: Int) = if (i < firstIndex) ModInt(0) else get(min(i, lastIndex))

class OffsetModIntArray(val firstIndex: Int, val lastIndex: Int) {
    constructor(indices: IntRange): this(indices.first, indices.last)
    inline val indices get() = firstIndex .. lastIndex
    val arr = ModIntArray(lastIndex - firstIndex + 1)
    val size get() = arr.size

    operator fun get(i: Int) = arr[i - firstIndex]
    operator fun set(i: Int, v: ModInt) { arr[i - firstIndex] = v }
    fun last() = arr.last()
}

var MOD = 998244353

infix fun Int.modulo(mod: Int): Int = (this % mod).let { (it shr Int.SIZE_BITS - 1 and mod) + it }
infix fun Long.modulo(mod: Long) = (this % mod).let { (it shr Long.SIZE_BITS - 1 and mod) + it }
infix fun Long.modulo(mod: Int) = modulo(mod.toLong()).toInt()

fun Int.mulMod(other: Int, mod: Int) = toLong() * other modulo mod

fun Int.powMod(exponent: Long, mod: Int): Int {
    if(exponent < 0) error("Inverse not implemented")
    var res = 1L
    var e = exponent
    var b = modulo(mod).toLong()

    while(e > 0) {
        if(e and 1 == 1L) {
            res = res * b % mod
        }
        e = e shr 1
        b = b * b % mod
    }
    return res.toInt()
}
fun Int.powMod(exponent: Int, mod: Int) = powMod(exponent.toLong(), mod)
fun Int.modPowArray(n: Int, mod: Int): IntArray {
    val res = IntArray(n+1)
    res[0] = 1
    for(i in 1..n) res[i] = mulMod(res[i-1], mod)
    return res
}

