class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val cnt1 = nl()
    val cnt2 = nl()
    val X = nl()
    val Y = nl()

    val MAX = if (isDebug) 10 else Long.MAX_VALUE / 2 // 2e18ぐらいでok
    val ans = findMin(1L, MAX) { a ->
      val x = a / X
      val y = a / Y
      val xy = a / (X * Y)
      val notX = a - x
      val notY = a - y
      val notXy = a - (x + y - xy)
      val need1 = max(0, cnt1 - notX + notXy)
      val need2 = max(0, cnt2 - notY + notXy)
      debug{"$a $notX $notY $notXy $need1 $need2"}
      notXy >= need1 + need2
    }
    out.print(ans)
  }

  /**
   * [l, r]
   */
  fun findMin(l: Long, r: Long, f: (Long) -> Boolean): Long {
    // (l, h]
    var low = l - 1
    var high = r
    while(high - low > 1) {
      val m = (low + high) / 2
      if (f(m)) high = m
      else low = m
    }
    return high
  }












































  private val isDebug = try {
    // なんか本番でエラーでる
