import java.io.BufferedReader
import java.io.BufferedWriter

class ProblemE {
    private fun BufferedReader.readInt(): Int = this.readLine().toInt()
    private fun BufferedReader.readIntArray(delimiter: String = " ") =
        this.readLine().split(delimiter).map { it.toInt() }.toIntArray()

    private fun BufferedWriter.writeLine(s: String) {
        this.write(s)
        this.newLine()
    }

    private fun solveTest(input: BufferedReader, output: BufferedWriter) {
        val (n, m) = input.readIntArray()

        /***
         * x^(i*j) where 1 <=i <= log_x(k), 1 <= j <= m
         *               1 <= i <= 20, 1 <= j <= 1e6
         *
         */
        val numDistinctPowers = IntArray(22)
        var numUnique = 0
        val visited = BooleanArray(22*(m +1))
        for(i in 1 until numDistinctPowers.size) {
            for(j in 1..m) {
                if(!visited[i*j]) {
                    visited[i*j] = true
                    numUnique+=1
                }
            }
            numDistinctPowers[i] = numUnique
        }
        val isAPower = BooleanArray(n +1)
        var numDistinct = 1L
        for(x in 2..n) {
            if(!isAPower[x]) {
                var powerCount = 0
                var j = x.toLong()
                while(j <= n) {
                    isAPower[j.toInt()] = true
                    powerCount += 1
                    j *= x
                }
                numDistinct+= numDistinctPowers[powerCount]
            }
        }
        output.writeLine(numDistinct.toString())
    }

    fun solve(input: BufferedReader, output: BufferedWriter) {
        solveTest(input, output)
        input.close()
        output.close()
    }

}

fun main() {
    val solution = ProblemE()
    solution.solve(System.`in`.bufferedReader(), System.out.bufferedWriter())
}

