class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val S = ns().map{it-'0'}
    val N = S.size
    val M = ni()
    val cntDigit = IntArray(10)
    for (i in 0 until S.size) {
      cntDigit[S[i]]++
    }
    val coef = IntArray(11)
    coef[0] = 1
    for (i in 0 until 10) {
      coef[i + 1] = coef[i] * (1 + cntDigit[i])
    }
    debug(coef)
    var best = Array(coef.last()){LongArray(M)}
    var next = Array(coef.last()){LongArray(M)}
    best[0][0] = 1

    val map = IntArray(10_000) // 100 * 10 + 100 しかいかないけどたくさんつくっとく
    for (i in 0 until map.size) {
      map[i] = i % M
    }

    var pow10 = 1
    for (i in N - 1 downTo 0) {
      for (s in 0 until coef.last()) {
        for (d in 0 until 10) {
          if (i == 0 && d == 0) continue
          if ((s + coef[d]) / coef[d + 1] > s / coef[d + 1]) continue
          val ns = s + coef[d]
          for (m in 0 until M) {
            if (best[s][m] == 0L) continue
            val nm = map[m + pow10 * d]
//            debug{"s:$s m:$m d:$d ns:$ns nm:$nm"}
            next[ns][nm] += best[s][m]
          }
        }
      }
      debug{"DP($i)"}
      debugDim(next)
      val t = best
      best = next
      next = t

      pow10 = (pow10 * 10) % M
    }
    out.println(best[coef.last() - 1][0])
  }













































