        val endLoop = sqrt(this.toDouble()).toLong()
        for (i in 1L..endLoop) {
            if (this % i == 0L) {
                output.add(i)
                output.add(this / i)
            }
        }
        return output
    }

    val n = readLong()
    val factors = n.factors().toList().sorted()
    print(1 + (n - factors[1]) / 2)
}

