fun findTargetIndex(step: Long, size: Long, targetIndex: Long): Long{
    if(size == 1L) {
        return 1L
    }
    val next = size / 2

    if(next == targetIndex) {
        return step
    }
    if(targetIndex > next) {
        return findTargetIndex(step - 1, next, targetIndex - next - 1)
    }
        return findTargetIndex(step - 1, next, targetIndex)
}

fun getArrSize(step: Long): Long { 
    if(step <= 1L) {
        return 1
    }
    return (2 * getArrSize(step - 1)) + 1
}

