fun nearest(m: Long): Long{
    if(m==0L)
        return 0
    val temp = sqrt((2*m).toDouble()).toLong()
    for(i in -3..3){
        if(((temp+i)*(temp+i-1) < 2*m) && ((temp+i+1)*(temp+i) >= 2*m)){
            return temp+i+1
        }
    }
    return -1
}

