fun canWriteInNumberOfDays(
    numberOfDays: Int,
    numberOfCups: Int,
    targetNumberOfPages: Int,
    caffeine: Array<Long> // Sorted by descending
): Boolean {
    val maxNumberOfPages = calculateMaxNumberOfPages(numberOfDays, numberOfCups, caffeine)
    return maxNumberOfPages >= targetNumberOfPages
}

fun calculateMaxNumberOfPages(
    numberOfDays: Int,
    numberOfCups: Int,
    caffeine: Array<Long>
): Long {
    var orderOfCup = 0L
    var numberOfPages = 0L
    for (i in 0 until numberOfCups) {
        numberOfPages += maxOf(caffeine[i] - orderOfCup, 0L)
        if (i % numberOfDays == numberOfDays - 1) ++orderOfCup
    }
    return numberOfPages
}

