fun check(a: Array<Int>, m: Int, d: Int): Boolean {
    var sum = 0
    for (i in 0 until a.size) {
        val debuff = i / d
        if (a[i] <= debuff)
            break
        sum += a[i] - debuff
    }
    return sum >= m
}

