  return places
}

fun solve(input: InputReader, output: PrintWriter) {
  val p = input.nextInt()
  val x = input.nextInt()
  val y = input.nextInt()

  var losed = x
  while (losed >= y) {
    if (winPlaces(losed).contains(p)) {
      output.print(0)
      return
    }
    losed -= 50
  }


  var successfulBreaks = 1
  while (true) {
    val noFails = x + successfulBreaks * 100
    val oneFail = x + successfulBreaks * 100 - 50
    if (winPlaces(noFails).contains(p) || winPlaces(oneFail).contains(p)) {
      output.print(successfulBreaks)
      return
    }
    successfulBreaks += 1
  }
}

