class Data {
    private val rd: BufferedReader
    private var tok: StringTokenizer = StringTokenizer("")
    private val wr: PrintWriter

    init {
        rd = BufferedReader(InputStreamReader(System.`in`))
        wr = PrintWriter(System.out)
    }

    fun readToken(): String {
        while (!tok.hasMoreTokens()) {
            tok = StringTokenizer(rd.readLine())
        }
        return tok.nextToken()
    }

    fun readInt(): Int {
        return readToken().toInt()
    }

    fun <T> writeln(value: T) {
        wr.println(value)
    }

    fun close() {
        rd.close()
        wr.close()
    }
}

/**
 * Solution to problem 740A (Alyona and copybooks)
 * http://codeforces.com/problemset/problem/740/A
 */
class Solution {
    val data: Data = Data()

    fun solve() {
        val n = data.readInt()

        val s = IntArray(4)
        s[0] = 0
        s[1] = data.readInt()
        s[2] = data.readInt()
        s[3] = data.readInt()

        val d = s.copyOf()

        var relaxing = true
        while (relaxing) {
            relaxing = false
            for (i in 0 .. d.size - 1) {
                for (j in 1 .. s.size - 1) {
                    val k = (i + j) % 4
                    if (d[k] > d[i] + s[j]) {
                        d[k] = d[i] + s[j]
                        relaxing = true
                    }
                }
            }
        }

        data.writeln(d[(4 - (n % 4)) % 4])
        data.close()
    }
}

fun main(args: Array<String>) {
    Solution().solve()
}

