class Window(len: Int) {
    private val eleQ = IntBuffer(len)
    private val minQ = IntBuffer(len)

    fun add(item: Int) {
        if(eleQ.isFull && eleQ.removeFirst() == minQ.first) minQ.removeFirst()
        eleQ.addLast(item)
        while(minQ.size != 0 && minQ.last > item) minQ.removeLast()
        minQ.addLast(item)
    }

    val min: Int get() = minQ.first
}

