class IntBuffer(val capacity: Int) {
    private val arr = IntArray(capacity)
    var size = 0
        private set

    val isFull get() = size == capacity
    private var head = 0

    private fun incHead() {
        head++
        if(head == capacity) head = 0
    }

    private fun decHead() {
        if(head == 0) head = capacity - 1
        else head--
    }

    private fun index(i: Int) = (head + i).let { if(it >= capacity) it - capacity else it }

    fun addLast(e: Int) {
        if(isFull) return
        arr[index(size)] = e
        size++
    }

    fun removeFirst(): Int {
        val e = get(0)
        incHead()
        size--
        return e
    }
    fun removeLast(): Int {
        val e = get(size-1)
        size--
        return e
    }

    fun addFirst(e: Int) {
        if(isFull) return
        decHead()
        arr[head] = e
        size++
    }

    fun get(index: Int): Int = arr[index(index)]
    val first get() = get(0)
    val last get() = get(size-1)
}

