    for (pos in 0 until n - 1) {
        aDeltas[pos] = aes[pos + 1] - aes[pos]
        bDeltas[pos] = bs[pos + 1] - bs[pos]
    }
    aDeltas[n - 1] = l - aes.last() + aes.first()
    bDeltas[n - 1] = l - bs.last() + bs.first()
    loop@ for (start in 0 until n) {
        for (pos in 0 until n) {
            if (aDeltas[pos] != bDeltas[(start + pos) % n]) continue@loop
        }
        print("YES")
        return
    }
    print("NO")
}

