fun main() { _writer.solve(); _writer.flush() }
fun PrintWriter.solve() {
//    val startTime = System.nanoTime()

    val numCases = 1//readInt()
    case@ for(case in 1..numCases) {
//        print("Case #$case: ")

        val n = read().toBigInteger()

        val ones = Array(51) { one }
        for(i in 1..ones.lastIndex) ones[i] = (ones[i-1] * ten).inc()

        val heap = DijkHeap()
        heap.promote(n, 0)

        val ans = run ans@ {
            while(heap.isNotFinished()) {
                val x = heap.remove()
                val c = heap.cost(x)

                if(x == BigInteger.ZERO) return@ans c

                val i = ones.bsIndexOfLast { it <= x }
                heap.promote(x - ones[i], c + i + 1)
                heap.promote(ones[i+1] - x, c + i + 2)
            }

            -1
        }

        println(ans)
    }

//    iprintln("Time: ${(System.nanoTime() - startTime) / 1000000} ms")
}

