class Main {
    internal class TaskA {
        fun solve(inp: InputReader, out: PrintWriter) {
            val n = inp.nextInt()
            val primes = sieve(60)
            var ans = 0
            for (i in 1..n) {
                val set = hashSetOf<Int>()
                var j = 0
                var v = i
                while (primes[j] * primes[j] <= v)
                    if (v % primes[j] == 0) {
                        v /= primes[j]
                        set.add(primes[j])
                    } else
                        j++
                if (v > 1)
                    set.add(v)
                if (set.size == 2)
                    ans++
            }
            out.println(ans)
        }

        private fun sieve(max: Int): IntArray {
            val a = Array(max + 1) { true }
            val primes = arrayListOf<Int>()
            for (i in 2..max)
                if (a[i]) {
                    primes.add(i)
                    var j = 2 * i
                    while (j <= max) {
                        a[j] = false
                        j += i
                    }
                }
            return primes.toIntArray()
        }
    }

