enum class SetType {
    EMPTY,
    LINE,
    WHOLE_FIELD
}

typealias Line = Triple<Int, Int, Int>
fun Line.a() = first
fun Line.b() = second
fun Line.c() = third


fun Line.setType(): SetType {
    if (a() == 0 && b() == 0 && c() == 0) return SetType.WHOLE_FIELD
    if (a() == 0 && b() == 0) return SetType.EMPTY
    return SetType.LINE
}

fun calcDet(line1: Line, line2: Line) = line1.a() * line2.b() - line1.b() * line2.a()

fun calcIntersections(line1: Line, line2: Line): Int {
    if (line1.setType() == SetType.EMPTY || line2.setType() == SetType.EMPTY) return 0
    if (line1.setType() == SetType.WHOLE_FIELD || line2.setType() == SetType.WHOLE_FIELD) return -1
    val det = calcDet(line1, line2)
    if (det != 0) return 1

    return if (line1.first != 0) {
        val c1f = line1.c() * line2.a()
        val c2f = line2.c() * line1.a()
        if (c1f == c2f) -1 else 0
    } else {
        val c1f = line1.c() * line2.b()
        val c2f = line2.c() * line1.b()
        if (c1f == c2f) -1 else 0
    }
}

