internal class Parserdoubt(`in`: InputStream) {
    private val BUFFER_SIZE = 1 shl 17

    private val din: DataInputStream
    private val buffer: ByteArray
    private var bufferPointer: Int = 0
    private var bytesRead: Int = 0

    init {
        din = DataInputStream(`in`)
        buffer = ByteArray(BUFFER_SIZE)
        bytesRead = 0
        bufferPointer = bytesRead
    }

    @Throws(Exception::class)
    fun nextString(): String {
        val sb = StringBuffer("")
        var c = read()
        while (c <= ' '.toByte())
            c = read()
        do {
            sb.append(c.toChar())
            c = read()
        } while (c > ' '.toByte())
        return sb.toString()
    }

    @Throws(Exception::class)
    fun wholeLine(): String {
        val sb = StringBuffer("")
        var c = read()
        while (c <= '\n'.toByte())
            c = read()
        do {
            sb.append(c.toChar())
            c = read()
        } while (c > '\n'.toByte())
        return sb.toString()
    }

    @Throws(Exception::class)
    fun nextChar(): Char {
        var c = read()
        while (c <= ' '.toByte())
            c = read()
        return c.toChar()
    }

    @Throws(Exception::class)
    fun nextInt(): Int {
        var ret = 0
        var c = read()
        while (c <= ' '.toByte())
            c = read()
        val neg = c == '-'.toByte()
        if (neg)
            c = read()
        do {
            ret = ret * 10 + c - '0'.toInt()
            c = read()
        } while (c > ' '.toByte())
        return if (neg) -ret else ret
    }

    @Throws(Exception::class)
    fun nextLong(): Long {
        var ret: Long = 0
        var c = read()
        while (c <= ' '.toByte())
            c = read()
        val neg = c == '-'.toByte()
        if (neg)
            c = read()
        do {
            ret = ret * 10 + c - '0'.toLong()
            c = read()
        } while (c > ' '.toByte())
        return if (neg) -ret else ret
    }

    @Throws(Exception::class)
    private fun fillBuffer() {
        bufferPointer = 0
        bytesRead = din.read(buffer, 0, BUFFER_SIZE)
        if (bytesRead == -1)
            buffer[0] = -1
    }

    @Throws(Exception::class)
    private fun read(): Byte {
        if (bufferPointer == bytesRead)
            fillBuffer()
        return buffer[bufferPointer++]
    }
}

