fun binExp(a: Long, n: Long): Long{
    tailrec fun go(a: Long, n: Long, a1: Long): Long{
        if (n == 0.toLong()) return 1
        if (n == 1.toLong()) return a * a1

        if (n % 2 == 0.toLong()) return go(a * a, n/2, a1)
        else return go(a * a, (n - 1)/2, a * a1)
    }
    return go(a, n, 1)
}

