class SuffixArray(val input : String){
    //time complexity is n(log(n))^2

    fun sa() : IntArray{
        val n = input.length
        var cur = IntArray(n) { i -> input[i] -'a' } //will store the current sort order
        for (i in 1 until 20){
            val newCur = IntArray(n) { 0 }
            val newlist = mutableListOf<Triple<Int, Int, Int>>()
            for (j in 0 until n) {
                newlist.add(Triple(j, cur[j], if ( j+ power(2, i) < n) cur[j + power(2, i)] else -1))
            }
            newlist.sortWith(comparator())
            //after sorting
            for (j in 0 until n){
                newCur[newlist[j].first] = if (j > 0 && newlist[j].second == newlist[j - 1].second && newlist[j].third == newlist[j - 1].third) newCur[newlist[j - 1].first] else j
            }
            cur =  newCur

        }
        return cur
    }

    internal class comparator : Comparator<Triple<Int, Int, Int>>{
        override fun compare(o1: Triple<Int, Int, Int>?, o2: Triple<Int, Int, Int>?): Int {
            if (o1!!.second != o2!!.second){
                return o1.second.compareTo(o2.second)
            }else{
                //both are equal what to do now
                return o1.third.compareTo(o2.third)
            }
        }
    }


}



class Primes{
    val limit = 1000
    val composites = IntArray(limit + 1) { 0 }
    val factors= IntArray(limit + 1) { 0 }
    val preFactors = IntArray(limit + 1) { 0 }
    val primes  = mutableListOf<Int>()

    init {
        sieve()
        calcFactors()
    }

    fun sieve(){
        for (i in 2 until limit + 1){
            if (composites[i] == 0){
                primes.add(i)
                var cur = 1
                while (cur*i <= limit){
                    composites[cur*i] = i
                    cur++
                }
            }
        }
    }

    fun calcFactors(){
        for (i in 2 until limit + 1){
            var num = i
            while (num != 1){
                factors[i]++
                num /= composites[num]
            }
        }
        for (i in 2 until limit + 1){
            preFactors[i]= preFactors[i - 1] + factors[i]
        }
    }
}



