fun power(i: Int, j: Int): Int {
    if (j == 0) return 1
    return i * power(i, j - 1)
}

class MinSegmentTree(
        input: Array<Int>
) {
    private val tree: Array<Int>
    private val lazy: Array<Int>

    constructor(size: Int) : this(Array(size) { Int.MAX_VALUE })

    init {
        val size = nextPowerOfTwo(input.size)
        tree = Array(2 * size) { Int.MAX_VALUE }
        lazy = Array(2 * size) { Int.MAX_VALUE }
        for (i in 0 until input.size) {
            tree[i + size] = input[i]
        }
        for (i in (size - 1) downTo 1) {
            tree[i] = Math.min(tree[leftChild(i)], tree[rightChild(i)])
        }
    }

    private fun updateTree(lowerRange: Int, upperRange: Int, lowerBound: Int, upperBound: Int, index: Int, value: Int) {
        updateLazyNode(index, lowerBound, upperBound, lazy[index])
        if (noOverlap(lowerRange, upperRange, lowerBound, upperBound)) return
        else if (completeOverlap(lowerRange, upperRange, lowerBound, upperBound)) updateLazyNode(index, lowerBound, upperBound, value)
        else {
            updateTree(lowerRange, upperRange, lowerBound, midIndex(lowerBound, upperBound), leftChild(index), value)
            updateTree(lowerRange, upperRange, midIndex(lowerBound, upperBound) + 1, upperBound, rightChild(index), value)
            tree[index] = Math.min(tree[leftChild(index)], tree[rightChild(index)])
        }
    }

    private fun queryTree(lowerRange: Int, upperRange: Int, lowerBound: Int, upperBound: Int, index: Int): Int {
        updateLazyNode(index, lowerBound, upperBound, lazy[index])
        if (noOverlap(lowerRange, upperRange, lowerBound, upperBound)) return Int.MAX_VALUE
        else if (completeOverlap(lowerRange, upperRange, lowerBound, upperBound)) return tree[index]
        else {
            return Math.min(queryTree(lowerRange, upperRange, lowerBound, midIndex(lowerBound, upperBound), leftChild(index)),
                    queryTree(lowerRange, upperRange, midIndex(lowerBound, upperBound) + 1, upperBound, rightChild(index)))
        }
    }

    private fun updateLazyNode(index: Int, lowerBound: Int, upperBound: Int, delta: Int) {
        tree[index] += delta
        if (lowerBound != upperBound) {
            lazy[leftChild(index)] += delta
            lazy[rightChild(index)] += delta
        }
        lazy[index] = 0
    }

    fun getElements(N: Int): List<Int> {
        return tree.copyOfRange(tree.size / 2, tree.size / 2 + N).asList()
    }

    fun update(lowerRange: Int, upperRange: Int, value: Int) {
        updateTree(lowerRange, upperRange, 1, lazy.size / 2, 1, value)
    }

    fun query(lowerRange: Int, upperRange: Int): Int {
        return queryTree(lowerRange, upperRange, 1, lazy.size / 2, 1)
    }

    private fun noOverlap(l: Int, u: Int, lb: Int, ub: Int): Boolean = (lb > u || ub < l)

    private fun completeOverlap(l: Int, u: Int, lb: Int, ub: Int): Boolean = (lb >= l && ub <= u)


    private fun nextPowerOfTwo(num: Int): Int {
        var exponent = 2
        while (true) {
            if (exponent >= num) {
                return exponent
            }
            exponent *= 2
        }
    }

    private fun midIndex(l: Int, r: Int) = (l + r) / 2
    private fun parent(i: Int) = i / 2
    private fun leftChild(i: Int) = 2 * i
    private fun rightChild(i: Int) = 2 * i + 1

}

class InputReader(private val stream: InputStream) {
    private val buf = ByteArray(1024)
    private var curChar: Int = 0
    private var numChars: Int = 0
    private val filter: SpaceCharFilter? = null

    fun read(): Int {
        if (numChars == -1)
            throw InputMismatchException()
        if (curChar >= numChars) {
            curChar = 0
            try {
                numChars = stream.read(buf)
            } catch (e: IOException) {
                throw InputMismatchException()
            }

            if (numChars <= 0)
                return -1
        }
        return buf[curChar++].toInt()
    }

    fun readInt(): Int {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        var sgn = 1
        if (c == '-'.toInt()) {
            sgn = -1
            c = read()
        }
        var res = 0
        do {
            if (c < '0'.toInt() || c > '9'.toInt())
                throw InputMismatchException()
            res *= 10
            res += c - '0'.toInt()
            c = read()
        } while (!isSpaceChar(c))
        return res * sgn
    }

    fun readLong(): Long {
        var c = read()
        while (isSpaceChar(c)) {
            c = read()
        }
        var sgn: Long = 1
        if (c == '-'.toInt()) {
            sgn = -1
            c = read()
        }
        var number: Long = 0
        do {
            number *= 10L
            number += (c - '0'.toInt()).toLong()
            c = read()
        } while (!isSpaceChar(c))
        return number * sgn
    }

    fun readString(): String {
        var c = read()
        while (isSpaceChar(c))
            c = read()
        val res = StringBuilder()
        do {
            res.appendCodePoint(c)
            c = read()
        } while (!isSpaceChar(c))
        return res.toString()
    }

    fun isSpaceChar(c: Int): Boolean {
        return filter?.isSpaceChar(c)
                ?: (c == ' '.toInt() || c == '\n'.toInt() || c == '\r'.toInt() || c == '\t'.toInt() || c == -1)
    }

    operator fun next(): String {
        return readString()
    }

    interface SpaceCharFilter {
        fun isSpaceChar(ch: Int): Boolean
    }
}

class OutputWriter {
    private val writer: PrintWriter

    constructor(outputStream: OutputStream) {
        writer = PrintWriter(BufferedWriter(OutputStreamWriter(outputStream)))
    }

    constructor(writer: Writer) {
        this.writer = PrintWriter(writer)
    }

    fun print(vararg objects: Any) {
        for (i in objects.indices) {
            if (i != 0)
                writer.print(' ')
            writer.print(objects[i])
        }
    }

    fun printLine(vararg objects: Any) {
        print(*objects)
        writer.println()
    }

    fun close() {
        writer.close()
    }

    fun flush() {
        writer.flush()
    }

}

class DinitzMaxFlowSolver(val n: Int, val s: Int, val t: Int, val graph: MutableMap<Int, MutableList<Edge>>, val edgeMap: MutableMap<Pair<Int, Int>, Edge>) {

    private val level = IntArray(n + 1) { -1 }  //storing levels of each vertex in level graph
    var maxFlow = 0L

    init {
        solve()
    }

    fun solve() {
        val next = IntArray(n + 1) { 0 }
        while (bfs()) {
            Arrays.fill(next, 0)
            var flow = 0L
            do {
                maxFlow += flow
                flow = dfs(s, next, Long.MAX_VALUE)
            } while (flow != 0L)
        }
    }

    private fun dfs(at: Int, next: IntArray, flow: Long): Long {
        if (at == t) return flow
        var size = 0
        if (graph.containsKey(at)) size = graph[at]!!.size
        while (next[at] < size) {
            val edge = graph[at]!!.get(next[at])
            if (edge.remainingCapacity() > 0 && level[edge.to] == level[at] + 1) {
                val bottleNeck = dfs(edge.to, next, Math.min(flow, edge.remainingCapacity()))
                if (bottleNeck > 0) {
                    edgeMap[Pair(edge.from, edge.to)]!!.flow += bottleNeck
                    edgeMap[Pair(edge.to, edge.from)]!!.flow -= bottleNeck
                    return bottleNeck
                }
            }
            next[at]++
        }
        return 0
    }

    private fun bfs(): Boolean {
        Arrays.fill(level, -1)
        val curLevel = ArrayDeque<Int>()
        curLevel.add(s)
        level[s] = 0

        while (curLevel.isNotEmpty()) {
            val top = curLevel.poll()
            if (graph.containsKey(top)) {
                graph[top]!!.forEach {
                    if (it.remainingCapacity() > 0 && level[it.to] == -1) {
                        level[it.to] = level[top] + 1
                        curLevel.offer(it.to)
                    }
                }
            }
        }
        return level[t] != -1
    }


}

class Edge(val from: Int, val to: Int, val capacity: Long) {
    var flow = 0L
    fun remainingCapacity(): Long {
        return capacity - flow
    }
}


class ConnectedComponents(val g : Graph, val price : IntArray){

    private val visited = HashSet<Int>()
    private val stack = Stack<Int>()
    private val revertedGraph = revertGraph()
    private val component = mutableListOf<Int>()
    var ways= 1L
    var min = 0L
    val mod = 1000000007

    init {
        getConnectedComponents()
    }


    fun getConnectedComponents() {
        g.vertices.forEach {
            if (!visited.contains(it)){
                visited.add(it)
                dfs(it)
            }
        }

        visited.clear()
        while (stack.isNotEmpty()){
            val node = stack.pop()
            if (!visited.contains(node)){
                visited.add(node)
                dfs2(node)
                var take = Int.MAX_VALUE
                for (i in 0 until component.size){
                    if (price[component[i] - 1] < take){
                        take = price[component[i] - 1]
                    }
                }
                min+= take
                ways= (ways*component.filter { price[it - 1] == take }.count())%mod
                component.clear()
            }
        }
    }

    fun dfs(node : Int){
        if (g.edges.containsKey(node)){
            g.edges[node]!!.forEach {
                if (!visited.contains(it)){
                    visited.add(it)
                    dfs(it)
                }
            }
        }
        stack.push(node)
    }

    fun dfs2(node : Int){
        component.add(node)
        if (revertedGraph.edges.containsKey(node)){
            revertedGraph.edges[node]!!.forEach {
                if (!visited.contains(it)){
                    visited.add(it)
                    dfs2(it)
                }
            }
        }
    }

    fun revertGraph() : Graph {
        val newEdges= mutableMapOf<Int, MutableList<Int>>()
        g.edges.forEach {
            val u = it.key
            val vs = it.value
            vs.forEach { v ->
                if (!newEdges.containsKey(v)){
                    newEdges[v]= mutableListOf()
                }
                newEdges[v]!!.add(u)
            }
        }
        return Graph(g.vertices, newEdges)
    }
}

