fun PrintWriter.solve() {
//    val startTime = System.nanoTime()

    val numCases = 1//readInt()
    case@ for(case in 1..numCases) {
//        print("Case #$case: ")

        val n = readInt()
        val k = readInt()
        val s = CharArray(n) { readChar() }.also { readChar() }
        val a = readChar()
        val b = readChar()

        val ans = if(a == b) {
            val x = min(n, k + s.count { it == a })
            x * (x-1) / 2
        } else {
            // Di[x][y] = score
            // x = number of moves used
            // y = number of a's made

            var D = Array(1) { IntArray(1) }

            for(i in 0 until n) {
                val si = s[i]
                val diff = si != a && si != b
                val Di = Array(min(k, i+1)+1) { IntArray(i+2) { -1 } }

                for(x in D.indices) {
                    for(y in D[x].indices) {
                        val d = D[x][y]
                        if(d == -1) continue
                        if(diff) Di[x].setMax(y, d)

                        // a
                        run {
                            val nx = if(si == a) x else x+1
                            if(nx <= k) Di[nx].setMax(y+1, d)
                        }

                        // b
                        val nx = if(si == b) x else x+1
                        if(nx <= k) Di[nx].setMax(y, d + y)
                    }
                }

                D = Di
            }

            var ans = 0
            for(dx in D) ans = max(ans, dx.max()!!)
            ans
        }

        println(ans)
    }

//    iprintln("Time: ${(System.nanoTime() - startTime) / 1000000} ms")
}

