fun solve(k: Int, s: String, t: String): Int {
    var res = calc(s.toCharArray(), t)

    for (toChange in 0..k) {
        for (l in 0..toChange) {
            val c = s.toCharArray()
            val r = toChange - l
            var count = 0
            for (i in c.indices) {
                if (count == l) {
                    break
                }
                if (c[i] == t[1]) {
                    c[i] = t[0]
                    count++
                }
            }
            count = 0
            for (i in c.indices.reversed()) {
                if (count == r) {
                    break
                }
                if (c[i] == t[0]) {
                    c[i] = t[1]
                    count++
                }
            }

            val left = k - toChange
            val lPos = c.withIndex().filter { it.value !in t }.take(left)
            val rPos = c.withIndex().reversed().filter { it.value !in t  }.take(left).reversed()


            for (p in rPos) {
                c[p.index] = t[1]
            }
            res = maxOf(res, calc(c, t))
            var idx = 0
            for (p in lPos) {
                c[rPos[idx].index] = rPos[idx++].value
                c[p.index] = t[0]
                res = maxOf(res, calc(c, t))
            }
        }
    }
    return res
}

fun calc(c: CharArray, t: String): Int {
    var res = 0
    var second = c.count { it == t[1] }
    for (i in c.indices) {
        if (c[i] == t[1]) {
            second--
        }
        if (c[i] == t[0]) {
            res += second
        }
    }
    return res
}

