fun main() {
    val out = PrintWriter(System.out)
    val fs = FS(System.`in`)

    var T = 1
    while(T-->0) {

        var n = fs.nextInt()
        var moves = fs.nextInt()
        var S1 = fs.next()
        var S2 = fs.next()

        var A = S2[0]
        var B = S2[1]

        var dp = Array(n){Array(moves+1){IntArray(n)}}
        for(i in 0 until n)
            for(j in 0 until moves+1)
                dp[i][j].fill(-1)

        fun solve(idx: Int, moves: Int, numA: Int): Int {
            if(idx == n) return 0
            var dpRet = dp[idx][moves][numA]
            if(dpRet != -1) return dpRet

            var res = 0
            var extras = if(S1[idx] == B) numA else 0
            var newNumA = numA + if(S1[idx] == A) 1 else 0

            res = solve(idx+1, moves, newNumA)+extras

            if(moves > 0) {
                for(x in 0 until 2) {
                    extras = if(S2[x] == B) numA else 0
                    newNumA = numA + if(S2[x] == A) 1 else 0
                    var ret = solve(idx+1, moves-1, newNumA)+extras
                    res = max(res, ret)
                }
            }

            dp[idx][moves][numA] = res
            return res
        }

        println(solve(0, moves, 0))

    }

    out.close()
}

