fun solve(a: Long, b: Long): Boolean {
    val set = mutableSetOf<String>()
    set.add(a.toString(2))
    val q: Queue<String> = LinkedList()
    q.add(a.toString(2))

    while (!q.isEmpty()) {
        val s = q.poll()
        var t: String

        t = s + "0"
        t = t.reversed()
        while (t.length > 1 && t[0] == '0') {
            t = t.substring(1)
        }

        if (t.length < 100) {
            if (set.contains(t).not()) {
                set.add(t)
                q.add(t)
            }
        }

        t = s + "1"
        t = t.reversed()
        if (t.length < 100) {
            if (set.contains(t).not()) {
                set.add(t)
                q.add(t)
            }
        }
    }
    return set.contains(b.toString(2))
}

