fun gcd(a: Long, b: Long) : Long = if (a == 0L) b else gcd(b % a, a)

fun exGcd(a: Long, b: Long) : Pair<Long, Long> {
  if (a == 0L)
    return 0L to 1L
  val (r1, r2) = exGcd(b % a, a)
  return r2 - r1 * (b/a) to r1
}

