fun run() {

    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val k = scanner.nextInt()
    val arr = LongArray(n + 1) { 1L }
    var mod = 1000000007L
    val help = Array<IntArray>(n + 1) {
        if (it < 2)
            return@Array intArrayOf()
        val a = ArrayList<Int>()
        var i = 2
        while (i * i <= it) {
            if (it % i == 0) {
                a.add(i)
                if (i * i != it)
                    a.add(it / i)
            }
            i++
        }
        a.add(1)
        a.toIntArray()
    }
    for (i in 1 until k) {
        for (j in 2..n) {
            for (q in help[j]) {
                arr[q] += arr[j]
                arr[q] %= mod
            }
        }
    }
    var res = 0L
    for (i in 1..n) {
        res += arr[i]
        res %= mod
    }
    println(res)

}

class Scanner(s: InputStream) {
    var st: StringTokenizer? = null
    var br: BufferedReader = BufferedReader(InputStreamReader(s))
    @Throws(IOException::class)
    operator fun next(): String {
        while (st == null || !st!!.hasMoreTokens())
            st = StringTokenizer(br.readLine())
        return st!!.nextToken()
    }
    @Throws(IOException::class)
    fun nextInt(): Int {
        return Integer.parseInt(next())
    }
    @Throws(IOException::class)
    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }
    @Throws(IOException::class)
    fun nextLine(): String {
        return br.readLine()
    }
    @Throws(IOException::class)
    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }
    @Throws(IOException::class)
