fun num_good_sequences(n : Int, k : Int) : Long {
  val modulo = 1000000007L
  val num_ways = Array(n + 1, {_ -> LongArray(k + 1)}) 
  for (i in 1 .. n) {
    num_ways[i][1] = 1L
  }
  for (j in 1 .. (k - 1)) {
    val j_plus_1 = j + 1
    for (i in 1 .. n) {
      var f = 1
      var fi = f * i
      while (fi <= n) {
        num_ways[fi][j_plus_1] = (num_ways[fi][j_plus_1] + num_ways[i][j]) % modulo
        f = f + 1
        fi = f * i
      }
    }
  }
  var result = 0L
  for (i in 1 .. n) {
    result = (result + num_ways[i][k]) % modulo
  }
  return result
}

