fun solve(ir : InputReader, pw : PrintWriter) {

    val n : Int = ir.nextInt()
    val m : Int = ir.nextInt()
    val min : Int = ir.nextInt()
    val max : Int = ir.nextInt()
    val t = IntArray(m)
    var count = 0
    var myMin = 101
    var myMax = 0

    for (i in 0 until m)
        t[i] = ir.nextInt()

    for (i in 0 until m) {
        if (t[i] < myMin)
            myMin = t[i]

        if (t[i] > myMax)
            myMax = t[i]
    }

    if (myMax > max || myMin < min)
        pw.print("Incorrect")
    else {
        if (myMax < max)
            count++
        if (myMin > min)
            count++

        if (n - m >= count)
            pw.print("Correct")
        else
            pw.print("Incorrect")
    }

}

class InputReader(stream: InputStream) {
    private val reader: BufferedReader = BufferedReader(InputStreamReader(stream), 32768)
    private var tokenizer: StringTokenizer? = null

    init {
        tokenizer = null
    }

    operator fun next(): String {
        while (tokenizer == null || !tokenizer!!.hasMoreTokens())
            try {
                tokenizer = StringTokenizer(reader.readLine())
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

        return tokenizer!!.nextToken()
    }

    fun nextLine(): String? {
        val fullLine: String
        while (tokenizer == null || !tokenizer!!.hasMoreTokens()) {
            try {
                fullLine = reader.readLine()
            } catch (e: IOException) {
                throw RuntimeException(e)
            }

            return fullLine
        }
        return null
    }

    fun toArray(): Array<String> {
        return nextLine()!!.split(" ".toRegex()).dropLastWhile { it.isEmpty() }.toTypedArray()
    }

    fun nextInt(): Int {
        return Integer.parseInt(next())
    }

    fun nextDouble(): Double {
        return java.lang.Double.parseDouble(next())
    }

    fun nextLong(): Long {
        return java.lang.Long.parseLong(next())
    }

}

