fun solve(io: ProblemIO) {
    val c = IntArray(10)
    val a = IntArray(6, { io.readInt() })
    for (v in a) {
        ++c[v]
    }
    val li = c.indices.find({ i -> c[i] >= 4 }) ?: 0
    c[li] -= 4
    val ri = c.indices.find({ i -> c[i] == 2 }) ?: 0
    val res = when {
        li == 0 -> "Alien"
        li != 0 && ri != 0 -> "Elephant"
        else -> "Bear"
    }
    io.println(res)
