class FastScanner(ins: InputStream): Closeable {
    val BUFFER_SIZE = 65536;
    val br: BufferedReader
    var end = false

    var len: Int = 0
    val buffer = CharArray(BUFFER_SIZE)
    var it: Int = 0

    init {
        br = BufferedReader(InputStreamReader(ins), BUFFER_SIZE)
    }

    constructor(file: String): this(FileInputStream(file))

    inline fun isLineBreaker(c: Char) = c == '\n'
    inline fun isDelimiter(c: Char) = c == ' ' || c == '\n' || c == '\r'

    inline fun ensureBuffer() {
        if (it == len) {
            it = 0
            len = br.read(buffer)
            if (len == -1) end = true
        }
    }

    inline fun moveNext() {
        while (!end) {
            ensureBuffer()
            if (!isDelimiter(buffer[it])) return
            while (it < len && isDelimiter(buffer[it])) it++;
        }
    }

    inline fun nextChar(): Char {
        moveNext()
        if (end) return (-1).toChar()
        return buffer[it++]
    }

    inline fun next(): String {
        moveNext()
        val sb = StringBuilder()
        while (!end) {
            val l = it
            while (++it < len && !isDelimiter(buffer[it]));
            sb.append(buffer, l, it - l)
            ensureBuffer()
            if (end || isDelimiter(buffer[it])) break;
        }
        return sb.toString()
    }

    inline fun nextInt(): Int {
        moveNext()
        var minus = true
        if (buffer[it] == '-') {
            it++
            minus = false
        }
        var result: Int = 0
        while (!end) {
            while (it < len && !isDelimiter(buffer[it])) {
                result *= 10
                result += (buffer[it] - '0').toInt()
                it++
            }
            ensureBuffer()
            if (end || isDelimiter(buffer[it])) break
        }
        return if (minus) result else -result
    }

    inline fun nextLong(): Long {
        moveNext()
        var minus = true
        if (buffer[it] == '-') {
            it++
            minus = false
        }
        var result: Long = 0
        while (!end) {
            while (it < len && !isDelimiter(buffer[it])) {
                result *= 10
                result += (buffer[it] - '0').toLong()
                it++
            }
            ensureBuffer()
            if (end || isDelimiter(buffer[it])) break
        }
        return if (minus) result else -result
    }

    inline fun nextLine(): String {
        moveNext()
        val sb = StringBuilder()
        while (!end) {
            val l = it
            while (++it < len && !isLineBreaker(buffer[it]));
            sb.append(buffer, l, it - l)
            ensureBuffer()
            if (end || isLineBreaker(buffer[it])) break;
        }
        return sb.toString()
    }

    override fun close() {
        br.close()
    }
}

