fun tryEat(n: Long, c: Long): Boolean {
    var remains = n
    var eaten = 0L

    while (remains > c) {
        remains -= c
        eaten += c

        remains -= remains / 10
    }
    eaten += remains
//    println(eaten)

    return eaten * 2 >= n
}

