val MOD = 1_000_000_007
class Comb(n: Int, val mod: Int) {

  val F = LongArray(n + 1)
  val I = LongArray(n + 1)
  init {
    F[0] = 1
    for (i in 1..n) {
      F[i] = F[i - 1] * i % mod
    }
    I[n] = powMod(F[n], (mod - 2).toLong(), mod)
    for (i in n - 1 downTo 0) {
      I[i] = I[i + 1] * (i + 1) % mod
    }
  }

  private fun powMod(a: Long, n: Long, mod: Int): Long {
    if (n == 0L) return 1
    val res = powMod(a * a % mod, n / 2, mod)
    return if (n % 2 == 1L) res * a % mod else res
  }

  fun comb(n: Int, k: Int): Long {
    return F[n] * I[k] % mod * I[n - k] % mod
  }

  fun inv(x: Int): Long {
    return I[x] * F[x - 1] % mod
  }

  /**
   * nのグループからk回重複ありで選ぶ組み合わせ数
   * n - 1のしきりとkの○で考える
   */
  fun H(n: Int, k: Int) = comb(n + k - 1, k)
}
class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val N = ni()
    val K = nl()
    val comb = Comb(N + 10, MOD)
    val powK = LongArray(N + 11)
    val powKK = LongArray(N + 11)
    powK[0] = 1
    powKK[0] = 1
    for (i in 0 until N + 10) {
      powK[i + 1] = powK[i] * K % MOD
      powKK[i + 1] = powKK[i] * (K - 1) % MOD
    }
    val dp = Array(N + 1){LongArray(N + 1)}
    dp[0][0] = 1
    for (i in 0 until N) {
      for (s in 0 .. N) {
        val cmb1 = (MOD + powK[s] - powKK[s]) % MOD // sの中に１がある
        val cmbAll = powK[s] // すべて
        for (add in 0 .. N - s) {
          val ns = s + add
          val cl = if (add == 0) cmb1 else cmbAll // s側の組み合わせ
          val cr1 = comb.comb(N - s, add) // addの1部分
          val crr = powKK[N - s - add] // addの1以外の部分
          val cmb = cl * cr1 % MOD * crr % MOD
          dp[i + 1][ns] = (dp[i + 1][ns] + dp[i][s] * cmb % MOD) % MOD
        }
      }
      debug(dp[i + 1])
    }

    out.println(dp[N][N])
  }













































