fun f(_p: Long, deg: Int, k: Int): Int {
    val dp = Array(k + 1) { IntArray(deg + 1) }
    dp[0][deg] = 1
    val inverses = IntArray(deg + 2) { inverse(it) }
    for (step in 1..k) {
        for (d in 0..deg) {
            for (nd in d..deg) {
                dp[step][d] = add(dp[step][d], mult(dp[step - 1][nd], inverses[nd + 1]))
            }
        }
    }
    var result = 0
    var pi = 1
    val p = (_p % MOD).toInt()
    for (i in 0..deg) {
        result = add(result, mult(dp[k][i], pi))
        pi = mult(pi, p)
    }
    return result
}

