fun Long.factorize() = sequence {
    var n = this@factorize

    for(p in 2..Long.MAX_VALUE) {
        if(p * p > n) break

        while(n % p == 0L) {
            yield(p)
            n /= p
        }
    }

    if(n > 1) yield(n)
}

data class Run<T>(val item: T, val num: Int)

fun <T> Sequence<T>.runs() = sequence {
    val i = iterator()

    if(i.hasNext().not()) return@sequence
    var last = i.next()
    var num = 1

    for(e in i) {
        if(last == e) num++
        else {
            yield(Run(last, num))
            last = e
            num = 1
        }
    }
    yield(Run(last, num))
}

