private fun factors(n: Long): LongArray {
    val ret = mutableListOf<Long>()
    val limit = sqrt(n.toDouble()).toInt()
    for (i in 1..limit) {
        if (n % i == 0L) {
            ret.add(i.toLong())
            if (i.toLong() * i != n) {
                ret.add(n / i)
            }
        }
    }
    ret.sort()
    return ret.toLongArray()
}

fun main() {
    Thread(null, {
        val (n, kTmp) = readLongs()
        val k = kTmp.toInt()
        debug("k=$k")

        val t = System.nanoTime()

        val primeFactors = mutableListOf<Pair<Long, Int>>() // (prime, exp)
        run {
            val limit = sqrt(n.toDouble()).toInt()
            var nn = n
            for (i in 2..limit) {
                if (nn % i == 0L) {
                    var cnt = 0
                    while (nn % i == 0L) {
                        cnt++
                        nn /= i
                    }
                    primeFactors.add(i.toLong() to cnt)
                }
            }
            if (nn > 1) {
                primeFactors.add(nn to 1)
            }
            for (primeFactor in primeFactors) {
                debug(primeFactor)
            }
        }

        var ans = 1L

        fun solve(p: Long, e: Int): Long {
            val props = Array(k + 1) { LongArray(e + 1) { 0 } }
            val ev = Array(k + 1) { LongArray(e + 1) { 0 } }
            for (i in 0..e) {
                props[0][i] = 1
                ev[0][i] = p.powerMod(i)
            }
            for (kk in 1..k) {
                for (i in 0..e) {
                    for (j in 0..i) {
                        props[kk][i] = props[kk][i].addMod(props[kk - 1][j])
                        ev[kk][i] = ev[kk][i].addMod(ev[kk - 1][j])
                    }
                    props[kk][i] = props[kk][i].divMod(i + 1L)
                    ev[kk][i] = ev[kk][i].divMod(i + 1L)
                }
            }
            return ev[k][e]
        }

        for ((p, exp) in primeFactors) {
            ans = ans.mulMod(solve(p, exp))
        }

        writeLn(ans)

        debug("time: ${(System.nanoTime() - t) / 1e9}")
    }, "cool", 1 shl 28).apply {
        start()
        join()
    }
    flush()
}

private fun invMod0(a: Long, m: Long): Long {
    val ans = extGcd(a, m)
    return if (ans[0] == 1L) (ans[1] + m) % m else -1
}

private fun extGcd(a: Long, m: Long): LongArray {
    return if (m == 0L) {
        longArrayOf(a, 1, 0)
    } else {
        val ans = extGcd(m, a % m)
        val tmp = ans[1]
        ans[1] = ans[2]
        ans[2] = tmp
        ans[2] -= ans[1] * (a / m)
        ans
    }
}

private fun Long.sqr() = this * this

private const val MODULO = (1e9 + 7).toLong()
private fun Long.addMod(other: Long): Long {
    var ret = this + other
    while (ret >= MODULO) {
        ret -= MODULO
    }
    while (ret < 0) {
        ret += MODULO
    }
    return ret
}

private fun Long.subMod(other: Long) = addMod(-other)
private fun Long.mulMod(other: Long) = this % MODULO * (other % MODULO) % MODULO
private fun Long.invMod() = invMod0(this, MODULO)
private fun Long.divMod(other: Long) = mulMod(other.invMod())
private fun Long.powerMod(exp: Int): Long = when {
    exp == 0 -> 1
    exp % 2 == 0 -> powerMod(exp / 2).sqr() % MODULO
    else -> powerMod(exp - 1).mulMod(this)
}

