                    while (nn % i == 0L) {
                        cnt++
                        nn /= i
                    }
                    primeFactors.add(i.toLong() to cnt)
                }
            }
            if (nn > 1) {
                primeFactors.add(nn to 1)
            }
            for (primeFactor in primeFactors) {
                debug(primeFactor)
            }
        }

        val invs = LongArray(log(1e15, 2.0).toInt() + 10)
        debug(invs.size)
        for (i in invs.indices) {
            invs[i] = i.toLong().invMod2()
        }

        var ans = 1L

        fun solve(p: Long, e: Int): Long {
            val props = Array(k + 1) { LongArray(e + 1) { 0 } }
            val ev = Array(k + 1) { LongArray(e + 1) { 0 } }
            for (i in 0..e) {
                props[0][i] = 1
                ev[0][i] = p.powerMod(i)
            }
            for (kk in 1..k) {
