fun getDivisors(x : Int) : MutableList<Int> {
    val divisors = ArrayList<Int>()

    var d = 1
    while (d * d <= x) {
        if (x % d == 0) {
            if (d != 1) divisors.add(d)
            if (x != d) divisors.add(x / d)
        }

        ++d
    }

    return divisors
}

fun getPrimeDivisors(xx : Int) : MutableList<Int> {
    val divisors = ArrayList<Int>()

    var d = 2
    var x = xx
    while (d * d <= x) {
        if (x % d == 0) {
            divisors.add(d)
            while (x % d == 0) {
                x /= d
            }
        }

        ++d
    }

    if (x > 1) divisors.add(x)

    return divisors
}

