fun computeNextsAndPos(a: IntArray): Pair<IntArray, IntArray> {
    val n = a.size
    val pos = IntArray(n + 1) { n }
    val nexts = IntArray(n)
    for (i in a.indices.reversed()) {
        nexts[i] = pos[a[i]]
        pos[a[i]] = i
    }
    return nexts to pos
}

