fun solveB(n: Int, m: Int, timesRaw: List<Int>): Int {
    val times = timesRaw.sorted()
    val fullTaskTime = times.sum()
    val fullTaskScore = times.size + 1
    return (0..n).map { fullTasksCount ->
        val timeForFullTasks = fullTaskTime * fullTasksCount
        var timeLeft = m - timeForFullTasks
        var score = fullTasksCount * fullTaskScore
        if (timeLeft < 0) {
            0
        } else {
            val tasksLeft = n - fullTasksCount
            var currentSubTask = 0
            outer@ while (currentSubTask < times.size) {
                var currentTask = 0
                while (currentTask < tasksLeft) {
                    val timeSpent = times[currentSubTask]
                    val scoreToAdd = if (currentSubTask == times.size - 1) 2 else 1
                    if (timeSpent <= timeLeft) {
                        score += scoreToAdd
                        timeLeft -= timeSpent
                    } else {
                        break@outer
                    }
                    currentTask++
                }
                currentSubTask++
            }
            score
        }
    }.max()!!
}

