fun matmul(matA: Array<LongArray>, matB: Array<LongArray>, mod: Long): Array<LongArray> {
    val (x, y, z) = Triple(matA.size, matB[0].size, matA[0].size)
    val res = Array(x) { LongArray(y) }

    for (i in 0 until x) for (j in 0 until y) for (k in 0 until z) {
        res[i][j] = (res[i][j] + matA[i][k] * matB[k][j]) % mod
    }

    return res
}

