fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextLong()
    val k = scanner.nextLong()
    val a = scanner.nextLong()
    val b = scanner.nextLong()

    tailrec fun gcd(i: Long, j: Long): Long =
            if (i % j == 0L) j
            else gcd(j, i % j)

    val m = n * k
    var min = m
    var max = 1L

    outer@ for (i in arrayOf(a + b, a - b, -a + b, -a - b)) {
        for (j in 0L..n) {
            val s = j * k + i
            if (s in 1..m) {
                val g = gcd(m, s)
                val c = m / g
                min = min(min, c)
                max = max(max, c)
                if (min == 1L && max == m) break@outer
            }
        }
    }

    println("$min $max")
}

