fun dfs(v: Int): Long {
    if (v == 10)
        return get()
    if (arr[v] == 0)
        return dfs(v + 1)
    var res = 0L
    val q = arr[v]
    for (i in 1..q) {
        arr[v] = i
        s += i
        res += dfs(v + 1)
        s -= i
    }
    return res
}

fun get(): Long {
    var res = 1L
    for (i in 2 until s)
        res *= i
    res *= s - arr[0]
    for (i in 0 until 10)
        for (j in 2..arr[i])
            res /= j
    return res
}

