private fun f(x: Long):
        Long {
    return Math.max(0, (x * cb - nb) * pb) + Math.max(0, (x * cs - ns) * ps) +
            Math.max(0, (x * cc - nc) * pc)
}

private fun solve() {
    var recipe = readLn()
    val (nb_, ns_, nc_) = readInts()
