                cs++
            }
            else -> {
                cc++
            }
        }
    }

    var x = 0L
    var jump: Long = 100000000000000L // 1e14
    while (jump >= 1) {
        while (f(x + jump) <= r) {
            x += jump
        }
        jump /= 2
    }

    println(x)
}

