class FastScanner(private val input: InputStream = System.`in`) {
    private val sb = StringBuilder()
    private val buffer = ByteArray(4096)
    private var pos = 0
    private var size = 0

    fun nextLong(): Long {
        var c = skipWhitespace()

        val sign = if (c == '-'.toInt()) {
            c = read()
            -1
        } else 1

        var ans = 0L

        while (c > ' '.toInt()) {
            ans = ans * 10 + c - '0'.toInt()
            c = read()
        }

        return sign * ans
    }

    fun nextInt() = nextLong().toInt()

    private fun skipWhitespace(): Int {
        while (true) {
            val c = read()
            if (c > ' '.toInt() || c < 0) return c
        }
    }

    private fun read(): Int {
        while (pos >= size) {
            if (size < 0) return -1
            size = input.read(buffer, 0, buffer.size)
            pos = 0
        }
        return buffer[pos++].toInt()
    }
}

/**
 * @param mod prime number
 */
class Mod(val mod: Int) {
    init {
        assert(mod > 1)
    }

    inline fun Long.mod() = (this % mod).toInt().let { if (it < 0) it + mod else it }
    inline fun Long.unsafeMod() = (this % mod).toInt()
    infix inline fun Int.madd(other: Int) = plus(other.toLong()).unsafeMod()
    infix inline fun Int.mmul(other: Int) = times(other.toLong()).unsafeMod()

}

inline fun <T> withMod(mod: Int, action: Mod.() -> T): T = Mod(mod).action()

class PrimeSieve(maxN: Int) {
    private val minDivisor = IntArray(maxN + 1) { it }

    init {
        var n = 2
        while (n * n <= maxN) {
            if (n == minDivisor[n]) {
                (n * n..maxN step n).forEach {
                    minDivisor[it] = minDivisor[it].coerceAtMost(n)
                }
            }
            n++
        }
    }

    fun getMinDivisor(n: Int) = minDivisor[n]
}

