fun POW(N:Int ,P: Int ,mod : Int):Int{
    var x=1
    var n=N
    var p=P
    while (p > 0) {
        if (p%2 == 0) {
            n = (n.toLong()*n %mod).toInt()
            p /= 2
        } else {
            x = (x.toLong()*n %mod).toInt()
            p -= 1
        }
    }

    return x
}

