class Solver(input: InputStream, output: OutputStream) {

    companion object {
        private const val MAX_N = (1e6 + 10).toInt()
        private const val INF = (1e9 + 7).toInt()
        private const val MOD = (1e9 + 7).toInt()
        private const val INF_F = 1e-6
    }

    private val reader = Reader(input)
    private val writer = Writer(output)

    fun solve() {
        val n = reader.nextInt()
        val l = reader.nextInt()
        val r = reader.nextInt()
        val x = reader.nextInt()
        val c = reader.nextArrayInt(n).sorted()

        val bins = mutableListOf<String>()
        calcBin(bins, "", n)
        bins.sort()

        var ans = 0
        bins.forEach { bin ->
            if (bin.count { it == '1' } < 2) {
                return@forEach
            }
            val i = bin.indexOfFirst { it == '1' }
            val j = bin.indexOfLast { it == '1' }
            if (c[j] - c[i] < x) {
                return@forEach
            }
            val s = sum(c, i, j, bin)
            if (s in l..r) {
                ans++
            }
        }
        writer.println(ans)
    }

    private fun calcBin(bins: MutableList<String>, s: String, n: Int) {
        if (s.length == n) {
            bins.add(s)
            return
        }
        calcBin(bins, s + "1", n)
        calcBin(bins, s + "0", n)
    }

    private fun sum(c: List<Int>, i: Int, j: Int, bin: String): Int {
        var ans = 0
        for (x in i..j) {
            if (bin[x] == '1') {
                ans += c[x]
            }
        }
        return ans
    }

    fun clear() {
        writer.close()
    }
}

