fun getMinRest (a: List<Char>): Int {
    val inf = 100000
    tailrec fun go (xs: Queue<Char>, rest: Int, contest: Int, gym: Int): Int =
        if (xs.isEmpty()) min(rest, min(contest, gym))
        else {
            val newRest = min(rest, min(contest, gym)) + 1
            when (xs.poll()) {
                '0' -> go(xs, newRest, inf, inf)
                '1' -> go(xs, newRest, min(rest, gym), inf)
                '2' -> go(xs, newRest, inf, min(rest, contest))
                else -> go(xs, newRest, min(rest, gym), min(rest, contest))
            }
        }
    return go(LinkedList(a),0, inf, inf)
}

